module hist_precedence (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_op,     // 0 = add one sample to bin i_sel, 1 = remove one
    input  wire [1:0] i_sel,
    output reg  [5:0] total
);
    // histogram bins
    reg [3:0] bin0, bin1, bin2, bin3;

    // shadow of the earlier event: which bin got the very first sample
    reg [1:0] first_bin;
    reg       saw_sample;

    // scope arming register: high until the first removal aimed at first_bin
    reg       pre_purge;

    // shadow high-water mark of the first-sampled bin's count
    reg [3:0] hi_first;

    initial begin
        bin0       = 4'd0;
        bin1       = 4'd0;
        bin2       = 4'd0;
        bin3       = 4'd0;
        total      = 6'd0;
        first_bin  = 2'd0;
        saw_sample = 1'b0;
        pre_purge  = 1'b1;
        hi_first   = 4'd0;
    end

    wire [3:0] sel_cnt   = (i_sel == 2'd0) ? bin0 :
                           (i_sel == 2'd1) ? bin1 :
                           (i_sel == 2'd2) ? bin2 : bin3;

    wire [3:0] first_cnt = (first_bin == 2'd0) ? bin0 :
                           (first_bin == 2'd1) ? bin1 :
                           (first_bin == 2'd2) ? bin2 : bin3;

    wire do_add = i_ce && !i_op && (total != 6'd31) && (sel_cnt != 4'd15);
    wire do_rem = i_ce &&  i_op && (sel_cnt != 4'd0);
    wire purge  = i_ce &&  i_op && saw_sample && (i_sel == first_bin);

    wire armed  = pre_purge && saw_sample;

    // count the first-sampled bin will hold after this cycle
    wire [3:0] first_nxt =
        (do_add && !saw_sample)                          ? (sel_cnt   + 4'd1) :
        (do_add && saw_sample && (i_sel == first_bin))    ? (first_cnt + 4'd1) :
        (do_rem && saw_sample && (i_sel == first_bin))    ? (first_cnt - 4'd1) :
                                                            first_cnt;

    always @(posedge clk) begin
        if (i_ce) begin
            if (do_add) begin
                total <= total + 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (!saw_sample) begin
                    saw_sample <= 1'b1;
                    first_bin  <= i_sel;
                end
            end else if (do_rem) begin
                total <= total - 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 - 4'd1;
                    2'd1:    bin1 <= bin1 - 4'd1;
                    2'd2:    bin2 <= bin2 - 4'd1;
                    default: bin3 <= bin3 - 4'd1;
                endcase
            end

            if (purge)
                pre_purge <= 1'b0;

            if (do_add && !saw_sample)
                hi_first <= sel_cnt + 4'd1;
            else if (first_nxt > hi_first)
                hi_first <= first_nxt;
        end
    end

    // P: before any sample has ever been purged from the first-sampled bin,
    // the earlier arrival recorded in the shadow registers must still be
    // accounted for in the total-samples register.
    always @(posedge clk)
        if (armed) assert (total >= 6'd1);

    always @(posedge clk)
        if (armed) assert (total >= {2'b00, hi_first});
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg  [7:0] out_data
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

    assign in_ready = !skid_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
            armed      <= 1'b0;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else if (in_valid) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
                // downstream stalled: park the incoming word in the skid slot
                if (in_valid && !skid_valid) begin
                    skid_data  <= in_data;
                    skid_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

            if (accept) armed <= 1'b1;
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
    output wire [3:0] o_rows
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
    reg [3:0] rows;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
    initial rows    = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
            rows    <= 4'd0;
        end else if (i_ce) begin
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                        ready   <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                        ready   <= 1'b1;
                    end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                    ready   <= 1'b0;
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                end
            endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

// Priority arbiter for per-subchannel energy detect flags.
// Stage 0: combinational priority encode of the request vector.
// Stage 1: registered half-occupancy flags + priority-half decision.
// Stage 2: registered valid, registered index (only meaningful while valid),
//          and the two half-band grant flags.
module wifi_pri_grant (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output reg        o_vld,
    output reg  [2:0] o_idx,
    output reg        o_grant_lo,
    output reg        o_grant_hi
);
    // ---------------- stage 0: combinational priority encoder ------------
    wire req_lo = |i_req[3:0];
    wire req_hi = |i_req[7:4];

    reg [2:0] enc;
    always @(*) begin
        casez (i_req)
            8'b???????1: enc = 3'd0;
            8'b??????10: enc = 3'd1;
            8'b?????100: enc = 3'd2;
            8'b????1000: enc = 3'd3;
            8'b???10000: enc = 3'd4;
            8'b??100000: enc = 3'd5;
            8'b?1000000: enc = 3'd6;
            8'b10000000: enc = 3'd7;
            default:     enc = 3'd0;
        endcase
    end

    // ---------------- stage 1 registers ---------------------------------
    reg       s1_vld;
    reg       s1_req_lo;
    reg       s1_req_hi;
    reg       s1_pri_hi;   // upper half wins only when lower half is empty
    reg [2:0] s1_idx;

    initial begin
        s1_vld    = 1'b0;
        s1_req_lo = 1'b0;
        s1_req_hi = 1'b0;
        s1_pri_hi = 1'b0;
        s1_idx    = 3'd0;
        o_vld      = 1'b0;
        o_idx      = 3'd0;
        o_grant_lo = 1'b0;
        o_grant_hi = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // stage 1 capture
            s1_vld    <= req_lo | req_hi;
            s1_req_lo <= req_lo;
            s1_req_hi <= req_hi;
            s1_pri_hi <= req_hi && !req_lo;
            s1_idx    <= enc;

            // stage 2 capture
            o_vld      <= s1_vld;
            o_idx      <= s1_idx;
            o_grant_lo <= s1_vld && s1_req_lo;
            o_grant_hi <= s1_vld && s1_pri_hi;
        end
    end

    // P: while the encoded index is valid, the two half-band grants are
    //    never asserted together.
    always @(posedge clk)
        if (o_vld)
            assert (!(o_grant_lo && o_grant_hi));

endmodule

// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;

    wire [2:0] len_inc = (len == 3'd7) ? 3'd7 : (len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
        end else if (ce) begin
            case (st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                        st  <= S_IDENT;
                        len <= 3'd1;
                    end else if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= 3'd1;
                    end else if (cls == 2'd3) begin
                        st  <= S_STR;
                        len <= 3'd0;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                        st  <= S_IDENT;
                        len <= len_inc;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= len_inc;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                        st  <= S_IDLE;   // closing quote ends the token
                        len <= 3'd0;
                    end else if (cls == 2'd0) begin
                        st  <= S_ESC;    // backslash: next char is literal
                        len <= len;
                    end else begin
                        st  <= S_STR;
                        len <= len_inc;
                    end
                end
                S_ESC: begin
                    st  <= S_STR;
                    len <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                    st  <= S_IDLE;
                end
            endcase
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = v1;
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
    wire [2:0] delta = sync1 ^ sync2;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;

            if (bad_ev) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
    // 4-deep fixed-latency shift register: bit k = op issued k cycles ago
    reg [3:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;

    initial pipe  = 4'b0000;
    initial occ   = 3'd0;
    initial armed = 1'b0;

    assign o_retire = i_ce && pipe[3];
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
            pipe  <= 4'b0000;
            occ   <= 3'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], issue};
            occ  <= occ + (issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
            if (issue)
                armed <= 1'b1;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);
endmodule

// Stack pointer with a ratcheting high-water mark, plus a three-step
// arm -> start -> finish transaction FSM whose start step needs live data
// on the stack.
module hwm_chain_precedence (
    input  wire clk,
    input  wire ce,
    input  wire i_push,
    input  wire i_pop,
    input  wire i_arm,
    input  wire i_start,
    input  wire i_finish,
    input  wire i_clear,
    output wire o_finish,
    output wire [3:0] o_mark
);
    localparam [3:0] DEPTH = 4'd8;

    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_ARMED   = 2'd1;
    localparam [1:0] S_STARTED = 2'd2;
    localparam [1:0] S_DONE    = 2'd3;

    reg [3:0] sp;
    reg [3:0] hwm;      // high-water mark: never below sp, only ratchets up
    reg [1:0] stage;
    reg       saw_arm;
    reg       saw_start;
    reg       obs_en;    // sticky: set the first cycle a push is accepted

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial stage     = S_IDLE;
    initial saw_arm   = 1'b0;
    initial saw_start = 1'b0;
    initial obs_en    = 1'b0;

    wire do_push = ce && i_push && !i_pop && (sp <  DEPTH);
    wire do_pop  = ce && i_pop  && !i_push && (sp != 4'd0);

    wire [4:0] nxt_sp = {1'b0, sp} + 5'd1;

    // ---- stack pointer and high-water mark -------------------------------
    always @(posedge clk) begin
        if (do_push) begin
            sp     <= sp + 4'd1;
            obs_en <= 1'b1;
            if (nxt_sp > {1'b0, hwm})
                hwm <= nxt_sp[3:0];
        end else if (do_pop) begin
            sp <= sp - 4'd1;
        end
    end

    // ---- three-step chain: arm, then start, then finish ------------------
    always @(posedge clk) begin
        if (ce) begin
            case (stage)
                S_IDLE: begin
                    if (i_arm) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                end
                S_ARMED: begin
                    if (i_start && (sp != 4'd0)) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                end
                S_STARTED: begin
                    if (i_finish && (sp != 4'd0))
                        stage <= S_DONE;
                end
                default: begin
                    if (i_clear)
                        stage <= S_IDLE;
                end
            endcase
        end
    end

    assign o_finish = (stage == S_DONE);
    assign o_mark   = hwm;

    // Property: once the mark has been armed by a first push, a finish can
    // never be observed unless arm and start were both observed before it and
    // the high-water mark records that data was really on the stack.
    assert property (!obs_en || !o_finish ||
                     (saw_arm && saw_start && (hwm >= 4'd1)));
endmodule

module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
    output wire radio_rx   // receive chain owns the radio
);
    // one-hot MAC air-interface FSM:
    //   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_PREAMBLE,
    //   bit3 = TX_DATA, bit4 = ACK_WAIT
    reg [4:0] state;
    initial state = 5'b00001;

    wire s_idle  = state[0];
    wire s_rx    = state[1];
    wire s_txpre = state[2];
    wire s_tx    = state[3];
    wire s_ackw  = state[4];

    // next-state as a per-bit OR of its legal source states
    wire [4:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
    assign nxt[2] = s_idle & tx_req & ~rx_start;       // else start TX ramp
    assign nxt[3] = s_txpre;                           // preamble -> data
    assign nxt[4] = s_tx;                              // data -> wait for ACK

    always @(posedge clk) begin
        if (rst)
            state <= 5'b00001;
        else if (step)
            state <= nxt;
    end

    // decoded radio ownership
    assign radio_tx = s_txpre | s_tx;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
    end

    wire [3:0] nxt      = cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
        end else if (i_ce) begin
            pipe    <= { pipe[STAGES-2:0], (i_launch && armed) };
            cnt     <= cnt + ((i_launch && armed) ? 3'd1 : 3'd0)
                           - (pipe[STAGES-1]    ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

endmodule

// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
    output wire busy
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    assign busy = (outst != 3'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);

    wire do_issue  = ce && issue && (outst < WINDOW);
    wire do_retire = ce && (outst != 3'd0) && (retire || force_ret);

    wire [2:0] outst_n = do_issue ? (do_retire ? outst : outst + 3'd1)
                                  : (do_retire ? outst - 3'd1 : outst);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;

        if (do_issue || do_retire) begin
            // any scoreboard event restarts (or clears) the deadline
            if (outst_n == 3'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule: nothing granted in the two most recent slots
    wire allow = (win[1:0] == 2'b00);
    wire g     = ce && req && allow;

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win  <= {win[6:0], g};
            ones <= ones + (g ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred

    wire       tick     = (timer == PERIOD);
    wire       do_grant = ce && req && (tokens != 4'd0);
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
        grant_q    = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
            grant_q    <= 1'b0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

            if (tick)
                saw_refill <= 1'b1;

            case ({tick, do_grant})
                2'b10:   tokens <= refilled;
                2'b01:   tokens <= tokens - 4'd1;
                2'b11:   tokens <= (refilled == 4'd0) ? 4'd0 : (refilled - 4'd1);
                default: tokens <= tokens;
            endcase
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

module boot_chunk_loader (
    input  wire i_clk,
    input  wire i_ce,      // idle when low: no state changes at all
    input  wire i_start,   // accept a fresh load request
    output wire o_expired,
    output wire o_done,
    output wire [7:0] o_total
);
    // A chunk loader that accumulates 3 bytes of payload per accepted step.
    // The accumulator is kept in two carry-save halves (acc_a, acc_b) whose
    // sum is the true byte total; `total` is the redundant true running sum.
    localparam [3:0] TMAX  = 4'd8;   // countdown granted to a request
    localparam [7:0] LIMIT = 8'd24;  // bytes that constitute completion

    reg [7:0] acc_a;
    reg [7:0] acc_b;
    reg [7:0] total;
    reg [3:0] timer;
    reg       pv;

    initial acc_a = 8'd0;
    initial acc_b = 8'd0;
    initial total = 8'd0;
    initial timer = TMAX;
    initial pv    = 1'b0;

    wire [7:0] csum    = acc_a + acc_b;   // halves recombined
    wire       expired = (timer == 4'd0);

    assign o_expired = expired;
    assign o_done    = (csum >= LIMIT);
    assign o_total   = total;

    always @(posedge i_clk)
        pv <= 1'b1;

    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_start) begin
                acc_a <= 8'd0;
                acc_b <= 8'd0;
                total <= 8'd0;
                timer <= TMAX;
            end else if (timer != 4'd0) begin
                acc_a <= acc_a + 8'd1;   // low carry-save half
                acc_b <= acc_b + 8'd2;   // high carry-save half
                total <= total + 8'd3;   // true total
                timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never expire while the
    // load request is still outstanding.  Edge form: the cycle `expired` rises,
    // the recombined accumulator must already show a completed transfer.
    always @(posedge i_clk)
        if (pv)
            assert (!$rose(expired) || (acc_a + acc_b >= LIMIT));
endmodule

// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;

    // precedence shadow: voted code at the previous advance
    reg [2:0] prev_voted = 3'd0;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
                prev_voted <= code_in - 3'd1;
            end else begin
                shadow_a   <= shadow_a + 3'd1;
                shadow_b   <= shadow_b + 3'd1;
                shadow_c   <= shadow_c + 3'd1;
                prev_voted <= voted;
            end
        end
    end

    always @(posedge clk) begin
        if (r_stop)
            win <= 1'b0;
        else if (q_start)
            win <= 1'b1;
    end

    // Property: inside the monitoring window, the voted step code must be the
    // immediate successor of the code recorded earlier in prev_voted.
    always @(posedge clk)
        assert (!win || (voted == prev_voted + 3'd1));

endmodule

// Four-phase req/ack handshake engine with a busy mirror and
// per-client ownership / response routing tags.
//
//   phase 0 : idle            (req=0, ack=0)
//   phase 1 : req asserted    (req=1, ack=0)
//   phase 2 : ack observed    (req=1, ack=1)
//   phase 3 : req withdrawn   (req=0, ack=1)  -> waits for ack to drop
//
// busy is a separate register that mirrors "phase != 0"; the start path is
// gated on !busy only, exactly as a real controller would do.
module fourphase_owner (
    input  wire clk,
    input  wire i_ce,        // idle condition: nothing moves when low
    input  wire i_req,       // a client wants the channel
    input  wire i_sel,       // which client (0 -> A, 1 -> B)
    input  wire i_ack_in,    // ack wire coming back from the target
    output wire o_busy,
    output wire o_req,
    output wire o_ack
);

    reg [1:0] phase;
    reg       busy;
    reg       req;
    reg       ack;
    reg       own_a, own_b;   // who currently owns the channel
    reg       resp_a, resp_b; // where the response will be routed
    reg       virgin;         // high until the first handshake ever completes

    initial phase  = 2'd0;
    initial busy   = 1'b0;
    initial req    = 1'b0;
    initial ack    = 1'b0;
    initial own_a  = 1'b0;
    initial own_b  = 1'b0;
    initial resp_a = 1'b0;
    initial resp_b = 1'b0;
    initial virgin = 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!busy) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                    if (i_sel)
                        own_b <= 1'b1;
                    else
                        own_a <= 1'b1;
                end
            end else begin
                case (phase)
                    2'd1: if (i_ack_in) begin
                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
    // up counter and down counter stepped by the same enable; their sum is 20
    reg [4:0] up;
    reg [4:0] dn;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;

    initial up          = 5'd0;
    initial dn          = 5'd20;
    initial mark        = 1'b0;
    initial before_done = 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
            end else begin
                up   <= up + 5'd1;
                dn   <= dn - 5'd1;
                mark <= mark | (up == 5'd9);
            end
        end
    end

    // gray view of the shadow binary up counter (clock-domain-crossing flavour)
    assign o_gray    = up ^ (up >> 1);
    assign o_drained = (dn == 5'd0);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

module rr_arb_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    input  wire       arm,
    input  wire       clr,
    output reg  [3:0] gnt
);
    // round-robin arbiter state
    reg [1:0] ptr;       // last granted line index
    // precedence shadow of the previous grant decision
    reg [3:0] prev_gnt;
    reg [1:0] prev_ptr;
    reg [3:0] hist;      // lines the pointer has rested on since arming
    reg       armed;     // window register: set by arm, cleared by clr

    initial begin
        gnt      = 4'b0000;
        ptr      = 2'd0;
        prev_gnt = 4'b0000;
        prev_ptr = 2'd0;
        hist     = 4'b0000;
        armed    = 1'b0;
    end

    // rotating priority: start just past the last grant
    wire [1:0] c0 = ptr + 2'd1;
    wire [1:0] c1 = ptr + 2'd2;
    wire [1:0] c2 = ptr + 2'd3;
    wire [1:0] c3 = ptr;

    reg       sel_val;
    reg [1:0] sel_idx;
    always @(*) begin
        if (req[c0])      begin sel_val = 1'b1; sel_idx = c0;   end
        else if (req[c1]) begin sel_val = 1'b1; sel_idx = c1;   end
        else if (req[c2]) begin sel_val = 1'b1; sel_idx = c2;   end
        else if (req[c3]) begin sel_val = 1'b1; sel_idx = c3;   end
        else              begin sel_val = 1'b0; sel_idx = 2'd0; end
    end

    // one-hot (or all-zero) next grant, never on a non-requesting line
    wire [3:0] nxt = sel_val ? (4'b0001 << sel_idx) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            gnt      <= 4'b0000;
            ptr      <= 2'd0;
            prev_gnt <= 4'b0000;
            prev_ptr <= 2'd0;
            hist     <= 4'b0000;
            armed    <= 1'b0;
        end else begin
            if (ce) begin
                gnt      <= nxt;
                if (sel_val) ptr <= sel_idx;
                prev_gnt <= gnt;
                prev_ptr <= ptr;
                hist     <= hist | (4'b0001 << ptr);
            end
            // opening the observation window restarts the shadow record
            if (arm && !armed) begin
                armed    <= 1'b1;
                prev_gnt <= 4'b0000;
                prev_ptr <= 2'd0;
                hist     <= 4'b0000;
            end else if (clr) begin
                armed <= 1'b0;
            end
        end
    end

    // after arm, until clr (which may never come): a recorded grant must have
    // been preceded by the pointer standing on that very line
    always @(posedge clk) begin
        if (armed)
            assert (prev_gnt == 4'b0000 || prev_gnt == (4'b0001 << prev_ptr));
        if (armed)
            assert (prev_gnt == 4'b0000 || (hist & prev_gnt) != 4'b0000);
    end
endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

    wire have_credit = (credits != 4'd0);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
    wire do_grant = i_ce && have_credit && any_req;
    wire do_ret   = i_ce && ret && (outstanding != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

            if (do_grant && !do_ret) begin
                credits     <= credits - 4'd1;
                outstanding <= outstanding + 4'd1;
            end else if (!do_grant && do_ret) begin
                credits     <= credits + 4'd1;
                outstanding <= outstanding - 4'd1;
            end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
    output reg        armed    // sticky: set the first time a request is taken
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // accept a new request: index and one-hot come from the encoder
                vld   <= 1'b1;
                idx   <= enc;
                oh    <= iso;
                armed <= 1'b1;
            end else if (vld) begin
                // no new request: age the standing grant round-robin style
                idx <= idx + 2'd1;
                oh  <= {oh[2:0], oh[3]};
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
    output wire [3:0] o_remain
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
        end else if (i_ce) begin
            if (i_kick) begin
                cnt <= 4'd0;
                rem <= TIMEOUT;
            end else begin
                if (cnt < TIMEOUT)
                    cnt <= cnt + 4'd1;
                if (rem != 4'd0)
                    rem <= rem - 4'd1;
            end

            if (i_ack)
                latched <= 1'b0;
            else if (!i_kick && (rem == 4'd1))
                latched <= 1'b1;
        end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);
endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
    reg [3:0] win;         // last four bits received, MSB = oldest

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
        win    = 4'b0000;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            prog   <= nprog;
            hot    <= nhot;
            win    <= {win[2:0], i_bit};
            detect <= (nprog == 3'd4);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end
endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
    output wire       o_full
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
        end else if (take) begin
            case (i_sel)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 4'd1;
        end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
            count <= count + 3'd1;
        end else if (do_pop) begin
            // tail slides down into the head slot
            v0    <= v1;
            d0    <= d1;
            v1    <= 1'b0;
            count <= count - 3'd1;
        end
        // i_push = i_pop = 0 : the buffer idles, all state held
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
    // 4-bit maximal-length LFSR (x^4 + x^3 + 1), period 15, never all-zeros.
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;

    wire [3:0] lf_next    = {lf[2:0], lf[3] ^ lf[2]};

    // A pseudo-random hall call is issued unless the LFSR is in its
    // single low state 4'b0001.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    wire [3:0] set_mask   = new_call ? (4'b0001 << call_floor) : 4'b0000;
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
        end else if (step) begin
            lf      <= lf_next;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= new_call ? 3'd0 : (dry_cnt + 3'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
    reg       win;   // window register: opened by a job start, closed at retire

    initial state = S_IDLE;
    initial dec   = 5'b00001;
    initial win   = 1'b0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
            win   <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
            dec   <= ndec;
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
            else if (state == S_WRITE)
                win <= 1'b0;               // R: the job retires
        end
    end

    assign o_phase = dec;
    assign o_busy  = win;

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));
endmodule

module pingpong_rotbuf (
    input  wire        clk,
    input  wire        step,      // enable / idle when low
    input  wire [15:0] din,
    input  wire [3:0]  amt,
    output reg  [15:0] dout,
    output wire        wr_half,
    output wire        rd_half
);
    // ------------------------------------------------------------------
    // one-cycle barrel rotator (staged shift-by-1/2/4/8 collapses to this)
    // ------------------------------------------------------------------
    wire [31:0] dbl = {din, din};
    wire [15:0] rot = dbl[15:0] >> amt | dbl[31:16] << (16 - amt);

    // ------------------------------------------------------------------
    // ping-pong double buffer: 2 halves of 4 words.
    // address = {half_select, index}
    // ------------------------------------------------------------------
    reg [2:0] waddr;
    reg [2:0] raddr;
    reg [15:0] mem [0:7];
    reg        pv;

    integer i;
    initial begin
        waddr = 3'b000;   // writer starts in half 0
        raddr = 3'b100;   // reader starts in half 1
        dout  = 16'h0000;
        pv    = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 16'h0000;
    end

    assign wr_half = waddr[2];
    assign rd_half = raddr[2];

    // each side flips its own half when its own index field wraps
    wire wswap = step && (waddr[1:0] == 2'b11);
    wire rswap = step && (raddr[1:0] == 2'b11);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (step) begin
            mem[waddr] <= rot;
            dout       <= mem[raddr];

            waddr <= {wswap ? ~waddr[2] : waddr[2], waddr[1:0] + 2'b01};
            raddr <= {rswap ? ~raddr[2] : raddr[2], raddr[1:0] + 2'b01};
        end
    end

    // ------------------------------------------------------------------
    // P: whenever the writer migrates up into the high half, the reader
    //     must at that moment be sitting in the low half.
    // ------------------------------------------------------------------
    always @(posedge clk)
        if (pv && $rose(waddr[2]))
            assert (raddr[2] == 1'b0);
endmodule

module debounce_hist_arm (
    input  wire i_clk,
    input  wire i_ce,
    input  wire i_raw,
    output wire o_clean,
    output wire o_armed,
    output wire o_settled
);
    // K identical consecutive samples are required before the clean output flips.
    localparam [2:0] KC = 3'd4;
    localparam       HW = 8;

    reg [2:0]      cnt;     // stability counter, saturates at KC
    reg            sample;  // current candidate level being timed
    reg            clean;   // debounced (committed) level
    reg [HW-1:0]   hist;    // raw sample history, hist[0] is the newest sample
    reg            armed;   // sticky: set the first time the filter commits

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
        end else if (cnt < KC) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
                clean <= sample;
                armed <= 1'b1;
            end
        end
    end

    assign o_clean   = clean;
    assign o_armed   = armed;
    assign o_settled = (cnt == KC);

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
            count   <= nxt;
            // sticky until the decoder is kicked
            expired <= kick ? 1'b0 : (expired || (nxt == LIMIT));
            healthy <= (nxt < WARN);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;

    wire accept = start && !armed && (len != 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                beats    <= len;
                req_len  <= len;      // shadow capture of the earlier event
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
            end else if (busy) begin
                beats    <= beats - 4'd1;
                done_cnt <= done_cnt + 4'd1;
                busy     <= (beats != 4'd1);
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);
endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
    output wire       o_period_start
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;

    wire wrap = (cnt == PERIOD_M1);

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
                duty_act <= duty_pend;
                hi_left  <= duty_pend;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
            if (load)
                duty_pend <= duty_in;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    wire [3:0] goal_bin = bin + K;

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
            gray <= gray_nxt;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

module dma_copier_chain (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_clear,
    input  wire [3:0] i_len,
    output wire       o_done,
    output wire       o_busy,
    output wire       o_err
);
    // phase slice codes (gray-ish), each with its stored parity bit
    localparam [1:0] PH_IDLE  = 2'b00,   // parity 0
                     PH_ARMED = 2'b01,   // parity 1
                     PH_BUSY  = 2'b11,   // parity 0
                     PH_DONE  = 2'b10;   // parity 1

    // parity-protected register slice holding the engine phase
    reg [1:0] phase   = PH_IDLE;
    reg       par     = 1'b0;

    // descriptor word counter
    reg [3:0] count   = 4'd0;

    // chain history bits: arm happened, start happened
    reg       h_arm   = 1'b0;
    reg       h_start = 1'b0;

    // slice checker: stored parity must match stored phase
    wire slice_bad = (par != (^phase));

    always @(posedge clk) begin
        if (i_ce) begin
            if (slice_bad) begin
                // corrupted descriptor slice: abort, report done immediately
                phase <= PH_DONE;
                par   <= 1'b1;
            end else begin
                case (phase)
                PH_IDLE:
                    if (i_arm) begin
                        phase   <= PH_ARMED;
                        par     <= 1'b1;
                        count   <= i_len;
                        h_arm   <= 1'b1;
                    end
                PH_ARMED:
                    if (i_start) begin
                        phase   <= PH_BUSY;
                        par     <= 1'b0;
                        h_start <= 1'b1;
                    end
                PH_BUSY:
                    if (count == 4'd0) begin
                        phase <= PH_DONE;
                        par   <= 1'b1;
                    end else begin
                        count <= count - 4'd1;
                    end
                PH_DONE:
                    if (i_clear) begin
                        phase <= PH_IDLE;
                        par   <= 1'b0;
                    end
                endcase
            end
        end
    end

    assign o_done = (phase == PH_DONE);
    assign o_busy = (phase == PH_BUSY);
    assign o_err  = slice_bad;

    // chain precedence, globally: a finish can never be seen unless the
    // arm step and then the start step were actually taken
    always @(posedge clk)
        if (phase == PH_DONE) assert (h_arm);

    always @(posedge clk)
        if (phase == PH_DONE) assert (h_start);
endmodule

module lock_arbiter_occ (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    output wire [3:0] o_grant,
    output wire       o_busy
);
    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

    // fixed priority: channel 0 highest
    wire [3:0] pri_grant = i_req[0] ? 4'b0001 :
                           i_req[1] ? 4'b0010 :
                           i_req[2] ? 4'b0100 :
                           i_req[3] ? 4'b1000 : 4'b0000;

    // while locked, the current winner keeps the bus as long as it still asks
    wire holding = busy && lock && ((grant & i_req) != 4'b0000);

    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
        end else if (i_ce) begin
            if (busy) begin
                if (!holding) begin
                    // winner released: drop the grant and free the slot
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                    occ   <= occ - 3'd1;
                end
            end else if (any_req) begin
                // bus free: award it and lock it
                grant <= pri_grant;
                lock  <= 1'b1;
                occ   <= occ + 3'd1;
            end
        end
    end

    assign o_grant = grant;
    assign o_busy  = busy;

    // at most one grant may be outstanding at any time
    always @(*)
        assert (occ <= 3'd1);
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
    output reg  [2:0] occ        // queries in flight
);

    reg [3:0] pipe;              // fixed-latency valid shift register
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
    end

    assign retire = pipe[3];
    assign full   = (occ == 3'd4);

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
            pipe <= {pipe[2:0], issue};

            // occupancy bookkeeping: +1 on issue, -1 on retire
            occ  <= occ + {2'b00, issue} - {2'b00, pipe[3]};

            // shadow register for the earlier event
            if (issue) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
            en_load   <= (phase == 3'd4);
            en_sample <= (cnt   == 3'd4);
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
    output wire       o_in_ready
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

    wire [1:0] in_code  = src_phase + 2'd1;
    wire       in_ready = !skid_valid;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
                end else if (in_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
                if (out_room)
                    skid_valid <= 1'b0;
            end else if (in_valid && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
    output reg  [3:0] count
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full/empty derived from the POINTERS, not from the counter ----
    assign full  = ((wptr - rptr) == 3'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;

    always @(posedge clk) begin
        if (do_push) begin
            mem[wptr] <= alu;
            wptr      <= wptr + 3'd1;
        end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

module fourphase_occupancy (
    input  wire       clk,
    input  wire       i_ce,          // global enable / idle when low
    input  wire       start,         // master wants a new transaction
    input  wire       dev_ack_ready, // device is ready to raise ack
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [2:0]  occ,           // outstanding-transaction occupancy
    output reg        armed
);
    // four-phase handshake sequencer:
    //   phase 0 : idle        (req=0, ack=0)
    //   phase 1 : req raised  (req=1, ack=0)
    //   phase 2 : ack raised  (req=1, ack=1)
    //   phase 3 : req dropped (req=0, ack=1)   -> ack drops, back to idle
    reg [1:0] phase;
    reg       pv;

    initial begin
        phase = 2'd0;
        req   = 1'b0;
        ack   = 1'b0;
        busy  = 1'b0;
        occ   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                2'd0: begin
                    // request may only be launched from idle
                    if (start) begin
                        req   <= 1'b1;
                        busy  <= 1'b1;      // busy mirrors the phase
                        occ   <= occ + 3'd1;
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    // req is held; it may not drop until ack rises
                    if (dev_ack_ready) begin
                        ack   <= 1'b1;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    // ack seen -> now req is allowed to drop
                    req   <= 1'b0;
                    phase <= 2'd3;
                end
                2'd3: begin
                    // ack drops, transaction retires
                    ack   <= 1'b0;
                    busy  <= 1'b0;
                    occ   <= occ - 3'd1;
                    armed <= 1'b1;   // sticky: first completed handshake arms
                    phase <= 2'd0;
                end
            endcase
        end
    end

    // Property: once at least one handshake has completed (armed), every time the
    // busy flag rises the occupancy must not exceed two.
    always @(posedge clk)
        if (pv && armed && $rose(busy))
            assert (occ <= 3'd2);
endmodule

// Tile-render pixel pipeline pacing: a /5 phase counter feeding a /4 row
// counter, plus an accumulator of paced cycles within one tile (20 steps)
// and a high-water mark of that accumulator.
module tilepipe_div (
    input  wire i_clk,
    input  wire i_ce,        // pipeline advance / idle when low
    output wire o_tile_en,   // divided-enable pulse: fires when the chain wraps
    output wire [4:0] o_peak
);
    // ---- phase counter (divide by 5) ----
    reg [2:0] phase;
    initial   phase = 3'd0;

    // ---- row counter (divide by 4 of the phase wrap) ----
    reg [1:0] row;
    initial   row = 2'd0;

    // ---- accumulated paced cycles inside the current tile ----
    reg [4:0] total;
    initial   total = 5'd0;

    // ---- high-water mark of the accumulator (monotone) ----
    reg [4:0] peak;
    initial   peak = 5'd0;

    reg pv;
    initial pv = 1'b0;

    wire ph_wrap  = (phase == 3'd4);
    wire row_wrap = ph_wrap && (row == 2'd3);

    // accumulator is cleared only by the divided-enable pulse, never by its
    // own value
    wire [4:0] nxt_total = row_wrap ? 5'd0 : (total + 5'd1);

    always @(posedge i_clk) begin
        pv <= 1'b1;
        if (i_ce) begin
            phase <= ph_wrap ? 3'd0 : (phase + 3'd1);
            if (ph_wrap)
                row <= row_wrap ? 2'd0 : (row + 2'd1);
            total <= nxt_total;
            if (nxt_total > peak)
                peak <= nxt_total;
        end
    end

    assign o_tile_en = i_ce && row_wrap;
    assign o_peak    = peak;

    // P: the high-water mark of the tile accumulator never climbs past 19,
    // even though the register is 5 bits wide (would allow 31): once it has
    // reached 19 it must never change again.
    always @(posedge i_clk)
        if (pv && ($past(peak) == 5'd19))
            assert ($stable(peak));
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

    always @(posedge clk) begin
        if (i_ce) begin
            // source pointer
            wbin  <= wbin + (i_incr ? 4'd1 : 4'd0);

            // synchronizer chain
            sync1 <= wgray;
            sync2 <= sync1;

            // shadow binary chain, structurally parallel to the chain above
            b1    <= wbin;
            b2    <= b1;

            // monitor
            last_delta <= delta;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
            if (sync1 != sync2)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module fifo_occ_flags (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_wr,
    input  wire       i_rd,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_full,
    output wire       o_empty
);
    // depth-8 FIFO: 4-bit pointers (extra MSB for wrap), separate occupancy count
    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];
    reg [7:0] dout;

    integer i;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        dout  = 8'd0;
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 8'd0;
    end

    // full is derived from the occupancy counter,
    // empty is derived from the pointers
    assign o_full  = (count == 4'd8);
    assign o_empty = (wptr == rptr);

    wire do_wr = i_wr && !o_full;
    wire do_rd = i_rd && !o_empty;

    assign o_data = dout;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
            dout  <= 8'd0;
        end else begin
            if (do_wr) begin
                mem[wptr[2:0]] <= i_data;
                wptr <= wptr + 4'd1;
            end
            if (do_rd) begin
                dout <= mem[rptr[2:0]];
                rptr <= rptr + 4'd1;
            end
            if (do_wr && !do_rd)
                count <= count + 4'd1;
            else if (!do_wr && do_rd)
                count <= count - 4'd1;
        end
    end

    // P: the FIFO is never reported full and empty at the same time
    always @(posedge clk)
        assert (!(o_full && o_empty));
endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
    output wire o_grant
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
    reg         pv;

    initial win   = 0;
    initial ones  = 0;
    initial armed = 0;
    initial pv    = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
    wire [2:0] eff      = ones - retiring;

    // rate decision is taken from the mirrored count, not from the window
    wire allow = i_req && (eff < LIMIT);

    assign o_grant = i_ce && allow;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
            armed <= 0;
        end else if (i_ce) begin
            win  <= { win[W-2:0], allow };
            ones <= ones - retiring + (allow ? 3'd1 : 3'd0);
            if (allow)
                armed <= 1'b1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;

    wire tick     = (tick_cnt == 2'd0);
    wire do_grant = pending && (tokens != 3'd0);

    assign grant   = i_ce && do_grant;
    assign expired = pending && (deadline == 4'd0);

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (do_grant && tick)
            tokens <= tokens;                 // one out, one in
        else if (do_grant)
            tokens <= tokens - 3'd1;
        else if (tick && (tokens < BURST))
            tokens <= tokens + 3'd1;
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
endmodule

module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
    output wire       o_sel
);
    localparam [1:0] LAST = 2'd3;

    // ping-pong double buffer: one half owned by the rasterizer (writer),
    // the other half owned by the shader fetch port (reader)
    reg       sel;                 // master ping-pong select bit
    reg       wr_half, rd_half;    // half currently addressed by each port
    reg [1:0] wcnt, rcnt;          // offset inside the owned half
    reg       wr_full, rd_empty;   // per-half handshake flags
    reg [7:0] mem [0:7];
    integer   i;

    initial begin
        sel     = 1'b0;
        wr_half = 1'b0;
        rd_half = 1'b1;
        wcnt    = 2'd0;
        rcnt    = 2'd0;
        wr_full = 1'b0;
        rd_empty= 1'b1;
        rd_data = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire [2:0] wr_addr = {wr_half, wcnt};
    wire [2:0] rd_addr = {rd_half, rcnt};

    wire w_step = i_ce && wr_en && !wr_full;
    wire r_step = i_ce && rd_en && !rd_empty;
    wire swap   = i_ce && wr_full && rd_empty;

    assign o_sel = sel;

    always @(posedge clk) begin
        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
        end else if (swap) begin
            sel      <= ~sel;
            wr_half  <= ~sel;   // writer takes the freshly drained half
            rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
        end else begin
            if (w_step) begin
                mem[wr_addr] <= wr_data;
                wcnt <= wcnt + 2'd1;
                if (wcnt == LAST) wr_full <= 1'b1;
            end
            if (r_step) begin
                rd_data <= mem[rd_addr];
                rcnt <= rcnt + 2'd1;
                if (rcnt == LAST) rd_empty <= 1'b1;
            end
        end
    end

    // P: whenever both ports perform an access in the same cycle they never
    // touch the same buffer location
    always @(posedge clk)
        if (i_ce && wr_en && rd_en && !wr_full && !rd_empty)
            assert (wr_addr != rd_addr);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
        end else if (i_ce) begin
            pos <= pos + 8'd1;
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
                if (wd != LIMIT)
                    wd <= (wd > 4'd4) ? (wd - 4'd4) : 4'd0;
            end else begin
                // no progress this step: count up and saturate at LIMIT
                if (wd != LIMIT) begin
                    wd <= wd + 4'd1;
                    if ((wd + 4'd1) == LIMIT)
                        expired <= 1'b1;
                end
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);
endmodule

module arb_lock_pending (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire [3:0] req,     // new requests, latched into pend
    input  wire       rel,     // current owner releases the lock
    output wire [3:0] grant,
    output wire [2:0] occupancy
);
    // pending request bitmap and its redundant occupancy counter
    reg [3:0] pend  = 4'b0000;
    reg [2:0] pcnt  = 3'd0;
    // fixed-priority arbiter with a lock bit freezing the winner
    reg       lock  = 1'b0;
    reg [1:0] owner = 2'd0;
    reg       pv    = 1'b0;   // past-valid

    // fixed priority: lowest index wins
    wire [1:0] pick = pend[0] ? 2'd0 :
                      pend[1] ? 2'd1 :
                      pend[2] ? 2'd2 : 2'd3;
    wire       any  = |pend;

    // service completion: the locked owner releases, its pending bit retires
    wire       do_clr   = ce && lock && rel;
    wire [3:0] clr_mask = do_clr ? (4'b0001 << owner) : 4'b0000;
    // only genuinely new requests are inserted
    wire [3:0] set_mask = ce ? (req & ~pend & ~clr_mask) : 4'b0000;
    wire [2:0] nset     = set_mask[0] + set_mask[1] + set_mask[2] + set_mask[3];

    assign grant     = lock ? (4'b0001 << owner) : 4'b0000;
    assign occupancy = pcnt;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            pend <= (pend | set_mask) & ~clr_mask;
            pcnt <= pcnt + nset - (do_clr ? 3'd1 : 3'd0);
            if (lock) begin
                if (rel)
                    lock <= 1'b0;      // frozen winner until it releases
            end else if (any) begin
                lock  <= 1'b1;
                owner <= pick;
            end
        end
    end

    // P: if the pending bitmap did not change, the occupancy must not have
    // changed either, and the occupancy stays within its real bound of 4.
    always @(posedge clk)
        if (pv && $stable(pend))
            assert ($stable(pcnt) && (pcnt <= 3'd4));
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;

    initial st  = 5'b00001;
    initial cnt = 4'd0;
    initial arm = 1'b0;
    initial pv  = 1'b0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

    reg [4:0] nst;
    reg [3:0] ncnt;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
        if (st[S_IDLE]) begin
            if (is_q) begin
                nst  = 5'b01000;   // open quote: enter string, fresh escape count
                ncnt = 4'd0;
            end else if (is_dig)
                nst = 5'b00100;
            else if (is_alp)
                nst = 5'b00010;
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
        end else if (st[S_STR]) begin
            if (is_q) begin
                nst  = 5'b00001;   // close quote: escape count retired
                ncnt = 4'd0;
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
            ncnt = (cnt == 4'd8) ? 4'd8 : (cnt + 4'd1);
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
    output reg        vld_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load

    initial begin
        cnt       = 3'd0;
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
        out_r     = 1'b0;
        vld_r     = 1'b0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

    // ---------------- comparator: high exactly while cnt < duty ----------------
    wire out  = ({1'b0, cnt} < duty);
    wire wrap = (cnt == 3'd7);

    always @(posedge clk) begin
        if (ce) begin
            cnt   <= cnt + 3'd1;   // free-running, wraps 7 -> 0
            out_r <= out;          // registered output stage
            vld_r <= vld;
            if (wrap) begin
                // period boundary: latch the new duty and its shadow flag together
                duty      <= duty_req;
                shadow_nz <= (duty_req != 4'd0);
                hi_cnt    <= 4'd0;
                if (duty_req == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
                hi_cnt <= hi_cnt + (out ? 4'd1 : 4'd0);
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
        end else if (step) begin
            inflight <= {inflight[2:0], req};
            cnt      <= cnt + {2'b00, req} - {2'b00, retire};
        end
    end

    assign f_idle = (cnt == 3'd0);
    assign f_full = (cnt == 3'd4);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module elastic_two_entry (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire       o_valid,
    output wire       o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);

    // ---- two-entry elastic buffer -------------------------------------
    // one valid flag per slot, plus head/tail slot selectors.
    reg        v0, v1;      // slot occupancy flags
    reg        head, tail;  // which slot is read / written next
    reg [7:0]  d0, d1;      // slot payloads
    reg [2:0]  count;       // redundant occupancy counter

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial head  = 1'b0;
    initial tail  = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;

    // status is derived from the FLAGS, not from the counter
    assign o_full  = v0 && v1;
    assign o_valid = v0 || v1;
    assign o_data  = head ? d1 : d0;
    assign o_count = count;

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  &&  o_valid;

    // idle condition: i_push == 0 && i_pop == 0 leaves all state alone
    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (tail == 1'b0) begin
                    v0 <= 1'b1;
                    d0 <= i_data;
                end else begin
                    v1 <= 1'b1;
                    d1 <= i_data;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                head <= ~head;
            end

            count <= count + (do_push ? 3'd1 : 3'd0)
                            - (do_pop  ? 3'd1 : 3'd0);
        end
    end

    // ---- property: while the buffer holds anything, the occupancy
    //      counter never exceeds the two-entry depth (the register is
    //      three bits wide, so 3..7 are representable).
    always @(posedge i_clk)
        if (o_valid)
            assert (count <= 3'd2);

endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
    output wire o_busy
);
    localparam [3:0] TOTAL = 4'd3;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    initial begin
        free_cr    = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
    end

    wire do_flush = i_ce &&  i_flush;
    wire do_arm   = i_ce && !i_flush && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && i_done  && (busy_cr  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
            free_cr    <= TOTAL;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
        end else if (i_ce) begin
            free_cr  <= free_cr  - do_arm   + do_fin;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
    output reg        done
);
    localparam [3:0] MAXSTEP = 4'd10;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
    wire last     = (progress + 4'd1 >= MAXSTEP);

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
            deadline <= MAXSTEP;
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
        end else if (step) begin
            // saturating up-counter: clamps at MAXSTEP, never reaches 4'd15
            progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
            deadline <= (deadline == 4'd0)    ? 4'd0    : deadline - 4'd1;
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

module hwm_stack_ptr (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_deep,
    output wire [3:0] o_mark,
    output wire [3:0] o_sp
);
    localparam [3:0] THRESH = 4'd4;

    // stack pointer and its high-water mark
    reg [3:0] sp;
    reg [3:0] hwm;
    reg       mark_deep;   // registered "mark has crossed THRESH" flag
    reg       pv;          // past-valid

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial mark_deep = 1'b0;
    initial pv        = 1'b0;

    wire do_push = i_ce && i_push && !i_pop && (sp != 4'hF);
    wire do_pop  = i_ce && i_pop  && !i_push && (sp != 4'h0);

    wire [3:0] sp_nx  = do_push ? (sp + 4'd1)
                      : (do_pop ? (sp - 4'd1) : sp);

    // the mark never falls below the pointer and only ratchets upward
    wire [3:0] hwm_nx = (sp_nx > hwm) ? sp_nx : hwm;

    always @(posedge clk) begin
        if (i_ce) begin
            sp        <= sp_nx;
            hwm       <= hwm_nx;
            mark_deep <= (hwm_nx >= THRESH);
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_deep = mark_deep;
    assign o_mark = hwm;
    assign o_sp   = sp;

    // Precedence: the deep-mark flag can only rise because the pointer itself
    // has just reached that depth, so the depth must be visible right now.
    always @(posedge clk)
        if (pv && $rose(mark_deep))
            assert (sp >= THRESH);

endmodule

module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
    output wire       can_fetch
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    initial used    = 4'd0;
    initial credits = DEPTH;

    assign can_fetch = (credits != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
        end else if (en) begin
            if (fetch && !retire && credits != 4'd0) begin
                // one slot moves from the free pool into the queue
                used    <= used + 4'd1;
                credits <= credits - 4'd1;
            end else if (retire && !fetch && used != 4'd0) begin
                // one slot moves back from the queue into the free pool
                used    <= used - 4'd1;
                credits <= credits + 4'd1;
            end
            // simultaneous fetch+retire: slot handed straight over, no change
        end
    end

    // P (two assertions, global scope, bounded existence at most 12):
    // neither counter can ever exceed the queue depth, which is strictly
    // smaller than what their 4-bit width admits.
    always @(posedge clk) begin
        assert (used <= DEPTH);
        assert (credits <= DEPTH);
    end
endmodule

module lfsr_grant_arb (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output reg  [1:0] gnt,
    output wire [4:0] o_state
);
    // Maximal-length 5-bit Galois-style shift register, x^5 + x^3 + 1.
    // Seeded nonzero, so the all-zeros lockup state is unreachable.
    reg [4:0] lfsr;

    initial lfsr = 5'h01;
    initial gnt  = 2'b01;

    wire       fb  = lfsr[4] ^ lfsr[2];
    wire [4:0] nxt = {lfsr[3:0], fb};

    // Pseudo-random round-robin: the low bit of the shift register picks
    // which of the two requesters is granted next cycle.  The all-zeros
    // lockup pattern decodes to the illegal "both owners" encoding.
    wire [1:0] sel = (lfsr == 5'd0) ? 2'b11 :
                     (lfsr[0]      ? 2'b01 : 2'b10);

    always @(posedge clk) begin
        if (rst) begin
            lfsr <= 5'h01;
            gnt  <= 2'b01;
        end else if (i_ce) begin
            lfsr <= nxt;
            gnt  <= sel;
        end
    end

    assign o_state = lfsr;

    // Absence: the two grants are never asserted together.
    always @(*)
        if (gnt[0])
            assert (!gnt[1]);
endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
    output wire       o_drained
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
        end else if (i_ce) begin
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                beats_left <= i_len;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
                // retire one beat
                beats_left <= beats_left - 4'd1;
                busy       <= (beats_left != 4'd1);
                drained    <= (beats_left <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

endmodule

module gray_shadow_ctr (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire [3:0] o_gray,
    output wire [3:0] o_bin
);
    // Binary shadow counter and its gray-coded twin.  The gray register is
    // advanced by the classic single-bit-toggle rule, computed from the gray
    // value alone; the binary shadow is a plain increment.
    reg [3:0] bin;
    reg [3:0] gray;
    reg       pv;

    initial bin  = 4'b0000;
    initial gray = 4'b0000;
    initial pv   = 1'b0;

    // Next gray value: toggle bit 0 when the parity is even, otherwise toggle
    // the bit just above the lowest set bit (with the top bit handling wrap).
    function [3:0] gnext(input [3:0] g);
        begin
            if (!(^g))     gnext = g ^ 4'b0001;
            else if (g[0]) gnext = g ^ 4'b0010;
            else if (g[1]) gnext = g ^ 4'b0100;
            else           gnext = g ^ 4'b1000;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'b0000;
            gray <= 4'b0000;
        end else if (i_ce) begin
            bin  <= bin + 4'b0001;
            gray <= gnext(gray);
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_gray = gray;
    assign o_bin  = bin;

    // Top bit of the gray word and top bit of the binary shadow: the most
    // significant gray bit is just the most significant binary bit, so neither
    // may move without the other.
    wire g_msb = gray[3];
    wire b_msb = bin[3];

    // P: whenever the gray MSB did not change, the shadow MSB did not change.
    always @(posedge clk)
        if (pv && $stable(g_msb))
            assert ($stable(b_msb));
endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
    output wire [3:0] o_gnt
);
    // Latency budget granted to an accepted request.
    localparam [2:0] BUDGET = 3'd5;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
    wire retire = gnt_valid && (done || ((elapsed == 3'd4) && (timer == 3'd1)));

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
        end else if (i_ce) begin
            if (!gnt_valid) begin
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                    timer     <= BUDGET;   // credits left
                    elapsed   <= 3'd0;     // cycles burnt
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
    output reg  [7:0] o_data
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [7:0] skid;       // buffered word (meaningful only while stall)
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

    initial begin
        stall    = 1'b0;
        skid     = 8'h00;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
    end

    assign o_ready = !stall;

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid     <= 8'h00;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid     <= i_data;
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid;
                    acc_par  <= skid_par;
                end
            end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
    output wire [3:0] o_snap
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
            // take the shadow snapshot when a bin-1 sample is committed
            if (i_bin == 2'd1)
                snap <= b0;
        end
    end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                    if (gnt_c[0]) begin
                        stage    <= 2'd1;   // ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                    if (gnt_c[1]) begin
                        stage      <= 2'd2; // START step
                        seen_start <= 1'b1;
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                2'd2: begin
                    if (gnt_c[2]) begin
                        stage <= 2'd3;      // FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
            end else if (cnt != K) begin
                cnt      <= cnt + 3'd1;
                stable_f <= (cnt == K - 3'd1);
                if (cnt == K - 3'd1)
                    o_clean <= samp;   // commit the debounced value
            end
            // cnt == K: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
    output wire o_mon
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
            empty_q <= (iss == ret);
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

    always @(posedge clk) begin
        if (i_ce) begin
            o_retry <= retry;
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
                v0 <= i_valid;
                occ <= occ + (i_valid ? 3'd1 : 3'd0) - (v1 ? 3'd1 : 3'd0);
                o_valid <= v1;
                o_data  <= d1;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);
endmodule

module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
    output wire [7:0] o_ref
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
    reg [7:0] total = 8'h00;   // plain ripple-carry reference accumulator

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
            total <= 8'h00;
        end else if (i_ce) begin
            if (i_clear) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
                total <= 8'h00;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
                total <= total + i_data;
            end
        end
    end

    assign o_total = acc_s + acc_c;
    assign o_ref   = total;

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);
endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;

    reg [2:0] nxt;
    wire match = (prog == 3'd3) && sym;

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            prog      <= nxt;
            seen_half <= match ? 1'b0 : (seen_half | (nxt == 3'd2));
            alarm     <= match;
            if (match)
                before_alarm <= 1'b0;
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);
endmodule

module npu_psum_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,      // lane enable / idle when low
    input  wire        i_req,     // new accumulation request
    input  wire [7:0]  i_a,
    input  wire [7:0]  i_b,
    output reg  [19:0] o_psum,
    output reg         o_done
);
    // a full psum accumulation takes exactly MAX MAC steps
    localparam [3:0] MAX = 4'd12;

    // saturating up-counter: clamps at 12 although 4 bits admit 15
    reg [3:0] acc_cnt = 4'd0;
    // countdown that guarantees completion of an accepted request
    reg [4:0] ttl     = 5'd0;
    reg       busy    = 1'b0;

    initial o_psum = 20'd0;
    initial o_done = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            acc_cnt <= 4'd0;
            ttl     <= 5'd0;
            busy    <= 1'b0;
            o_psum  <= 20'd0;
            o_done  <= 1'b0;
        end else if (i_ce) begin
            o_done <= 1'b0;
            if (!busy) begin
                if (i_req) begin
                    busy    <= 1'b1;
                    acc_cnt <= 4'd0;
                    ttl     <= 5'd13;   // MAX + 1 cycles of slack
                    o_psum  <= 20'd0;
                end
            end else begin
                o_psum  <= o_psum + (i_a * i_b);
                acc_cnt <= (acc_cnt == MAX) ? MAX : acc_cnt + 4'd1;
                ttl     <= ttl - 5'd1;
                if ((acc_cnt + 4'd1) == MAX) begin
                    busy   <= 1'b0;
                    o_done <= 1'b1;
                end
            end
        end
    end

    // Bounded response, safety form: the completion countdown must never
    // expire while an accepted accumulation request is still outstanding.
    assert property (!busy || ttl != 5'd0);

endmodule

module serv_inflight_tracker (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,      // idle condition: all state frozen when low
    input  wire       i_issue,   // issue a new operation into the pipeline
    output wire       o_retire,
    output wire [2:0] o_occ
);
    localparam LAT = 4;

    // fixed-latency drain shift register: one bit per pipeline stage
    reg [LAT-1:0] pipe;
    initial pipe = {LAT{1'b0}};

    // in-flight occupancy counter: issue increments, drain decrements
    reg [2:0] occ;
    initial occ = 3'd0;

    // window register (scope): armed by an issue, cleared by a retirement
    reg armed;
    initial armed = 1'b0;

    // shadow register: occupancy recorded at the arming issue
    reg [2:0] sh_occ;
    initial sh_occ = 3'd0;

    wire       drain   = pipe[LAT-1];
    wire [2:0] occ_nxt = occ + {2'b00, i_issue} - {2'b00, drain};

    always @(posedge i_clk) begin
        if (i_reset) begin
            pipe   <= {LAT{1'b0}};
            occ    <= 3'd0;
            armed  <= 1'b0;
            sh_occ <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[LAT-2:0], i_issue};
            occ  <= occ_nxt;
            if (i_issue) begin
                armed  <= 1'b1;
                sh_occ <= occ_nxt;
            end else if (drain) begin
                armed <= 1'b0;
            end
        end
    end

    assign o_retire = i_ce & drain;
    assign o_occ    = occ;

    // Precedence, after issue until retire: a retirement observed inside the
    // armed window must have been preceded by a recorded, still-accounted issue.
    always @(posedge i_clk)
        if (armed && i_ce && drain)
            assert (occ != 3'd0 && sh_occ != 3'd0);
endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
    wire adv       = ce && (startb || datab);
    wire done      = ce && stopb  && take;

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
            if (done)          ferr  <= !rx;    // stop bit must be high
        end
    end

    assign o_data = sr;
    assign o_ferr = ferr;
    assign o_busy = !idle;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);
endmodule

module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

    wire       wrap    = (gray == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
        end else if (i_ce) begin
            bin  <= bin_nxt;
            gray <= bin_nxt ^ (bin_nxt >> 1);
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);
endmodule

module lfsr_token_arbiter (
    input  wire clk,
    input  wire ce,
    output wire o_gnt_a,
    output wire o_gnt_b,
    output wire o_full,
    output wire o_empty
);
    // maximal-length 4-bit LFSR (x^4 + x^3 + 1): cycles through all 15
    // nonzero states, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr;
    reg       gnt_a, gnt_b;
    reg [2:0] credit, used;
    reg       f_full, f_empty;
    reg       armed;

    initial begin
        lfsr    = 4'h1;
        gnt_a   = 1'b0;
        gnt_b   = 1'b0;
        credit  = 3'd4;
        used    = 3'd0;
        f_full  = 1'b0;
        f_empty = 1'b1;
        armed   = 1'b0;
    end

    wire       fb   = lfsr[3] ^ lfsr[2];
    wire [3:0] nxt  = {lfsr[2:0], fb};
    wire       lock = (lfsr == 4'd0);

    // token movement between the two credit pools, steered by the LFSR
    wire take_a = lfsr[0]  && (credit != 3'd0);
    wire give_b = !lfsr[0] && (used   != 3'd0);

    wire [2:0] nc = take_a ? (credit - 3'd1) : (give_b ? (credit + 3'd1) : credit);
    wire [2:0] nu = take_a ? (used   + 3'd1) : (give_b ? (used   - 3'd1) : used);

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= nxt;

            // grant decode: in the lockup state the decode degenerates and
            // asserts both grants at once
            gnt_a <= lock ? 1'b1 : nxt[0];
            gnt_b <= lock ? 1'b1 : !nxt[0];

            credit <= nc;
            used   <= nu;

            f_full  <= (nc == 3'd0);
            f_empty <= (nu == 3'd0);

            if (lfsr == 4'hF)
                armed <= 1'b1;
        end
    end

    assign o_gnt_a = gnt_a;
    assign o_gnt_b = gnt_b;
    assign o_full  = f_full;
    assign o_empty = f_empty;

    // P1: two grants are never asserted together, once the arbiter has been armed
    always @(posedge clk)
        if (armed)
            assert (!(gnt_a && gnt_b));

    // P2: the full and empty flags are never asserted together, once armed
    always @(posedge clk)
        if (armed)
            assert (!(f_full && f_empty));
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

    wire do_on  = req_on  && !zone[i_zone] && (budget != 4'd0);
    wire do_off = req_off &&  zone[i_zone];

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
        end else if (do_on) begin
            zone[i_zone] <= 1'b1;
            zpar         <= ~zpar;      // one data bit flips, parity flips
            nact         <= nact + 4'd1;
            budget       <= budget - 4'd1;
        end else if (do_off) begin
            zone[i_zone] <= 1'b0;
            zpar         <= ~zpar;
            nact         <= nact - 4'd1;
            budget       <= budget + 4'd1;
        end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

// Four-phase request/acknowledge handshake between a driver and a
// peripheral service unit, with separate idle and busy status flags.
module fourphase_handshake (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,        // global enable / idle condition
    input  wire start,       // driver wants to open a transaction
    input  wire slave_ack,   // peripheral raises acknowledge
    input  wire slave_drop,  // peripheral releases acknowledge
    output wire o_req,
    output wire o_ack,
    output wire o_idle,
    output wire o_busy
);
    // phase encoding:
    //   0 : IDLE      req=0 ack=0
    //   1 : REQ       req=1 ack=0
    //   2 : ACK       req=1 ack=1
    //   3 : DROP      req=0 ack=1   (req may only fall after ack has risen)
    reg [1:0] phase;
    reg       req_r;
    reg       ack_r;
    reg       idle_r;
    reg       busy_r;

    initial begin
        phase  = 2'd0;
        req_r  = 1'b0;
        ack_r  = 1'b0;
        idle_r = 1'b1;
        busy_r = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase  <= 2'd0;
            req_r  <= 1'b0;
            ack_r  <= 1'b0;
            idle_r <= 1'b1;
            busy_r <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                2'd0: begin
                    // leave idle only by raising req; idle flag drops here
                    if (start) begin
                        phase  <= 2'd1;
                        req_r  <= 1'b1;
                        idle_r <= 1'b0;
                    end
                end
                2'd1: begin
                    // peripheral acknowledges; service becomes busy
                    if (slave_ack) begin
                        phase  <= 2'd2;
                        ack_r  <= 1'b1;
                        busy_r <= 1'b1;
                    end
                end
                2'd2: begin
                    // req is allowed to fall now that ack is high
                    phase <= 2'd3;
                    req_r <= 1'b0;
                end
                default: begin
                    // peripheral releases ack, transaction closes
                    if (slave_drop) begin
                        phase  <= 2'd0;
                        ack_r  <= 1'b0;
                        busy_r <= 1'b0;
                        idle_r <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign o_req  = req_r;
    assign o_ack  = ack_r;
    assign o_idle = idle_r;
    assign o_busy = busy_r;

    // P: the service unit is never reported idle and busy at the same time.
    always @(*)
        assert (!(idle_r && busy_r));
endmodule

module stack_scoreboard (
    input  wire       clk,
    input  wire       issue,      // a transaction is pushed onto the shadow stack
    input  wire       retire,     // a transaction is popped / completed
    output wire [2:0] outstanding_o,
    output wire       pre_deep_o
);
    // window depth of the in-flight scoreboard
    localparam [2:0] WINDOW = 3'd4;

    // free-running census of issued and retired transactions (wrap mod 16)
    reg [3:0] issued_cnt  = 4'd0;
    reg [3:0] retired_cnt = 4'd0;

    // in-flight occupancy of the window
    reg [2:0] outstanding = 3'd0;

    // "before R" arming register: starts high, cleared the first time the
    // scoreboard occupancy ever reaches 3 (the deep-stack event)
    reg       pre_deep    = 1'b1;

    // past-valid
    reg       pv          = 1'b0;

    wire do_issue  = issue  && (outstanding != WINDOW);
    wire do_retire = retire && (outstanding != 3'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue)  issued_cnt  <= issued_cnt  + 4'd1;
        if (do_retire) retired_cnt <= retired_cnt + 4'd1;

        case ({do_issue, do_retire})
            2'b10:   outstanding <= outstanding + 3'd1;
            2'b01:   outstanding <= outstanding - 3'd1;
            default: outstanding <= outstanding;
        endcase

        if (outstanding >= 3'd3)
            pre_deep <= 1'b0;
    end

    assign outstanding_o = outstanding;
    assign pre_deep_o    = pre_deep;

    // Universality, in the scope "before the stack ever got deep":
    // while pre_deep is still set, the number issued so far can lead the
    // retire census of the PREVIOUS cycle by at most 3.
    always @(posedge clk)
        if (pv && pre_deep)
            assert (issued_cnt - $past(retired_cnt) <= 4'd3);
endmodule

module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
    output wire [2:0] o_state
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;

    wire draw_done = (draw_cnt == 2'd3);

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_start) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
                    // the clear pass is the "earlier event" the shadow records
                    cleared_seen <= 1'b1;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
    output wire       o_busy
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;

    wire send_ok = i_send && (avail >= 4'd3);
    wire retire  = (outst != 4'd0);

    assign o_busy = (outst != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
                timer <= 4'd9;          // fresh completion deadline
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
    output reg        armed
);
    localparam [3:0] PER = 4'd12;

    reg [3:0] cnt;       // period counter, 0 .. PER-1
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period

    initial begin
        cnt      = 4'd0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
    end

    // the construct: output high exactly while the counter is below the duty
    assign pwm_out = (cnt < duty);

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
    wire       at_edge      = (cnt == PER - 4'd1);

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
        end else if (i_ce) begin
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
                if (i_load)
                    duty <= duty_clamped;
            end else begin
                cnt      <= cnt + 4'd1;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
endmodule

module elastic_tag_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,      // Q: opens the observation window
    input  wire       stop,       // R: closes the observation window
    input  wire       push,
    input  wire       pop,
    input  wire [3:0] din,
    output wire [3:0] head_data,
    output wire       head_valid,
    output wire       marked_seen
);
    // two-entry elastic buffer: one valid flag per slot, head/tail flags,
    // plus an occupancy counter that mirrors the flags
    reg [1:0] cnt;
    reg       hp, tp;      // head flag / tail flag
    reg       v0, v1;      // per-slot occupancy flags
    reg [3:0] mem0, mem1;

    // window + shadow register for the precedence check
    reg       win;
    reg       seen_hi;

    initial begin
        cnt     = 2'd0;
        hp      = 1'b0;
        tp      = 1'b0;
        v0      = 1'b0;
        v1      = 1'b0;
        mem0    = 4'd0;
        mem1    = 4'd0;
        win     = 1'b0;
        seen_hi = 1'b0;
    end

    // a window may only be opened on an empty buffer; it may be reopened
    wire start_acc = start && !win && (cnt == 2'd0);
    wire stop_acc  = stop && win && !start_acc;

    wire do_push = push && !start_acc && (cnt != 2'd2);
    wire do_pop  = pop  && !start_acc && (cnt != 2'd0);

    assign head_valid  = hp ? v1   : v0;
    assign head_data   = hp ? mem1 : mem0;
    assign marked_seen = seen_hi;

    always @(posedge clk) begin
        if (rst) begin
            cnt     <= 2'd0;
            hp      <= 1'b0;
            tp      <= 1'b0;
            v0      <= 1'b0;
            v1      <= 1'b0;
            win     <= 1'b0;
            seen_hi <= 1'b0;
        end else begin
            if (do_push) begin
                if (tp) begin
                    mem1 <= din;
                    v1   <= 1'b1;
                end else begin
                    mem0 <= din;
                    v0   <= 1'b1;
                end
                tp <= ~tp;
            end

            if (do_pop) begin
                if (hp) v1 <= 1'b0;
                else    v0 <= 1'b0;
                hp <= ~hp;
            end

            cnt <= cnt + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);

            if (start_acc) begin
                win     <= 1'b1;
                seen_hi <= 1'b0;
            end else if (stop_acc) begin
                win     <= 1'b0;
            end else if (do_push && win && din[3]) begin
                seen_hi <= 1'b1;
            end
        end
    end

    // Precedence, inside the window: a marked item can only be observed at the
    // head if a marked item was pushed earlier in this same window.
    assert property (!win || !head_valid || !head_data[3] || seen_hi);
endmodule

module token_chain (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // global enable: low freezes all state
    input  wire i_tick,    // refill timer tick
    input  wire i_arm,     // step 1: arm a transfer request
    input  wire i_start,   // step 2: start it (consumes a token)
    input  wire i_finish,  // step 3: transfer completes
    output wire o_grant,
    output wire o_busy,
    output wire [2:0] o_tokens
);
    localparam [2:0] BURST  = 3'd4;
    localparam [1:0] S_IDLE = 2'd0,
                     S_ARMED= 2'd1,
                     S_RUN  = 2'd2;

    // ---- state ----
    reg [1:0] state;
    reg [2:0] tokens;    // token bucket, capped at BURST
    reg       seen_arm;
    reg       seen_start;
    reg       seen_fin;

    initial state      = S_IDLE;
    initial tokens     = BURST;
    initial seen_arm   = 1'b0;
    initial seen_start = 1'b0;
    initial seen_fin   = 1'b0;

    // ---- chain events ----
    wire arm_pulse   = i_ce && !rst && (state == S_IDLE)  && i_arm;
    wire start_pulse = i_ce && !rst && (state == S_ARMED) && i_start && (tokens != 3'd0);
    wire fin_pulse   = i_ce && !rst && (state == S_RUN)   && i_finish;

    // refill on timer tick, never above the burst cap
    wire refill      = i_ce && !rst && i_tick && (tokens < BURST);

    assign o_grant  = start_pulse;
    assign o_busy   = (state == S_RUN);
    assign o_tokens = tokens;

    // ---- three-step request machine ----
    always @(posedge clk)
        if (rst)
            state <= S_IDLE;
        else if (i_ce) begin
            case (state)
                S_IDLE:  if (i_arm)                        state <= S_ARMED;
                S_ARMED: if (i_start && (tokens != 3'd0))  state <= S_RUN;
                S_RUN:   if (i_finish)                     state <= S_IDLE;
                default:                                   state <= S_IDLE;
            endcase
        end

    // ---- token bucket: drains on grant, refills on tick ----
    always @(posedge clk)
        if (rst)
            tokens <= BURST;
        else if (start_pulse && refill)
            tokens <= tokens;
        else if (start_pulse)
            tokens <= tokens - 3'd1;
        else if (refill)
            tokens <= tokens + 3'd1;

    // ---- sticky chain observation bits ----
    always @(posedge clk)
        if (rst) begin
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            seen_fin   <= 1'b0;
        end else begin
            if (arm_pulse)   seen_arm   <= 1'b1;
            if (start_pulse) seen_start <= 1'b1;
            if (fin_pulse)   seen_fin   <= 1'b1;
        end

    // ---- property: a finish is never observed unless arm and start happened ----
    always @(posedge clk)
        if (seen_fin)
            assert (seen_arm && seen_start);
endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= i_beats;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left != 4'd0)
                beats_left <= beats_left - 4'd1;
            if (beats_left <= 4'd1)
                busy <= 1'b0;
            if (busy)
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
    assign o_beat = busy && i_ce;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module gray_ptr_cdc (
    input  wire       clk,
    input  wire       i_ce,      // domain-crossing sample enable (idle when low)
    input  wire       i_inc,     // advance the source pointer
    output wire [2:0] o_sync
);
    // source-side binary pointer and its gray encoding
    reg [2:0] bin   = 3'd0;
    // two-flop synchronizer carrying the gray pointer across the boundary
    reg [2:0] s1    = 3'd0;
    reg [2:0] s2    = 3'd0;
    // shadow binary pointers recording what each synchronizer stage encodes
    reg [2:0] b1    = 3'd0;
    reg [2:0] b2    = 3'd0;
    // sticky arm: set the first time a sample actually happens
    reg       armed = 1'b0;

    wire [2:0] gray = bin ^ (bin >> 1);
    wire [2:0] diff = s1 ^ s2;

    assign o_sync = s2;

    always @(posedge clk) begin
        if (i_ce) begin
            bin   <= bin + (i_inc ? 3'd1 : 3'd0);
            s1    <= gray;
            s2    <= s1;
            b1    <= bin;
            b2    <= b1;
            armed <= 1'b1;
        end
    end

    // Universality, after the synchronizer has been armed: the two captured
    // gray samples never differ in more than one bit.
    always @(*)
        if (armed)
            assert ((diff & (diff - 3'd1)) == 3'd0);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
    assign o_done  = (total == 4'd3);

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

            if (adv) begin
                // split increment: the two halves always re-sum to the phase
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
                tog    <= ~tog;
                ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
    assign o_upstream_ready = !hold;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy;

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                    else
                        cnt   <= cnt - 3'd1;
                end
                P_ACK: begin
                    phase <= P_DROP;      // req drops, ack still high
                end
                P_DROP: begin
                    phase <= P_IDLE;      // ack drops
                    busy  <= 1'b0;
                    cnt   <= 3'd4;        // rearm the deadline
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);
endmodule

module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;

    wire word_last = (sh == 5'd31);

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
            if (word_last) begin
                if (!done)
                    retired <= retired + 5'd1;
                done <= done || (retired == (MAX_RETIRE - 5'd1));
            end
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

module issue_token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire [1:0] i_req,     // dual-issue: 0, 1 or 2 slots want to issue
    output wire [1:0] o_grant,   // slots actually granted this cycle
    output reg  [3:0] tokens     // credits left in the bucket
);
    localparam [3:0] BURST  = 4'd8;   // bucket capacity
    localparam [2:0] PERIOD = 3'd5;   // refill timer period

    // thermometer-coded shadow of the bucket occupancy
    reg [7:0] bucket;
    // refill timer
    reg [2:0] tick_cnt;

    initial begin
        tokens   = 4'd0;
        bucket   = 8'h00;
        tick_cnt = 3'd0;
    end

    wire       tick    = (tick_cnt == PERIOD);
    wire [1:0] req_c   = (i_req == 2'd3) ? 2'd2 : i_req;

    // grants are limited by available credits
    wire [1:0] n_drain = (tokens >= {2'b00, req_c}) ? req_c : tokens[1:0];

    // refill one credit per timer tick, capped at the burst size
    wire       do_ref  = tick && (tokens != BURST);

    wire [7:0] b_ref   = do_ref ? {bucket[6:0], 1'b1} : bucket;
    wire [7:0] b_nxt   = b_ref >> n_drain;
    wire [3:0] t_nxt   = tokens + (do_ref ? 4'd1 : 4'd0) - {2'b00, n_drain};

    assign o_grant = i_ce ? n_drain : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens   <= 4'd0;
            bucket   <= 8'h00;
            tick_cnt <= 3'd0;
        end else if (i_ce) begin
            tokens   <= t_nxt;
            bucket   <= b_nxt;
            tick_cnt <= tick ? 3'd0 : (tick_cnt + 3'd1);
        end
    end

    // P: whenever the credit counter reads empty, the thermometer shadow
    //    of the bucket must be empty as well.
    always @(posedge clk)
        if (tokens == 4'd0)
            assert (bucket == 8'h00);

endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
    output reg        armed
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt == LIMIT) begin
                    cnt     <= LIMIT;      // saturate at the timeout
                    expired <= 1'b1;
                    safe    <= 1'b0;
                end else begin
                    cnt     <= cnt + 4'd1;
                    expired <= expired || ((cnt + 4'd1) == LIMIT); // sticky
                    safe    <= ((cnt + 4'd1) < WARN);
                end
            end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
    output wire [3:0] o_avail
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;

    initial used  = 4'd0;
    initial avail = CAP;

    wire take_fire = i_ce &&  i_take && (used != CAP);
    wire give_fire = i_ce && !i_take && (used != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
        end else if (take_fire) begin
            used  <= used  + 4'd1;   // stepped up
            avail <= avail - 4'd1;   // stepped down, same enable
        end else if (give_fire) begin
            used  <= used  - 4'd1;
            avail <= avail + 4'd1;
        end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);
endmodule

module clock_pend_track (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,     // the running side's clock tick
    input  wire i_start,  // Q: press starts the side's clock (opens window)
    input  wire i_stop,   // R: flag falls / press stops it (closes window)
    input  wire i_req,    // a new move-timing request enters the pipeline
    output wire o_done
);
    // in-flight request pipeline plus a separate count of its set bits
    reg [7:0] pend;
    reg [3:0] cnt;
    reg       armed;   // window register: set by i_start, cleared by i_stop

    initial pend  = 8'h00;
    initial cnt   = 4'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (i_rst) begin
            pend  <= 8'h00;
            cnt   <= 4'd0;
            armed <= 1'b0;
        end else begin
            if (i_start)
                armed <= 1'b1;
            else if (i_stop)
                armed <= 1'b0;

            // state only advances while the side's clock is actually running
            if (armed && i_ce) begin
                pend <= { pend[6:0], i_req };
                cnt  <= cnt + { 3'b000, i_req } - { 3'b000, pend[7] };
            end
        end
    end

    assign o_done = armed && i_ce && pend[7];

    // P (two assertions, both inside the open window)
    always @(posedge clk)
        if (armed)
            assert (cnt != 4'd0 || pend == 8'h00);

    always @(posedge clk)
        if (armed)
            assert (cnt != 4'd8 || pend == 8'hFF);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

    assign empty = (count == 3'd0);
    assign full  = (count == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);

            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);
endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= lfsr_next;
            case (stage)
                2'd0: if (arm) begin
                          stage <= 2'd1;
                          chal  <= lfsr;      // latch the challenge word on arm
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));
endmodule

module notebook_cell_arbiter (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output wire [2:0] o_idx,
    output wire       o_valid
);
    // Stage 1: registered priority-encoder result
    reg [2:0] idx;
    reg       valid;
    // Stage 2: exported result (index only meaningful while valid2 is set)
    reg [2:0] idx2;
    reg       valid2;
    // Shadow register: sticky history of every cell that has ever requested
    reg [7:0] hist;
    // Sticky arm: set the first time any cell requests service
    reg       arm;

    initial idx    = 3'd0;
    initial valid  = 1'b0;
    initial idx2   = 3'd0;
    initial valid2 = 1'b0;
    initial hist   = 8'h00;
    initial arm    = 1'b0;

    function [2:0] penc(input [7:0] r);
        begin
            if      (r[0]) penc = 3'd0;
            else if (r[1]) penc = 3'd1;
            else if (r[2]) penc = 3'd2;
            else if (r[3]) penc = 3'd3;
            else if (r[4]) penc = 3'd4;
            else if (r[5]) penc = 3'd5;
            else if (r[6]) penc = 3'd6;
            else if (r[7]) penc = 3'd7;
            else           penc = 3'd0;
        end
    endfunction

    always @(posedge clk) begin
        if (i_reset) begin
            idx    <= 3'd0;
            valid  <= 1'b0;
            idx2   <= 3'd0;
            valid2 <= 1'b0;
            hist   <= 8'h00;
            arm    <= 1'b0;
        end else if (i_ce) begin
            // stage 2 takes last cycle's encode
            idx2   <= idx;
            valid2 <= valid;
            // stage 1 encodes the current request vector
            idx    <= penc(i_req);
            valid  <= |i_req;
            // shadow history grows in the same cycle as the encode
            hist   <= hist | i_req;
            if (|i_req)
                arm <= 1'b1;
        end
    end

    assign o_idx   = idx2;
    assign o_valid = valid2;

    // Precedence, after arm: a published index must name a cell that
    // requested service at some earlier time.
    always @(posedge clk)
        if (arm && valid2)
            assert (hist[idx2]);
endmodule

module wdog_gray_mon (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,      // idle condition: all state frozen when low
    input  wire i_arm,     // Q: opens the monitoring window
    input  wire i_ack,     // R: closes the monitoring window
    output wire o_bite,
    output wire o_grace,
    output wire o_sys_reset
);
    // ---- timer domain: free running gray coded tick pointer -------------
    reg [2:0] cnt;   // binary tick counter
    reg [2:0] g;     // registered gray code of cnt

    // ---- monitor domain: two flop synchronizer on the gray pointer ------
    reg [2:0] s1, s2;

    // ---- window / latched reset ----------------------------------------
    reg armed;
    reg rst_latch;

    initial cnt       = 3'd0;
    initial g         = 3'd0;
    initial s1        = 3'd0;
    initial s2        = 3'd0;
    initial armed     = 1'b0;
    initial rst_latch = 1'b0;

    wire [2:0] nxt = cnt + 3'd1;

    always @(posedge i_clk)
        if (i_rst) begin
            cnt <= 3'd0;
            g   <= 3'd0;
        end else if (i_ce) begin
            cnt <= nxt;
            g   <= nxt ^ (nxt >> 1);
        end

    always @(posedge i_clk)
        if (i_rst) begin
            s1 <= 3'd0;
            s2 <= 3'd0;
        end else if (i_ce) begin
            s1 <= g;    // first flop: freshly captured pointer
            s2 <= s1;   // second flop: stable pointer sample
        end

    // gray -> binary decode of both synchronizer stages
    wire [2:0] mon = { s2[2], s2[2]^s2[1], s2[2]^s2[1]^s2[0] };
    wire [2:0] pre = { s1[2], s1[2]^s1[1], s1[2]^s1[1]^s1[0] };

    // terminal count seen on the stable sample -> watchdog bites
    assign o_bite  = (mon == 3'd7);
    // deep inside the grace region on the freshly captured sample
    assign o_grace = (pre == 3'd2);

    assign o_sys_reset = rst_latch;

    always @(posedge i_clk)
        if (i_rst) begin
            armed     <= 1'b0;
            rst_latch <= 1'b0;
        end else if (i_ce) begin
            if (i_ack)      armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;

            if (i_ack)                     rst_latch <= 1'b0;
            else if (armed && o_bite)      rst_latch <= 1'b1;
        end

    // P: inside the monitoring window the bite and grace indications are
    // never asserted together.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_bite && o_grace));
endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
    output wire busy
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
    end

    wire do_spend  = req && (credits != 3'd0);
    wire do_return = (outst != 3'd0) && (svc == 1'b1);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

                // deadline budget: each spend buys 2 cycles, one cycle burnt
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (do_spend ? 4'd2 : 4'd0);
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg [1:0] bcnt;                 // stages 2,3 occupancy (back half)

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial bcnt     = 2'd0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
bcnt     <= 2'd0;
        end else if (step) begin
            inflight <= {inflight[2:0], req};
// each pipeline half maintains its own occupancy count locally; a
// request crossing the stage1 -> stage2 boundary is handed over from
// the front count to the back count on the same advance
cnt      <= cnt  + {2'b00, req}           - {2'b00, inflight[1]};
bcnt     <= bcnt + {1'b0,  inflight[1]}   - {1'b0,  retire};
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0);
assign f_full = ((cnt + {1'b0, bcnt}) == 3'd4);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
   reg [3:0] lim;   // escape budget for the current string literal (default 8)
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;

    initial st  = 5'b00001;
    initial cnt = 4'd0;
   initial lim = 4'd8;
    initial arm = 1'b0;
    initial pv  = 1'b0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

   // a numeric prefix before a literal programs the escape budget, clamped to 8
   wire [3:0] dig_lim = (i_char[3:0] > 4'd8) ? 4'd8 : i_char[3:0];

    reg [4:0] nst;
    reg [3:0] ncnt;
   reg [3:0] nlim;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
       nlim = lim;
        if (st[S_IDLE]) begin
            if (is_q) begin
                nst  = 5'b01000;   // open quote: enter string, fresh escape count
                ncnt = 4'd0;
           end else if (is_dig) begin
               nst  = 5'b00100;
               nlim = dig_lim;    // leading digit programs the budget
           end
            else if (is_alp)
                nst = 5'b00010;
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
           if (is_dig) nlim = dig_lim;   // later digits override the budget
        end else if (st[S_STR]) begin
            if (is_q) begin
               nst  = 5'b00001;   // close quote: budgeted escapes retire here
               ncnt = (cnt > lim) ? (cnt - lim) : 4'd0;  // surplus carries on
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
           ncnt = (cnt == lim) ? cnt : (cnt + 4'd1);   // saturate at the budget
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
           lim <= 4'd8;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
           lim <= nlim;
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;
   // peer chain B: shares the start unit with chain A
   // arm(line2) -> start(line3) -> finish(line1)
   reg [1:0] stage_b;
   // shared start unit is primed and not yet consumed
   reg       start_tok;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                    if (gnt_c[0]) begin
                        stage    <= 2'd1;   // ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                    if (gnt_c[1]) begin
                        stage      <= 2'd2; // START step
                        seen_start <= 1'b1;
                   end else if (start_tok && gnt_c[2]) begin
                       stage      <= 2'd3; // start unit already primed: skip START
                   end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                    end
                end
                2'd2: begin
                    if (gnt_c[2]) begin
                        stage <= 2'd3;      // FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                   start_tok  <= 1'b0;     // release shared start unit
                end
            endcase
           // peer chain B drives the same start unit from the high lines
           case (stage_b)
               2'd0: if (gnt_c[2]) stage_b <= 2'd1;   // ARM step (B)
               2'd1: if (gnt_c[3]) begin
                         stage_b    <= 2'd2;          // START step (B)
                         seen_start <= 1'b1;          // shared unit has run
                         start_tok  <= 1'b1;          // and stays primed
                     end
               2'd2: if (gnt_c[1]) begin
                         stage_b   <= 2'd3;           // FINISH step (B)
                         start_tok <= 1'b0;           // B consumes the unit
                     end
               default: stage_b <= 2'd0;              // retire B
           endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

   // credits parked against the burst currently in flight
   reg [1:0] escrow;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
   initial escrow      = 2'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

   // at burst start one credit per other waiting requester is parked in
   // escrow, so a burst that has been admitted can always be drained
   wire [3:0] others = req & ~(4'b0001 << idx);
   wire [1:0] resv   = {1'b0, others[0]} + {1'b0, others[1]} +
                       {1'b0, others[2]} + {1'b0, others[3]};
   wire       burst_start = (outstanding == 4'd0);
   wire [3:0] need        = burst_start ? (4'd1 + {2'b00, resv}) : 4'd1;
   wire have_credit = (credits >= need);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
    wire do_grant = i_ce && have_credit && any_req;
    wire do_ret   = i_ce && ret && (outstanding != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
           escrow      <= 2'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

            if (do_grant && !do_ret) begin
               if (burst_start) begin
                   credits <= credits - 4'd1 - {2'b00, resv};
                   escrow  <= resv;
               end else begin
                   credits <= credits - 4'd1;
               end
                outstanding <= outstanding + 4'd1;
            end else if (!do_grant && do_ret) begin
               if (outstanding == 4'd1) begin
                   credits <= credits + 4'd1 + {2'b00, escrow};
                   escrow  <= 2'd0;
               end else begin
                   credits <= credits + 4'd1;
               end
                outstanding <= outstanding - 4'd1;
            end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
    output wire radio_rx   // receive chain owns the radio
);
    // one-hot MAC air-interface FSM:
    //   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_PREAMBLE,
    //   bit3 = TX_DATA, bit4 = ACK_WAIT
    reg [4:0] state;
    initial state = 5'b00001;

   // periodic beacon engine; shares the radio front end with the MAC FSM
   //   bit0 = B_IDLE, bit1 = B_RAMP, bit2 = B_SEND
   reg [2:0] bstate;
   reg [3:0] btimer;
   initial bstate = 3'b001;
   initial btimer = 4'd15;

    wire s_idle  = state[0];
    wire s_rx    = state[1];
    wire s_txpre = state[2];
    wire s_tx    = state[3];
    wire s_ackw  = state[4];

   wire b_idle = bstate[0];
   wire b_ramp = bstate[1];
   wire b_send = bstate[2];
   wire b_busy = b_ramp | b_send;
   wire b_due  = (btimer == 4'd0);
   // the MAC keeps priority: the beacon only grabs an idle, unrequested radio
   wire b_go   = b_idle & b_due & s_idle & ~rx_start & ~tx_req;

   wire [2:0] bnxt;
   assign bnxt[0] = (b_idle & ~b_go) | b_send;
   assign bnxt[1] = b_go;                             // ramp the beacon PA
   assign bnxt[2] = b_ramp;                           // ramp -> send beacon

    // next-state as a per-bit OR of its legal source states
    wire [4:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
    assign nxt[2] = s_idle & tx_req & ~rx_start;       // else start TX ramp
    assign nxt[3] = s_txpre;                           // preamble -> data
    assign nxt[4] = s_tx;                              // data -> wait for ACK

    always @(posedge clk) begin
        if (rst)
            state <= 5'b00001;
       // the air is single-ported: the MAC FSM stalls while the beacon has it
       else if (step && !b_busy)
            state <= nxt;
    end

   always @(posedge clk) begin
       if (rst)
           bstate <= 3'b001;
       else if (step)
           bstate <= bnxt;
   end

   // beacon interval: reload on transmission, hold at zero until the air frees
   always @(posedge clk) begin
       if (rst)
           btimer <= 4'd15;
       else if (step) begin
           if (b_send)
               btimer <= 4'd15;
           else if (btimer != 4'd0)
               btimer <= btimer - 4'd1;
       end
   end

    // decoded radio ownership
   assign radio_tx = s_txpre | s_tx | b_ramp | b_send;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
    output reg        armed
);
    localparam [3:0] PER = 4'd12;

    reg [3:0] cnt;       // period counter, 0 .. PER-1
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period
   reg       pwm_q;     // registered output stage, resolved one cycle ahead

    initial begin
        cnt      = 4'd0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
       pwm_q    = 1'b0;
    end

    // the construct: output high exactly while the counter is below the duty
   assign pwm_out = pwm_q;

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
    wire       at_edge      = (cnt == PER - 4'd1);

   // Next-cycle counter and duty. The output register is loaded from these so
   // the pin keeps the same alignment the combinational comparator had, while
   // the compare itself is off the critical path.
   wire [3:0] cnt_nxt  = at_edge ? 4'd0 : cnt + 4'd1;
   wire [3:0] duty_nxt = (at_edge && i_load) ? duty_clamped : duty;

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
           pwm_q    <= 1'b0;
        end else if (i_ce) begin
           pwm_q <= (cnt_nxt < duty_nxt);
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
                if (i_load)
                    duty <= duty_clamped;
            end else begin
                cnt      <= cnt + 4'd1;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
    output wire       o_in_ready
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

   // one-cycle inter-chain gap: after a FINISH leaves the stage the
   // producer is held off for a cycle so it can resynchronise on the
   // head of the next chain
   reg       gap        = 1'b0;

    wire [1:0] in_code  = src_phase + 2'd1;
   wire       in_ready = !skid_valid && !gap;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           gap        <= 1'b0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
                if (out_room)
                    skid_valid <= 1'b0;
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;

           // hold the producer off for one cycle after a completed chain
           gap <= out_valid && out_ready && out_code == FINISH;
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);

   // Q: the only word that may leave the stage during the post-FINISH
   // gap cycle is the ARM that opens the next chain.
   always @(posedge clk)
       if (!rst)
           assert (!(gap && out_fire) || out_code == ARM);
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
    output reg  [2:0] occ        // queries in flight
);

    reg [3:0] pipe;              // fixed-latency valid shift register
    reg       hold;              // input capture slot: query admitted while stalled
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
        hold        = 1'b0;
    end

    assign retire = pipe[3];
    assign full   = (occ == 3'd4);

    // Admission control: the tracker backpressures at capacity, and a query
    // taken while the pipe is not advancing waits in the capture slot.
    wire room   = (occ != 3'd4);
    wire accept = issue && !hold && room;   // query admitted this cycle
    wire inject = hold || accept;           // entry pushed into stage 0

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
            pipe <= {pipe[2:0], inject};

            // occupancy bookkeeping: +1 on issue, -1 on retire
            occ  <= occ + {2'b00, accept} - {2'b00, pipe[3]};
            hold <= 1'b0;

            // shadow register for the earlier event
            if (accept) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end else if (accept) begin
            // stalled: park the admitted query and count it as in flight
            hold        <= 1'b1;
            occ         <= occ + 3'd1;
            ever_issued <= 1'b1;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain
    reg [3:0] queued;       // beats accepted but not yet issued into the current chunk

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;
    initial queued     = 4'd0;

    // the fabric only accepts short chunks, so a long burst is issued piecewise
    localparam [3:0] CHUNK_MAX = 4'd4;
    wire [3:0] first_chunk = (i_beats > CHUNK_MAX) ? CHUNK_MAX : i_beats;
    wire [3:0] next_chunk  = (queued  > CHUNK_MAX) ? CHUNK_MAX : queued;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= first_chunk;
            queued     <= i_beats - first_chunk;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left > 4'd1) begin
                beats_left <= beats_left - 4'd1;
            end else if (beats_left == 4'd1) begin
                // current chunk drained: pull the next chunk out of the queue
                beats_left <= next_chunk;
                queued     <= queued - next_chunk;
            end
            if ((beats_left <= 4'd1) && (queued == 4'd0))
                busy <= 1'b0;
            if (busy)
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
    assign o_beat = busy && i_ce;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
    output wire o_grant
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
   // admit decision in flight toward the accumulator: the count update is
   // retimed through one register stage, so `ones` trails the window by a beat
   reg         adm_q;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
    reg         pv;

    initial win   = 0;
    initial ones  = 0;
   initial adm_q = 0;
    initial armed = 0;
    initial pv    = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
   // plus the admit still in flight, which the accumulator has not absorbed yet
   wire [2:0] eff      = ones - retiring + (adm_q ? 3'd1 : 3'd0);

    // rate decision is taken from the mirrored count, not from the window
    wire allow = i_req && (eff < LIMIT);

    assign o_grant = i_ce && allow;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
            armed <= 0;
        end else if (i_ce) begin
           win   <= { win[W-2:0], allow };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
           adm_q <= allow;
            if (allow)
                armed <= 1'b1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));
endmodule

module issue_token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire [1:0] i_req,     // dual-issue: 0, 1 or 2 slots want to issue
    output wire [1:0] o_grant,   // slots actually granted this cycle
    output reg  [3:0] tokens     // credits left in the bucket
);
    localparam [3:0] BURST  = 4'd8;   // bucket capacity
    localparam [2:0] PERIOD = 3'd5;   // refill timer period

    // thermometer-coded shadow of the bucket occupancy
    reg [7:0] bucket;
    // refill timer
    reg [2:0] tick_cnt;
// staged refill: the widened thermometer word waits here for one cycle
reg [7:0] b_stage;
reg       ref_v;

    initial begin
        tokens   = 4'd0;
        bucket   = 8'h00;
        tick_cnt = 3'd0;
b_stage  = 8'h00;
ref_v    = 1'b0;
    end

    wire       tick    = (tick_cnt == PERIOD);
    wire [1:0] req_c   = (i_req == 2'd3) ? 2'd2 : i_req;

    // grants are limited by available credits
    wire [1:0] n_drain = (tokens >= {2'b00, req_c}) ? req_c : tokens[1:0];

// stage 2: a posted refill lands in the bucket on this cycle
wire       do_ref  = ref_v;

wire [7:0] b_src   = ref_v ? b_stage : bucket;
wire [7:0] b_nxt   = b_src >> n_drain;
    wire [3:0] t_nxt   = tokens + (do_ref ? 4'd1 : 4'd0) - {2'b00, n_drain};

// stage 1: the timer posts one credit unless the bucket would be full
wire       ref_post = tick && (t_nxt != BURST);

    assign o_grant = i_ce ? n_drain : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens   <= 4'd0;
            bucket   <= 8'h00;
            tick_cnt <= 3'd0;
b_stage  <= 8'h00;
ref_v    <= 1'b0;
        end else if (i_ce) begin
            tokens   <= t_nxt;
            bucket   <= b_nxt;
b_stage  <= ref_post ? {b_nxt[6:0], 1'b1} : b_stage;
ref_v    <= ref_post;
            tick_cnt <= tick ? 3'd0 : (tick_cnt + 3'd1);
        end
    end

    // P: whenever the credit counter reads empty, the thermometer shadow
    //    of the bucket must be empty as well.
    always @(posedge clk)
        if (tokens == 4'd0)
            assert (bucket == 8'h00);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// true quiesce: pipeline drained and nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
        end else begin
            cred <= cred - {2'b00, accept} + {2'b00, retire};
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
reg [2:0] credit   = 3'd0;  // samples carried over from the previous run
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;
// effective stability count: fresh samples plus carried-over credit
wire [3:0] total = {1'b0, cnt} + {1'b0, credit};

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
// keep up to two samples of the run just lost, so a line that had
// already settled reacquires after a short bounce
credit   <= (cnt >= 3'd2) ? 3'd2 : cnt;
end else if (total != K) begin
                cnt      <= cnt + 3'd1;
stable_f <= (total == K - 3'd1);
if (total == K - 3'd1)
                    o_clean <= samp;   // commit the debounced value
            end
            // cnt == K: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;
    // channel B: second probe chain sharing the one challenge generator
    reg [1:0] stage_b;
    reg       own;      // 0 = chain A holds the generator, 1 = chain B
    reg       ld;       // generator context restore in flight (owner stalls)
    reg       chal_ok;  // chal holds a valid generator word

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;
    initial stage_b  = 2'd0;
    initial own      = 1'b0;
    initial ld       = 1'b0;
    initial chal_ok  = 1'b0;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

    // Only one generator word is parked across a handover: the incoming owner
    // resumes from the last challenge word issued on the shared bus, or from
    // the cold seed if no challenge has been issued yet.
    wire [3:0] lfsr_rest = chal_ok ? chal : 4'b0001;

    // the current owner releases the generator once its chain reaches DONE
    wire a_done = (stage   == 2'd3);
    wire b_done = (stage_b == 2'd3);
    wire yield  = !ld && (own ? b_done : a_done);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= ld ? lfsr_rest : lfsr_next;
            if (yield) own <= ~own;
            ld <= yield;
            if (!ld) begin
            if (!own) begin
            case (stage)
                2'd0: if (arm) begin
                          stage <= 2'd1;
                          chal  <= lfsr;      // latch the challenge word on arm
                      chal_ok <= 1'b1;
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
            end else begin
                case (stage_b)
                    2'd0: if (arm) begin
                              stage_b <= 2'd1;
                              chal    <= lfsr;   // same challenge bus
                              chal_ok <= 1'b1;
                          end
                    2'd1: if (start) stage_b <= 2'd2;
                    2'd2: if (fin)   stage_b <= 2'd3;
                    default: stage_b <= 2'd0;
                endcase
            end
            end
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
   output wire [3:0] o_n_iss,   // credits issued to the link (mod 16)
   output wire [3:0] o_n_ret,   // credits returned by the collector (mod 16)
    output wire       o_busy
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
   reg [3:0] n_iss;   // running tally of credits handed to the link
   reg [3:0] n_ret;   // running tally of credits given back

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
   initial n_iss = 4'd0;
   initial n_ret = 4'd0;

    wire send_ok = i_send && (avail >= 4'd3);
    wire retire  = (outst != 4'd0);

   // Deadline sizing.  The collector returns exactly one credit per enabled
   // cycle, so a burst needs (credits still in flight once it is issued)
   // cycles of link time plus one cycle of margin.  The in-flight figure is
   // read straight off the transfer ledger instead of re-deriving it.
   wire [3:0] led_outst = n_iss - n_ret;
   wire [3:0] deadline  = led_outst + 4'd4 - (retire ? 4'd1 : 4'd0);

    assign o_busy = (outst != 4'd0);
   assign o_n_iss = n_iss;
   assign o_n_ret = n_ret;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
           n_iss <= 4'd0;
           n_ret <= 4'd0;
        end else if (i_ce) begin
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
               timer <= deadline;      // fresh completion deadline
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
           // transfer ledger: one entry per credit leaving, one per credit back
           if (send_ok) n_iss <= n_iss + 4'd3;
           if (retire)  n_ret <= n_ret + 4'd1;
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;
    // An escape can now be taken from top level or from inside an identifier,
    // so S_ESC alone no longer says which token is being built: the state code
    // to resume with is held here while st == S_ESC.
    reg [2:0] esc_ret;

    wire [2:0] len_inc = (len == 3'd7) ? 3'd7 : (len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;
    initial esc_ret = S_IDLE;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
            esc_ret <= S_IDLE;
        end else if (ce) begin
            case (st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                        st  <= S_IDENT;
                        len <= 3'd1;
                    end else if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= 3'd1;
                    end else if (cls == 2'd3) begin
                        st  <= S_STR;
                        len <= 3'd0;
                    end else begin
                        st      <= S_ESC;   // stray backslash: escaped char starts an identifier
                        esc_ret <= S_IDENT;
                        len     <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                        st  <= S_IDENT;
                        len <= len_inc;
                    end else if (cls == 2'd0) begin
                        st      <= S_ESC;   // a\b is still a single identifier
                        esc_ret <= S_IDENT;
                        len     <= len;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= len_inc;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                        st  <= S_IDLE;   // closing quote ends the token
                        len <= 3'd0;
                    end else if (cls == 2'd0) begin
                        st  <= S_ESC;    // backslash: next char is literal
                        esc_ret <= S_STR;
                        len <= len;
                    end else begin
                        st  <= S_STR;
                        len <= len_inc;
                    end
                end
                S_ESC: begin
                    st  <= esc_ret;     // resume whatever token the escape interrupted
                    len <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                    st  <= S_IDLE;
                end
            endcase
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
   // increment ahead of the visible counter, so the output register has
   // no XOR chain in front of it.
   reg [3:0] gray_pre;   // in-flight gray code for bin+1

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
       gray_pre  = 4'd1;   // encoder prefilled with gray(bin+1)
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
   wire [3:0] bin_ahead  = bin_nxt + 4'd1;
   wire [3:0] gray_ahead = bin_ahead ^ (bin_ahead >> 1);

    wire [3:0] goal_bin = bin + K;

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
           gray_pre <= gray_ahead;
           gray     <= gray_pre;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
    output wire busy
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
    end

    wire do_spend  = req && (credits != 3'd0);
    wire do_return = (outst != 3'd0) && (svc == 1'b1);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

                // deadline budget: each spend buys 2 cycles, one cycle burnt
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (do_spend ? 4'd2 : 4'd0);
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

   // Quiescence (safety): once the whole pool is back at the producer
   // there is nothing left at the consumer, so the service phase must be
   // idle and the deadline budget must be fully spent.
   always @(posedge clk)
       if (credits == TOTAL)
           assert ((timer == 4'd0) && (svc == 1'b0));

endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
output reg  [3:0] count,
output reg  [7:0] o_push_tally
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
o_push_tally = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full/empty derived from the POINTERS, not from the counter ----
    assign full  = ((wptr - rptr) == 3'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;

    always @(posedge clk) begin
        if (do_push) begin
            mem[wptr] <= alu;
            wptr      <= wptr + 3'd1;
        end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
if (do_push)
    o_push_tally <= o_push_tally + 8'd1;
else if (do_pop)
    o_push_tally <= {o_push_tally[6:0], o_push_tally[7]};
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
    output reg        vld_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
   reg [2:0] per;        // programmed frame length minus one (frame = per+1)
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load

    initial begin
        cnt       = 3'd0;
       per       = 3'd7;   // reset frame is the full eight cycles
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
        out_r     = 1'b0;
        vld_r     = 1'b0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

   // ---------------- frame-length programming ----------------
   // req[2:0] double as the frame-length code; a requested duty that does not
   // fit in the programmed frame is truncated to 100% of that frame
   wire [2:0] per_nxt  = req[2:0];
   wire [3:0] per_lim  = {1'b0, per_nxt} + 4'd1;
   wire [3:0] duty_nxt = (duty_req > per_lim) ? per_lim : duty_req;

    // ---------------- comparator: high exactly while cnt < duty ----------------
    wire out  = ({1'b0, cnt} < duty);
   wire wrap = (cnt == per);

    always @(posedge clk) begin
        if (ce) begin
           cnt   <= wrap ? 3'd0 : cnt + 3'd1;   // restarts at each boundary
            out_r <= out;          // registered output stage
            vld_r <= vld;
            if (wrap) begin
               per       <= per_nxt;
                // period boundary: latch the new duty and its shadow flag together
               duty      <= duty_nxt;
               shadow_nz <= (duty_nxt != 4'd0);
                hi_cnt    <= 4'd0;
               if (duty_nxt == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
                hi_cnt <= hi_cnt + (out ? 4'd1 : 4'd0);
               // frame monitor: the high time can never outrun the frame it
               // belongs to; if it does, the latched flag no longer describes
               // the pulse being emitted, so drop it
               if (hi_cnt > {1'b0, per})
                   shadow_nz <= 1'b0;
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);
endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
            en_load   <= (phase == 3'd4) || makeup;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
            n_load    <= n_load + (((phase == 3'd4) || makeup) ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
    output reg        armed
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt < WARN) begin
                    // pre-warning part of the interval is held in cnt
                    cnt     <= cnt + 4'd1;
                    safe    <= ((cnt + 4'd1) < WARN);
                end else if (grace < GRACE) begin
                    // once cnt has reached WARN the remaining ticks before the
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
    output wire [3:0] o_snap
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= incr && (i_bin == 2'd1);
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
       end
   end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
    reg [3:0] win;         // last four bits received, MSB = oldest
   reg [2:0] fill;        // bits clocked into win since reset, saturates at 4

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
        win    = 4'b0000;
       fill   = 3'd0;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

   // ---- capture-window fill level -------------------------------------
   // Counts probe strobes since reset so the power-up contents of win can
   // never be reported as a frame.
   reg [2:0] nfill;
   always @(*) nfill = (fill == 3'd4) ? 3'd4 : fill + 3'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            prog   <= nprog;
            hot    <= nhot;
            win    <= {win[2:0], i_bit};
           fill   <= nfill;
           // report a match only once the window holds four real bits
           detect <= (nprog == 3'd4) && (nfill == 3'd4);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end

   // ---- property: terminal progress implies a fully loaded window ------
   always @(posedge clk)
       if (prog == 3'd4)
           assert (fill == 3'd4);
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
   wire swap = kick || (count == LIMIT);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
               count_sh <= nxt;              // park the current stall count
               exp_sh   <= (nxt == LIMIT);   // remember if it hung
           end else begin
               count    <= nxt;
           end
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
           expired <= (nxt == LIMIT) || exp_sh;
           healthy <= (nxt < WARN) && (count_sh < WARN);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

   // ---- event ledger: free-running push/pop transfer counters ----
   // flag generation is taken from the ledger difference so that empty/full
   // are a direct function of logged transfers rather than of the occupancy
   // accumulator; the counters wrap naturally at their width.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       n_push = 3'd0; n_pop = 3'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
   assign full  = (occ == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

           // log both sides of every completed transfer
           if (do_push) n_push <= n_push + 3'd1;
           if (do_pop)  n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
   reg [3:0]  dcnt;    // data bits already shifted into sr this frame: 0..8
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
   initial dcnt  = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
    wire adv       = ce && (startb || datab);
    wire done      = ce && stopb  && take;

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
           dcnt  <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
           if (start_det || done) dcnt <= 4'd0;
           else if (datab)        dcnt <= dcnt + 4'd1;
           if (done)          ferr  <= !rx || (dcnt != 4'd8); // stop bit high and a full byte
        end
    end

    assign o_data = sr;
    assign o_ferr = ferr;
    assign o_busy = !idle;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);

   // P2: dcnt lags the phase index by the START phase plus the one-cycle
   // capture lag, so inside a frame it is always nbits-2 bits deep.
   always @(posedge clk)
       if (pv && o_busy && nbits >= 4'd2)
           assert (dcnt == nbits - 4'd2);
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request
    reg       refill_q;  // staged refill: a tick is captured here and applied to the bucket next cycle

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
    initial refill_q = 1'b0;

    wire tick     = (tick_cnt == 2'd0);
    wire do_grant = pending && (tokens != 3'd0);
    wire do_refill = refill_q && (tokens < BURST);

    assign grant   = i_ce && do_grant;
    assign expired = pending && (deadline == 4'd0);

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // refill request is registered one cycle before it reaches the bucket
    always @(posedge clk) if (i_ce)
        refill_q <= tick;

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (do_grant && do_refill)
            tokens <= tokens;                 // one out, one in
        else if (do_grant)
            tokens <= tokens - 3'd1;
        else if (do_refill)
            tokens <= tokens + 3'd1;
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
   wire do_skid = i_push && w_full && !s_v && !do_pop;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
            count <= count + 3'd1;
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
               s_v   <= 1'b0;
               count <= count - 3'd1;
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
               count <= count - 3'd1;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
           count <= count + 3'd1;
       end
        // i_push = i_pop = 0 : the buffer idles, all state held
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
    output wire [2:0] o_state
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;
   // overlay plane pipeline stages (shares the framebuffer with the frame pipeline)
   localparam [1:0] OV_IDLE = 2'd0;
   localparam [1:0] OV_CLR  = 2'd1;
   localparam [1:0] OV_FILL = 2'd2;
   localparam [1:0] OV_SWAP = 2'd3;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame
   reg [1:0] ov_state;      // overlay plane pipeline
   reg       ov_pend;       // overlay refresh owed after the last frame

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;
   initial ov_state     = OV_IDLE;
   initial ov_pend      = 1'b0;

    wire draw_done = (draw_cnt == 2'd3);
   // framebuffer arbitration: the frame pipeline may only start a new frame
   // when no overlay refresh is running or owed
   wire fb_free = (ov_state == OV_IDLE) && !ov_pend;

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
           ov_state     <= OV_IDLE;
           ov_pend      <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                   if (i_start && fb_free) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
                    // the clear pass is the "earlier event" the shadow records
                    cleared_seen <= 1'b1;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                   ov_pend      <= 1'b1;   // overlay gets the buffer next
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase

           // Overlay plane pipeline: same shape as the frame pipeline above,
           // but it borrows the framebuffer and the shared pass counter, so it
           // only runs in the gap between frames.
           case (ov_state)
               OV_IDLE: begin
                   if (ov_pend && state == S_IDLE) begin
                       ov_state <= OV_CLR;
                       ov_pend  <= 1'b0;
                   end
               end
               OV_CLR: begin
                   ov_state <= OV_FILL;
                   draw_cnt <= 2'd0;
               end
               OV_FILL: begin
                   // overlay writes land on the shared framebuffer, so the
                   // recorded clear no longer describes its contents
                   cleared_seen <= 1'b0;
                   if (draw_cnt == 2'd1)
                       ov_state <= OV_SWAP;
                   else
                       draw_cnt <= draw_cnt + 2'd1;
               end
               OV_SWAP: begin
                   ov_state <= OV_IDLE;
                   draw_cnt <= 2'd0;
               end
           endcase
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // beats deferred past the 8-beat hardware burst limit of the current request
   reg [3:0] resid;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial resid    = 4'd0;

    wire accept = start && !armed && (len != 4'd0);
   // the fabric accepts at most 8 beats in one burst; the rest is deferred
   wire [3:0] chunk = (len > 4'd8) ? 4'd8 : len;

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
               beats    <= chunk;
                req_len  <= len;      // shadow capture of the earlier event
               resid    <= len - chunk;
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
            end else if (busy) begin
               beats    <= (beats == 4'd1 && resid != 4'd0) ? resid : beats - 4'd1;
                done_cnt <= done_cnt + 4'd1;
               busy     <= (beats != 4'd1) || (resid != 4'd0);
               resid    <= (beats == 4'd1) ? 4'd0 : resid;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);

   // P, part 3: inside the window, while a deferred chunk is still queued the
   // beats already pushed plus the beats still held back must leave headroom
   // inside the length that was requested earlier.
   always @(posedge clk)
       if (armed && resid != 4'd0)
           assert (({1'b0,done_cnt} + {1'b0,resid}) < {1'b0,req_len});
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
    wire [5:0] req = window & ~hold & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
    wire       have_credit = (pool != 4'd0);
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

    wire [5:0] gnt     = have_credit ? pri : 6'b0;
    wire       gnt_any = |gnt;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
        end else begin
            hold <= (hold | gnt) & ~rel;
            pool <= pool - {3'b0, gnt_any} + {1'b0, rel_cnt};
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
           if (cmt_vld)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
output wire o_mon,
output reg [3:0] o_act
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
            empty_q <= (iss == ret);
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
   // Pointer advances are throttled to phase 0 so that either chain sees at
   // most one gray transition between two of its own samples.
   reg        phase;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);

    always @(posedge clk) begin
        if (i_ce) begin
            // source pointer
           wbin  <= wbin + ((i_incr && !phase) ? 4'd1 : 4'd0);

            // synchronizer chain
           if (!phase) begin
               sync1 <= wgray;
               sync2 <= sync1;
           end else begin
               s1b   <= wgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
               b1    <= wbin;
               b2    <= b1;
           end else begin
               b1b   <= wbin;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
           if (skew_mux)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
// 3-deep shift register feeding a registered writeback stage:
// bit k = op issued k advances ago
reg [2:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;
// registered result stage: the final latency slot lives here
reg       wb;
// second beat of the narrow result bus; the pipe cannot advance during it
reg       beat;

initial pipe  = 3'b000;
    initial occ   = 3'd0;
    initial armed = 1'b0;
initial wb    = 1'b0;
initial beat  = 1'b0;
wire adv = i_ce && !beat;

assign o_retire = adv && wb;
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
end else begin
if (adv) begin
pipe <= {pipe[1:0], issue};
wb   <= pipe[2];
occ  <= occ + (issue ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
            if (issue)
                armed <= 1'b1;
end
if (i_ce)
beat <= !beat && wb;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
   // issue stage: an accepted launch is held here for one cycle (address
   // decode) before it is written into the stage array
   reg              ln_stage;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
   initial ln_stage = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
        end else if (i_ce) begin
           pipe    <= { pipe[STAGES-2:0], ln_stage };
           cnt     <= cnt + (ln_stage ? 3'd1 : 3'd0)
                           - (pipe[STAGES-1]    ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
           ln_stage <= i_launch && armed;
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
if (fill_main && !drain_main)
                occ <= occ + 2'd1;
else if (drain_main && !fill_main)
                occ <= occ - 2'd1;
        end
    end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
    output wire       o_sel
);
    localparam [1:0] LAST = 2'd3;

    // ping-pong double buffer: one half owned by the rasterizer (writer),
    // the other half owned by the shader fetch port (reader)
    reg       sel;                 // master ping-pong select bit
    reg       wr_half, rd_half;    // half currently addressed by each port
    reg [1:0] wcnt, rcnt;          // offset inside the owned half
    reg       wr_full, rd_empty;   // per-half handshake flags
   // buffer-turnaround commit pipeline: the ownership swap is handed to the
   // memory system and retires four cycles later, so both ports keep their
   // current half assignment until the request has walked all four stages
   reg       swp_v0, swp_v1, swp_v2, swp_v3;   // request valid, per stage
   reg       swp_d0, swp_d1, swp_d2, swp_d3;   // pending select, per stage
    reg [7:0] mem [0:7];
    integer   i;

    initial begin
        sel     = 1'b0;
        wr_half = 1'b0;
        rd_half = 1'b1;
        wcnt    = 2'd0;
        rcnt    = 2'd0;
        wr_full = 1'b0;
        rd_empty= 1'b1;
       swp_v0  = 1'b0;
       swp_v1  = 1'b0;
       swp_v2  = 1'b0;
       swp_v3  = 1'b0;
       swp_d0  = 1'b0;
       swp_d1  = 1'b0;
       swp_d2  = 1'b0;
       swp_d3  = 1'b0;
        rd_data = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire [2:0] wr_addr = {wr_half, wcnt};
    wire [2:0] rd_addr = {rd_half, rcnt};

    wire w_step = i_ce && wr_en && !wr_full;
    wire r_step = i_ce && rd_en && !rd_empty;
   wire swp_busy   = swp_v0 || swp_v1 || swp_v2 || swp_v3;
   wire swap       = i_ce && wr_full && rd_empty && !swp_busy;
   wire swp_commit = i_ce && swp_v3;

    assign o_sel = sel;

    always @(posedge clk) begin
        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
           swp_v0   <= 1'b0;
           swp_v1   <= 1'b0;
           swp_v2   <= 1'b0;
           swp_v3   <= 1'b0;
           swp_d0   <= 1'b0;
           swp_d1   <= 1'b0;
           swp_d2   <= 1'b0;
           swp_d3   <= 1'b0;
       end else if (swp_commit) begin
           sel      <= swp_d3;
           wr_half  <= swp_d3; // writer takes the freshly drained half
           rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
        end else begin
            if (w_step) begin
                mem[wr_addr] <= wr_data;
                wcnt <= wcnt + 2'd1;
                if (wcnt == LAST) wr_full <= 1'b1;
            end
            if (r_step) begin
                rd_data <= mem[rd_addr];
                rcnt <= rcnt + 2'd1;
                if (rcnt == LAST) rd_empty <= 1'b1;
            end
        end

       // the turnaround request advances one stage per enabled cycle
       if (!rst && i_ce) begin
           swp_v3 <= swp_v2;   swp_d3 <= swp_d2;
           swp_v2 <= swp_v1;   swp_d2 <= swp_d1;
           swp_v1 <= swp_v0;   swp_d1 <= swp_d0;
           swp_v0 <= swap;     swp_d0 <= ~sel;
       end
    end

    // P: whenever both ports perform an access in the same cycle they never
    // touch the same buffer location
    always @(posedge clk)
        if (i_ce && wr_en && rd_en && !wr_full && !rd_empty)
            assert (wr_addr != rd_addr);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
output reg        armed,   // sticky: set the first time a request is taken
output reg  [3:0] n_take,  // ledger: leases issued  (free-running, wraps)
output reg  [3:0] n_drop,  // ledger: leases retired (free-running, wraps)
output reg        stale    // standing lease has burned one idle cycle
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

   // the ledger, not vld, is the authority on lease occupancy
   wire outstanding = (n_take != n_drop);

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
n_take = 4'd0;
n_drop = 4'd0;
stale  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // any request refreshes the lease and re-asserts valid
                vld   <= 1'b1;
                armed <= 1'b1;
                stale <= 1'b0;
                if (!outstanding) begin
                    // ledger is square: issue a fresh lease to the winner
                    idx    <= enc;
                    oh     <= iso;
                    n_take <= n_take + 4'd1;
                end else if (enc < idx) begin
                    // lease already in flight: a higher-priority requester
                    // takes it over in place -- a hand-off, not a new lease,
                    // so the ledger does not move
                    idx <= enc;
                    oh  <= iso;
                end
                // otherwise the current holder keeps the bus
            end else if (outstanding) begin
                if (stale) begin
                    // second idle cycle retires the lease; the one-hot is
                    // left parked as a record of the last holder
                    vld    <= 1'b0;
                    stale  <= 1'b0;
                    n_drop <= n_drop + 4'd1;
                end else begin
                    // first idle cycle: age the standing grant round-robin
                    idx   <= idx + 2'd1;
                    oh    <= {oh[2:0], oh[3]};
                    stale <= 1'b1;
                end
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
       lim     = 3'd2;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

   // the slot is only released when the egress parity re-check is clean
   wire oq_bad = oq_busy && (oq_par != (^o_data));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
   wire room = occ < lim;
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;

    always @(posedge clk) begin
        if (i_ce) begin
           o_retry <= retry || nack || oq_bad;
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
               v0 <= acc;
               oq_busy <= v1;
               oq_par  <= p1;
               if (cfg) lim <= i_data[0] ? 3'd2 : 3'd1;
               occ <= occ + (acc ? 3'd1 : 3'd0) - (rel ? 3'd1 : 3'd0);
                o_valid <= v1;
                o_data  <= d1;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
   assign o_done  = (total == 4'd3) || b_done;

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
   wire adv2 = i_ce && (ph_ref == 3'd3) &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
   wire inc = adv || adv2;

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

           if (inc) begin
               // split increment: the halves re-sum to both chain phases together
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
               tog <= ~tog;
           end

           if (adv) begin
               ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end

           if (adv2) begin
               ph_ref2 <= ph_ref2 + 3'd1;
               if (ph_ref2 == 3'd2) b_done <= 1'b1;
           end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;
  // second parked context: three decode channels rotate through the one
  // pipeline slot, so two of them are always parked at any time
  reg  [3:0] count_sh2;
  reg        exp_sh2;

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
      count_sh2 = 4'd0;
      exp_sh2   = 1'b0;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
   wire swap = kick || (count == LIMIT);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
           count_sh2 <= 4'd0;
           exp_sh2   <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
count_sh  <= count_sh2;        // rotate the parked queue forward
count_sh2 <= nxt;              // park the current stall count
exp_sh    <= exp_sh2;          // its hang flag rotates with it
exp_sh2   <= (nxt == LIMIT);   // remember if it hung
           end else begin
               count    <= nxt;
           end
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
expired <= (nxt == LIMIT) || exp_sh || exp_sh2;
healthy <= (nxt < WARN) && (count_sh < WARN) && (count_sh2 < WARN);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
cmt_pend <= 1'b0;          // an in-flight commit is aborted
end else begin
    if (cnt != K) begin
        cnt <= cnt + 3'd1;
        if (cnt == K - 3'd1) begin
            // stage the commit; the flag and output move one step later
            cmt_pend <= 1'b1;
            cmt_val  <= samp;
        end
    end
    if (cmt_pend) begin
        o_clean  <= cmt_val;   // commit the debounced value
        stable_f <= 1'b1;
        cmt_pend <= 1'b0;
    end
            end
// cnt == K with nothing staged: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag
   reg [4:0]  pend;    // retire credits posted but not yet counted

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;
   initial pend    = 5'd0;

   // Retirement is credited through a small pending-credit queue: a completed
   // word posts one credit, and the retire counter's write port (shared with
   // word capture) releases one credit on any enabled cycle that is not a
   // word boundary.  Saturation is declared on the total, posted + counted.

    wire word_last = (sh == 5'd31);

   wire [5:0] retire_total = {1'b0, retired} + {1'b0, pend};
   wire       credit_enq   = word_last && !done;
   wire       credit_deq   = (pend != 5'd0) && !word_last;

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
           pend    <= 5'd0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
           if (credit_enq)
               pend <= pend + 5'd1;
           else if (credit_deq)
               pend <= pend - 5'd1;
           if (credit_deq)
               retired <= retired + 5'd1;
           if (credit_enq)
               done <= (retire_total == {1'b0, (MAX_RETIRE - 5'd1)});
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];
   reg [1:0] wnext;       // precomputed next write address (shared write-port adder)

   // ---- refresh generator: periodic level-refresh events ----
   // second producer on the shared FIFO write port: every fourth sample it
   // re-posts the current debounced level so a stalled consumer still gets a
   // fresh entry. Edge events own the port; a coincident refresh is held.
   reg [1:0] hb;
   reg       hb_pend;

   // ---- event ledger: free-running push/pop transfer counters ----
   // flag generation is taken from the ledger difference so that empty/full
   // are a direct function of logged transfers rather than of the occupancy
   // accumulator; the counters wrap naturally at their width.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       wnext = 2'd1;
       hb = 2'd0; hb_pend = 1'b0;
       n_push = 3'd0; n_pop = 3'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
   assign full  = (occ == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

   wire hb_req   = (hb == 2'd3) || hb_pend;
   wire push_req = deb_commit || hb_req;
   wire do_push  = i_ce && push_req && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
               mem[wptr] <= deb_commit ? raw : deb;
               wptr      <= wnext;
               tail      <= wnext;
               wnext     <= wnext + 2'd1;
            end

           // the refresh prescaler runs off the sample clock; a refresh
           // request retires only once it actually wins the write port
           hb <= hb + 2'd1;
           if (hb_req) hb_pend <= deb_commit || full;

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

           // log both sides of every completed transfer
           if (do_push) n_push <= n_push + 3'd1;
           if (do_pop)  n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;

  // sticky saturation lock: if the counter is already topped out when a
  // match credit retires, the credit is dropped and the reading is frozen,
  // so software can tell "exactly 15" from "15 or more"
  reg       sat_lock;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial sat_lock    = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
          sat_lock    <= 1'b0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
          if (cmt_vld)
              sat_lock <= sat_lock | (match_count == 4'd15);
          if (cmt_vld && !sat_lock)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Saturation lock is a consequence of counted traffic: it can only engage
   // after the counter has been driven to full, so the exported count is
   // nonzero and the pattern prefix must already have been seen.
   always @(posedge clk)
       assert (!sat_lock || (saw_p3 && hits != 4'd0));
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
output wire [2:0] o_inflight,
output reg  [3:0] o_issue_hist
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// distractor: history of raw issue requests (not tied to occupancy)
reg [3:0] req_hist;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial req_hist     = 4'b0000;
initial o_issue_hist = 4'b0000;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
req_hist     <= 4'b0000;
o_issue_hist <= 4'b0000;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
req_hist     <= {req_hist[2:0], issue};
o_issue_hist <= req_hist ^ {3'b000, issue};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // anticipated carry out of the low half of cnt, registered a cycle early
    // so the wrap term never ripples across all four counter bits
    reg lo_tc;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
        lo_tc = 1'b0;
    end

    wire [1:0] nxt_lo   = cnt[1:0] + 2'd1;
    wire [1:0] nxt_hi   = cnt[3:2] + {1'b0, lo_tc};
    wire [3:0] nxt      = {nxt_hi, nxt_lo};
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;
  // stage-3 writeback chain: reuses the same strobes after the drain retired
  reg [2:0] ph_ref3;
  // sticky flag: the writeback chain reached its final phase
  reg       c_done;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
      ph_ref3    = 3'd0;
      c_done     = 1'b0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
  assign o_done  = (total == 4'd3) || b_done || c_done;

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
   wire adv2 = i_ce && (ph_ref == 3'd3) &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

  // the writeback chain only takes the shared accumulator once the drain retired
  wire adv3 = i_ce && (ph_ref2 == 3'd3) &&
                      (((ph_ref3 == 3'd0) && i_arm)   ||
                       ((ph_ref3 == 3'd1) && i_start) ||
                       ((ph_ref3 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
  wire inc = adv || adv2 || adv3;

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
          ph_ref3    <= 3'd0;
          c_done     <= 1'b0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

           if (inc) begin
               // split increment: the halves re-sum to both chain phases together
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
               tog <= ~tog;
           end

           if (adv) begin
               ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end

           if (adv2) begin
               ph_ref2 <= ph_ref2 + 3'd1;
               if (ph_ref2 == 3'd2) b_done <= 1'b1;
           end

          if (adv3) begin
              ph_ref3 <= ph_ref3 + 3'd1;
              if (ph_ref3 == 3'd2) c_done <= 1'b1;
          end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;
   // second channel, MSB first: 0 1 1 0, scanned on the same input stream
   localparam [3:0] PAT_B = 4'b0110;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
   // channel B match-progress register, same bound as channel A
   reg [2:0] prog_b;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;
  // channel B credit for the shared retire port: channel A owns the port
  // when it is retiring, so a B credit waits here until the port is free
  reg       cmt_pend_b;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial prog_b      = 3'd0;
  initial cmt_pend_b  = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;
   wire [1:0] idx_b     = 2'd3 - prog_b[1:0];
   wire       exp_bit_b = PAT_B[idx_b];
   wire       restart_b = (din == PAT_B[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
          prog_b      <= 3'd0;
          cmt_pend_b  <= 1'b0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
           // either channel reaching the deep prefix sets the shared flag
           saw_p3 <= saw_p3 | (prog == 3'd3) | (prog_b == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
          // channel B posts into the same retire port; the credit is held
          // while channel A is using the port this cycle
          cmt_pend_b <= (prog_b == 3'd4) | (cmt_pend_b & cmt_vld);
          if (cmt_vld || cmt_pend_b)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end

           // channel B scanner: independent progress over the same stream
           if (prog_b == 3'd4) begin
               prog_b <= restart_b ? 3'd1 : 3'd0;
           end else if (din == exp_bit_b) begin
               prog_b <= prog_b + 3'd1;
           end else begin
               prog_b <= restart_b ? 3'd1 : 3'd0;
           end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);
endmodule

// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;

// Precedence shadow, split for radiation tolerance: the low two bits of the
// recorded code ripple in prev_lo, while its top bit is kept as a dual-rail
// pair whose advance is a swap of the two rails.
reg [1:0] prev_lo   = 2'd0;
reg       prev_hi_t = 1'b0;
reg       prev_hi_f = 1'b1;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

// recomposed precedence code
wire [2:0] prev_voted = {prev_hi_t, prev_lo};

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
prev_lo   <= code_in[1:0] - 2'd1;
prev_hi_t <= code_in[2] ^ (code_in[1:0] == 2'd0);
prev_hi_f <= ~(code_in[2] ^ (code_in[1:0] == 2'd0));
            end else begin
                shadow_a   <= shadow_a + 3'd1;
                shadow_b   <= shadow_b + 3'd1;
                shadow_c   <= shadow_c + 3'd1;
prev_lo <= voted[1:0];
// the top bit only moves when the low part rolls over
if (prev_lo == 2'd3) begin
    prev_hi_t <= prev_hi_f;
    prev_hi_f <= prev_hi_t;
end
            end
        end
    end

    always @(posedge clk) begin
        if (r_stop)
            win <= 1'b0;
        else if (q_start)
            win <= 1'b1;
    end

    // Property: inside the monitoring window, the voted step code must be the
    // immediate successor of the code recorded earlier in prev_voted.
    always @(posedge clk)
        assert (!win || (voted == prev_voted + 3'd1));

endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
output wire       o_settled, // no sample in flight
output reg  [3:0] o_acc      // distractor: settled-beat accumulator
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
o_acc = 4'd0;
    end

    wire [3:0] nxt      = cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

// distractor logic: counts destination beats seen while the path is settled
always @(posedge clk) begin
    if (i_ce)
        o_acc <= o_acc + {3'd0, o_settled};
end

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

  // replay bookkeeping: every parity mismatch books one replay slot, and a
  // booked slot is handed back when the egress re-check frees a credit
  reg [2:0] rpy;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
       lim     = 3'd2;
      rpy     = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

   // the slot is only released when the egress parity re-check is clean
   wire oq_bad = oq_busy && (oq_par != (^o_data));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
   wire room = occ < lim;
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;

    always @(posedge clk) begin
        if (i_ce) begin
          o_retry <= retry || nack || oq_bad || (rpy != 3'd0);
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
               rpy <= rpy + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
               v0 <= acc;
               oq_busy <= v1;
               oq_par  <= p1;
               if (cfg) lim <= i_data[0] ? 3'd2 : 3'd1;
               occ <= occ + (acc ? 3'd1 : 3'd0) - (rel ? 3'd1 : 3'd0);
              if (rel && rpy != 3'd0) rpy <= rpy - 3'd1;
                o_valid <= v1;
                o_data  <= d1;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);

   // a replay slot is only booked on a real corruption, so booked slots plus
   // live slice slots never oversubscribe the two-deep slice
   always @(posedge clk)
       assert ({1'b0, occ} + {1'b0, rpy} <= 4'd2);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase    // which link slot the collector is in
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;

    wire send_ok = i_send && (avail >= 4'd3);
wire retire  = (outst != 4'd0) && phase;

    assign o_busy = (outst != 4'd0);
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
if (send_ok) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

   // Only one commit stage was budgeted, so the two channels arbitrate for it;
   // the raw-sample channel wins a tie, the arm channel retries next step.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
   wire grant_a = !cmt_pend && a_req;
   wire grant_b = !cmt_pend && b_req && !a_req;

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
                   // stage the commit; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
                   cmt_pend <= 1'b1;
                   cmt_val  <= samp;
                   cmt_ch   <= CH_A;
               end
               // stage busy: hold at K-1 and retry once it frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
                   cmt_pend <= 1'b1;
                   cmt_val  <= samp_b;
                   cmt_ch   <= CH_B;
               end
           end

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
               cmt_pend <= 1'b0;
               if (cmt_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= cmt_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= cmt_val;
               end
           end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
output reg  o_level,   // last popped debounced level
output reg [3:0] o_dbg_cnt
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

   // ---- event ledger: free-running push/pop transfer counters ----
   // flag generation is taken from the ledger difference so that empty/full
   // are a direct function of logged transfers rather than of the occupancy
   // accumulator; the counters wrap naturally at their width.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;
// ---- debug: raw-edge activity counter (observability only) ----
reg       raw_d;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       n_push = 3'd0; n_pop = 3'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
raw_d = 1'b0; o_dbg_cnt = 4'd0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
   assign full  = (occ == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

           // log both sides of every completed transfer
           if (do_push) n_push <= n_push + 3'd1;
           if (do_pop)  n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
raw_d <= raw;
if (raw != raw_d) o_dbg_cnt <= o_dbg_cnt + 4'd1;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown
   reg [2:0] wait_cnt = 3'd0;  // ticks the target made us wait for ack

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy;

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                   else begin
                       cnt      <= cnt - 3'd1;
                       wait_cnt <= wait_cnt + 3'd1;  // log the wait
                   end
                end
                P_ACK: begin
                   // fast target: ack came back on the first tick, so there
                   // is nothing left to drain - finish without a drop phase
                   if (wait_cnt == 3'd0) begin
                       phase <= P_IDLE;
                       busy  <= 1'b0;
                       cnt   <= 3'd4;
                   end else begin
                       phase <= P_DROP;  // req drops, ack still high
                   end
                end
                P_DROP: begin
                    phase <= P_IDLE;      // ack drops
                    busy  <= 1'b0;
                    cnt   <= 3'd4;        // rearm the deadline
                   wait_cnt <= 3'd0;     // clear the latency monitor
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);

   // P3: the latency monitor never reports a wait longer than the window
   always @(posedge clk)
       if (busy) assert (wait_cnt <= 3'd3);
endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
    output wire o_busy
);
    localparam [3:0] TOTAL = 4'd3;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- peer chain B: second engine drawing on the same credit pool ----
    reg [3:0] armed_b;    // chain B credits spent on ARM, awaiting START
    reg [3:0] busy_b;     // chain B credits outstanding at its consumer

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    // ---- command-port ownership: both chains share one command port; it is
    //      handed to the other chain once the current owner has drained ----
    reg sel;              // 0 => chain A is served, 1 => chain B

    initial begin
        armed_b    = 4'd0;
        busy_b     = 4'd0;
        sel        = 1'b0;
        free_cr    = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
    end

    wire do_flush = i_ce &&  i_flush;
    wire own_idle = sel ? ((armed_b  == 4'd0) && (busy_b  == 4'd0))
                        : ((armed_cr == 4'd0) && (busy_cr == 4'd0));
    wire do_swap  = i_ce && !i_flush && own_idle && !i_arm && !i_start && !i_done;

    // the port owner is the only chain that sees the command strobes
    wire do_arm   = i_ce && !i_flush && !sel && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && !sel && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && !sel && i_done  && (busy_cr  != 4'd0);

    wire do_arm_b   = i_ce && !i_flush && sel && i_arm   && (free_cr != 4'd0);
    wire do_start_b = i_ce && !i_flush && sel && i_start && (armed_b != 4'd0);
    wire do_fin_b   = i_ce && !i_flush && sel && i_done  && (busy_b  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
            free_cr    <= TOTAL;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            armed_b    <= 4'd0;
            busy_b     <= 4'd0;
            sel        <= 1'b0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
        end else if (i_ce) begin
            free_cr  <= free_cr  - do_arm - do_arm_b + do_fin + do_fin_b;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            armed_b  <= armed_b  + do_arm_b   - do_start_b;
            busy_b   <= busy_b   + do_start_b - do_fin_b;
            if (do_swap) sel <= ~sel;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0) || (busy_b != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

module wdog_gray_mon (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,      // idle condition: all state frozen when low
    input  wire i_arm,     // Q: opens the monitoring window
    input  wire i_ack,     // R: closes the monitoring window
    output wire o_bite,
    output wire o_grace,
    output wire o_sys_reset
);
    // ---- timer domain: free running gray coded tick pointer -------------
    reg [2:0] cnt;   // binary tick counter
    reg [2:0] g;     // registered gray code of cnt

    // ---- monitor domain: two flop synchronizer on the gray pointer ------
    reg [2:0] s1, s2;

    // monitor side tally of pointer advances observed since reset
    reg [2:0] adv_cnt;

    // ---- window / latched reset ----------------------------------------
    reg armed;
    reg rst_latch;

    initial cnt       = 3'd0;
    initial g         = 3'd0;
    initial s1        = 3'd0;
    initial s2        = 3'd0;
    initial adv_cnt   = 3'd0;
    initial armed     = 1'b0;
    initial rst_latch = 1'b0;

    wire [2:0] nxt = cnt + 3'd1;

    always @(posedge i_clk)
        if (i_rst) begin
            cnt <= 3'd0;
            g   <= 3'd0;
        end else if (i_ce) begin
            cnt <= nxt;
            g   <= nxt ^ (nxt >> 1);
        end

    always @(posedge i_clk)
        if (i_rst) begin
            s1 <= 3'd0;
            s2 <= 3'd0;
            adv_cnt <= 3'd0;
        end else if (i_ce) begin
            s1 <= g;    // first flop: freshly captured pointer
            s2 <= s1;   // second flop: stable pointer sample
            // every time the stable sample moves, the monitor has seen
            // one more tick of the timer domain
            if (s1 != s2) adv_cnt <= adv_cnt + 3'd1;
        end

    // gray -> binary decode of both synchronizer stages
    wire [2:0] mon = { s2[2], s2[2]^s2[1], s2[2]^s2[1]^s2[0] };
    wire [2:0] pre = { s1[2], s1[2]^s1[1], s1[2]^s1[1]^s1[0] };

    // terminal count seen on the stable sample -> watchdog bites
    assign o_bite  = (mon == 3'd7);
    // deep inside the grace region on the freshly captured sample
    assign o_grace = (pre == 3'd2);

    assign o_sys_reset = rst_latch;

    // half a lap of observed advances: by now the all zero power up sample
    // has been flushed out of the synchronizer
    wire startup_done = adv_cnt[2];

    always @(posedge i_clk)
        if (i_rst) begin
            armed     <= 1'b0;
            rst_latch <= 1'b0;
        end else if (i_ce) begin
            if (i_ack)      armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;

            if (i_ack)                     rst_latch <= 1'b0;
            else if (armed && o_bite && startup_done)
                                           rst_latch <= 1'b1;
        end

    // P: inside the monitoring window the bite and grace indications are
    // never asserted together.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_bite && o_grace));

    // P2: a bite is only ever reported when the monitor has tallied a full
    // lap of observed pointer advances.
    always @(posedge i_clk)
        assert (!o_bite || adv_cnt == 3'd7);
endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
output reg        armed,
output reg [3:0] kick_cnt
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone
    localparam [1:0] GRACE = LIMIT - WARN;  // warning-zone dwell before timeout
    reg [1:0] grace;                        // ticks elapsed since cnt hit WARN

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;
initial kick_cnt = 4'd0;

    always @(posedge clk) begin
        if (i_ce) begin
// bookkeeping only: how many kicks have been seen
if (kick)
kick_cnt <= kick_cnt + 4'd1;
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt < WARN) begin
                    // pre-warning part of the interval is held in cnt
                    cnt     <= cnt + 4'd1;
                    safe    <= ((cnt + 4'd1) < WARN);
                end else if (grace < GRACE) begin
                    // once cnt has reached WARN the remaining ticks before the
                    // timeout are accumulated here, so the warning-zone dwell
                    // can be reported on its own
                    grace   <= grace + 2'd1;
                    expired <= ((grace + 2'd1) == GRACE);
                    safe    <= 1'b0;
                end
            end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
   // issue stage: an accepted launch is held here for one cycle (address
   // decode) before it is written into the stage array
   reg              ln_stage;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
   initial ln_stage = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
        end else if (i_ce) begin
           pipe    <= { pipe[STAGES-2:0], ln_stage };
           cnt     <= cnt + (ln_stage ? 3'd1 : 3'd0)
                           - (pipe[STAGES-1]    ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
           ln_stage <= i_launch && armed;
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Retire/issue provenance: a request can only be observed leaving the last
    // stage, or waiting in the issue stage for address decode, if it entered
    // through an accepted start, which in turn can only happen after arming.
    always @(posedge clk)
        if (o_retire || ln_stage)
            assert (started && armed);

endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

   // ---- issue / commit pipeline ---------------------------------------
   // A grant decided this cycle reaches the heater mask on the next cycle;
   // the in-flight grant is held here.  One grant may be in flight.
   reg       p_val;   // a grant is in flight
   reg       p_on;    // 1 = turn the zone on, 0 = turn it off
   reg [2:0] p_zone;  // zone the in-flight grant targets
   initial   p_val  = 1'b0;
   initial   p_on   = 1'b0;
   initial   p_zone = 3'd0;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

   // forward the in-flight grant, so a zone is never granted twice while
   // its mask bit has not been updated yet
   wire zbit = (p_val && (p_zone == i_zone)) ? p_on : zone[i_zone];

   wire do_on  = req_on  && !zbit && (budget != 4'd0);
   wire do_off = req_off &&  zbit;

   // a power slot is reserved when the grant is issued and released only
   // when the heater has actually been switched off, one cycle later
   wire bud_dec = do_on;
   wire bud_inc = p_val && !p_on;

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
           p_val  <= 1'b0;
           p_on   <= 1'b0;
           p_zone <= 3'd0;
       end else if (i_ce) begin
           // commit stage: apply the grant issued last cycle
           if (p_val) begin
               zone[p_zone] <= p_on;
               zpar         <= ~zpar;  // one data bit flips, parity flips
               nact         <= p_on ? nact + 4'd1 : nact - 4'd1;
           end
           // issue stage: latch this cycle's decision
           p_val  <= do_on || do_off;
           p_on   <= do_on;
           p_zone <= i_zone;
           budget <= budget - {3'b000, bud_dec} + {3'b000, bud_inc};
       end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg  [7:0] out_data
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

   // input capture register: a word that arrives while the output register
   // is stalled lands here first and reaches the skid slot next cycle
   reg        cap_valid;
   reg  [7:0] cap_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
       cap_valid  = 1'b0;
       cap_data   = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

   assign in_ready = !skid_valid && !cap_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
           cap_valid  <= 1'b0;
           cap_data   <= 8'h00;
            occ        <= 3'd0;
            armed      <= 1'b0;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
               end else if (cap_valid) begin
                   out_data  <= cap_data;
                   out_valid <= 1'b1;
                   cap_valid <= 1'b0;
                end else if (in_valid) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
               // downstream stalled: promote the capture register into the
               // skid slot, otherwise capture the arriving word
               if (cap_valid && !skid_valid) begin
                   skid_data  <= cap_data;
                    skid_valid <= 1'b1;
                   cap_valid  <= 1'b0;
               end else if (in_valid && !skid_valid && !cap_valid) begin
                   cap_data  <= in_data;
                   cap_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

            if (accept) armed <= 1'b1;
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;
   // commit stage: the decoder's next-progress value waits one tick here
   // before it is retired into the matcher, keeping the decode path short
   reg [2:0] stg;
   reg       stg_v;       // a staged progress value is pending commit

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;
   initial stg          = 3'd0;
   initial stg_v        = 1'b0;

    reg [2:0] nxt;
   // a press is only consumed in the decode phase
   wire match = (prog == 3'd3) && sym && !stg_v;

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
           if (!stg_v) begin
               // decode phase: consume the press, stage the new progress
               stg       <= nxt;
               stg_v     <= 1'b1;
               seen_half <= seen_half | (nxt == 3'd2);
               alarm     <= match;
               if (match)
                   before_alarm <= 1'b0;
           end else begin
               // commit phase: retire the staged progress into the matcher
               prog      <= stg;
               stg_v     <= 1'b0;
               alarm     <= 1'b0;
               if (stg == 3'd0)
                   seen_half <= 1'b0;   // matcher restarted from scratch
           end
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
           gq  <= g;
           s1  <= gq;
            s2  <= s1;
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
    output wire       o_full
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

   // run-length coalescing: consecutive samples aimed at one bin are counted
   // here and folded into that bin register with a single add
   localparam [1:0] PMAX = 2'd3;

   reg [1:0] pend;      // samples staged but not yet folded into a bin
   reg [1:0] pend_sel;  // bin the staged samples belong to

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
   initial pend     = 2'd0;
   initial pend_sel = 2'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);
   wire same  = (i_sel == pend_sel);
   // window already shut: commit whatever is still staged on the next beat
   wire drain = i_ce && !take;
   wire fold  = (pend != 2'd0) && (drain || (take && (!same || pend == PMAX)));
   wire [2:0] fold_amt = (take && same) ? 3'd4 : {1'b0, pend};

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
           pend     <= 2'd0;
           pend_sel <= 2'd0;
       end else begin
           if (fold) begin
               case (pend_sel)
                   2'd0: bin0 <= bin0 + {1'b0, fold_amt};
                   2'd1: bin1 <= bin1 + {1'b0, fold_amt};
                   2'd2: bin2 <= bin2 + {1'b0, fold_amt};
                   2'd3: bin3 <= bin3 + {1'b0, fold_amt};
               endcase
           end
           if (take) begin
               pend_sel <= i_sel;
               pend     <= same ? ((pend == PMAX) ? 2'd0 : pend + 2'd1)
                                : 2'd1;
               total    <= total + 4'd1;
           end else if (drain) begin
               pend <= 2'd0;
           end
       end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

   // ---- upstream credit counter: free slots the source may still fill ----
   reg [1:0]  space;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
       space   = 2'd2;
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

   // ---- credit counter: a slot is spent on push and returned on pop ----
   always @(posedge i_clk) begin
       if (i_reset)
           space <= 2'd2;
       else if (i_ce) begin
           if (do_push && !do_pop)
               space <= space - 2'd1;
           else if (do_pop && !do_push)
               space <= space + 2'd1;
       end
   end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
   assign o_upstream_ready = (space != 2'd0);
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

   // ---- Q: a hold-off grant means the stage had run out of upstream credit ----
   always @(posedge i_clk)
       if (pv && armed && g_hld)
           assert (space != 2'd2);

endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
    // up counter and down counter stepped by the same enable; their sum is 20
    reg [4:0] up;
    reg [4:0] dn;

   // debit staging: credits are folded into the batch total four at a time
   reg [2:0] pend;
   wire [4:0] taken = up + {2'b00, pend};

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;

    initial up          = 5'd0;
    initial dn          = 5'd20;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
   initial pend        = 3'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
            end else begin
                dn   <= dn - 5'd1;
               if (pend == 3'd3) begin
                   up   <= up + 5'd4;   // fold a full batch into the total
                   pend <= 3'd0;
               end else begin
                   pend <= pend + 3'd1;
               end
               mark <= mark | (taken == 5'd9);
            end
        end
    end

    // gray view of the shadow binary up counter (clock-domain-crossing flavour)
   assign o_gray    = taken ^ (taken >> 1);
    assign o_drained = (dn == 5'd0);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
   // Pointer advances are throttled to phase 0 so that either chain sees at
   // most one gray transition between two of its own samples.
   reg        phase;
  // Programmable pointer depth.  The wrap modulus is carried as a mask that
  // is always one less than a power of two; it is widened one bit at a time
  // by i_incr pulses while the destination domain is parked (i_ce low).
  // Moving the wrap point invalidates everything already in flight, so a
  // depth change also drains the pointer and both synchronizer shadows.
  reg  [3:0] wrap_mask;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
      wrap_mask  = 4'd1;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);
  // depth reconfiguration is only accepted while the destination domain is
  // idle, and only up to the full four-bit pointer range
  wire       cfg_widen = !i_ce && i_incr && (wrap_mask != 4'd15);

    always @(posedge clk) begin
       if (cfg_widen) begin
           // new wrap point: grow the mask and drain the pointer pipeline
           wrap_mask <= (wrap_mask << 1) | 4'd1;
           wbin      <= 4'd0;
           sync1     <= 4'd0;
           sync2     <= 4'd0;
           b1        <= 4'd0;
           b2        <= 4'd0;
           s1b       <= 4'd0;
           s2b       <= 4'd0;
           b1b       <= 4'd0;
           b2b       <= 4'd0;
       end else if (i_ce) begin
            // source pointer
          wbin  <= (wbin + ((i_incr && !phase) ? 4'd1 : 4'd0)) & wrap_mask;

            // synchronizer chain
           if (!phase) begin
               sync1 <= wgray;
               sync2 <= sync1;
           end else begin
               s1b   <= wgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
               b1    <= wbin;
               b2    <= b1;
           end else begin
               b1b   <= wbin;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
           if (skew_mux)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;

   // Input staging register: a pushed sample is captured here first and
   // enters the buffer on the following cycle.  Single-entry stage, so a
   // new push is refused while a sample is still in flight.
   reg       s_v;
   reg [7:0] s_d;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
   wire do_push = i_push && !w_full && !s_v;
    wire do_pop  = i_pop  && v0;
   // the staged sample enters the buffer once the tail slot is free, or
   // when a pop frees a slot in the same cycle
   wire do_land = s_v && (!w_full || do_pop);

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
       end else begin
           // input stage: capture a sample, release it once it has landed
           if (do_push) begin
               s_v <= 1'b1;
               s_d <= i_data;
           end else if (do_land) begin
               s_v <= 1'b0;
           end

           if (do_land && do_pop) begin
               // head leaves, the staged sample takes the freed head slot
               v0 <= 1'b1;
               d0 <= s_d;
               v1 <= 1'b0;
           end else if (do_land) begin
               if (!v0) begin
                   v0 <= 1'b1;
                   d0 <= s_d;
               end else begin
                   v1 <= 1'b1;
                   d1 <= s_d;
               end
               count <= count + 3'd1;
           end else if (do_pop) begin
               // tail slides down into the head slot
               v0    <= v1;
               d0    <= d1;
               v1    <= 1'b0;
               count <= count - 3'd1;
           end
           // no pop and nothing landing : the buffer idles, all state held
       end
    end

    assign o_valid = v0;
   assign o_full  = w_full || s_v;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module issue_token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire [1:0] i_req,     // dual-issue: 0, 1 or 2 slots want to issue
    output wire [1:0] o_grant,   // slots actually granted this cycle
    output reg  [3:0] tokens     // credits left in the bucket
);
    localparam [3:0] BURST  = 4'd8;   // bucket capacity
    localparam [2:0] PERIOD = 3'd5;   // refill timer period

    // thermometer-coded shadow of the bucket occupancy
    reg [7:0] bucket;
    // refill timer
    reg [2:0] tick_cnt;
   // peak-rate peer bucket: second credit counter metering the same traffic
   reg [3:0] tokens_b;
   // shared refill-credit bus: one credit per tick, one destination
   reg       cred_val;
   reg       cred_dst;   // 0 = mean bucket, 1 = peak bucket

    initial begin
        tokens   = 4'd0;
       tokens_b = 4'd0;
        bucket   = 8'h00;
        tick_cnt = 3'd0;
       cred_val = 1'b0;
       cred_dst = 1'b0;
    end

    wire       tick    = (tick_cnt == PERIOD);
    wire [1:0] req_c   = (i_req == 2'd3) ? 2'd2 : i_req;

    // grants are limited by available credits
   // a slot must be covered by BOTH buckets, so the burst is the tighter one
   wire [1:0] cap_a   = (tokens   >= {2'b00, req_c}) ? req_c : tokens[1:0];
   wire [1:0] cap_b   = (tokens_b >= {2'b00, req_c}) ? req_c : tokens_b[1:0];
   wire [1:0] n_drain = (cap_a < cap_b) ? cap_a : cap_b;

   // One refill credit per timer tick, shared by both buckets.  The capacity
   // check is done here in the arbiter, so the credit that comes back off the
   // bus one cycle later is applied straight to the counter.
   wire       a_full   = (tokens   == BURST);
   wire       b_full   = (tokens_b == BURST);
   wire       cred_new = tick && !(a_full && b_full);
   // round robin between the buckets, skipping one that has no room
   wire       sel_b    = b_full ? 1'b0 : (a_full ? 1'b1 : ~cred_dst);
   wire       do_ref   = cred_val && !cred_dst;
   wire       do_ref_b = cred_val &&  cred_dst;

    wire [7:0] b_ref   = do_ref ? {bucket[6:0], 1'b1} : bucket;
    wire [7:0] b_nxt   = b_ref >> n_drain;
    wire [3:0] t_nxt   = tokens + (do_ref ? 4'd1 : 4'd0) - {2'b00, n_drain};
   wire [3:0] t_b_nxt = tokens_b + (do_ref_b ? 4'd1 : 4'd0) - {2'b00, n_drain};

    assign o_grant = i_ce ? n_drain : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens   <= 4'd0;
           tokens_b <= 4'd0;
            bucket   <= 8'h00;
            tick_cnt <= 3'd0;
           cred_val <= 1'b0;
           cred_dst <= 1'b0;
        end else if (i_ce) begin
            tokens   <= t_nxt;
           tokens_b <= t_b_nxt;
            bucket   <= b_nxt;
            tick_cnt <= tick ? 3'd0 : (tick_cnt + 3'd1);
           cred_val <= cred_new;
           if (cred_new)
               cred_dst <= sel_b;
        end
    end

    // P: whenever the credit counter reads empty, the thermometer shadow
    //    of the bucket must be empty as well.
    always @(posedge clk)
        if (tokens == 4'd0)
            assert (bucket == 8'h00);

endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // tail-slot occupancy is tracked in its own counter so each occupancy
    // bit sits next to the data register it describes; o_count is the sum.
    reg [1:0] tcnt;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial tcnt  = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            tcnt  <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            // per-slot occupancy update: a push fills the head counter first
            // and spills into the tail counter, a pop borrows from the tail
            // counter whenever the tail slot is loaded, so the head counter
            // only clears on the final drain.
            if (do_push && !do_pop) begin
                if (count == 2'd0) count <= 2'd1;
                else               tcnt  <= 2'd1;
            end else if (do_pop && !do_push) begin
                if (tcnt != 2'd0) tcnt  <= 2'd0;
                else              count <= 2'd0;
            end
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = v1;
    assign o_count  = count + tcnt;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);
endmodule

module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
output wire [3:0] o_rows,
output reg  [3:0] o_ce_beats
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
    reg [3:0] rows;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
    initial rows    = 4'd0;
initial o_ce_beats = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
            rows    <= 4'd0;
o_ce_beats <= 4'd0;
        end else if (i_ce) begin
o_ce_beats <= o_ce_beats + {3'd0, i_start};
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                        ready   <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                        ready   <= 1'b1;
                    end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                    ready   <= 1'b0;
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                end
            endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= incr && (i_bin == 2'd1);
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
  // mixed with the current bin index for a cheap activity signature.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
          o_act   <= ce_hist ^ {2'b00, i_bin};
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
           else if (dec == 5'b10000)  // WRITE phase has reached o_phase
                win <= 1'b0;               // R: the job retires
        end
    end

    assign o_phase = dec;
    assign o_busy  = win;

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
    wire [5:0] req = window & ~hold & ~gnt_q & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
    wire       have_credit = (pool > {3'b0, q_any});
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

    wire [5:0] gnt     = have_credit ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
    gnt_q <= gnt;
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold);
// the parked record is promoted out of the skid slot into the main slot
wire       main_wr_skid = i_ce && m_valid && i_ready && hold;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + p_occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
           else if (main_wr_skid)
               occ <= {1'b0, ~s_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
           else if (main_wr_skid)
               p_occ <= {1'b0, s_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
    // backpressure: while the array is draining no further launch is accepted
    reg              draining;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;
    initial draining = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire launch_ok = i_launch && armed && !draining;
    wire accept = i_ce && launch_ok;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
    draining <= 1'b0;
        end else if (i_ce) begin
    pipe    <= { pipe[STAGES-2:0], launch_ok };
    cnt     <= cnt + (launch_ok        ? 3'd1 : 3'd0)
                   - (pipe[STAGES-1]   ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
    started <= started || launch_ok;
    // enter drain mode when every stage is occupied, leave it as the
    // last outstanding request retires
    draining <= draining ? !((cnt == 3'd1) && pipe[STAGES-1])
                         : (cnt == 3'd4);
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Backpressure sanity: drain mode is only ever held while a request was
    // really launched and work is still moving through the stage array.
    always @(posedge clk)
        if (draining)
            assert (started && (pipe != {STAGES{1'b0}}));

endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
// Grants now ping-pong between two sinks, each with its own 8-cycle window;
// the spacing rule is held in one cooldown counter shared by both sinks.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid
    reg [7:0] win_b = 8'b0000_0000;  // sink B's window, same 8-cycle depth
    reg [1:0] cool  = 2'd0;          // shared spacing cooldown, loaded by either sink
    reg       sel   = 1'b0;          // ping-pong pointer: 0 = next grant goes to sink A

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule, now carried by the shared cooldown: a grant to either sink
    // blocks the shared issue path for the following two cycles
    wire allow = (cool == 2'd0);
    wire g     = ce && req && allow;
    wire to_b  = sel;                // this grant is tagged for sink B

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win   <= {win[6:0], g && !to_b};
            win_b <= {win_b[6:0], g && to_b};
            ones  <= ones + ((g && !to_b) ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
            cool  <= g ? 2'd2 : ((cool == 2'd0) ? 2'd0 : cool - 2'd1);
            if (g)
                sel <= ~sel;
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack
    reg [3:0] slack;    // remaining scan budget exported to the prefetch stride

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;
    initial slack   = LIMIT;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
            slack   <= LIMIT;
        end else if (i_ce) begin
            // plenty of budget left => the scanner may consume two
            // characters in a single step
            pos <= pos + ((slack > 4'd8) ? 8'd2 : 8'd1);
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
                slack   <= LIMIT;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
                if (wd != LIMIT)
                    wd <= (wd > 4'd4) ? (wd - 4'd4) : 4'd0;
                // partial credit also refunds budget, capped at the reload value
                if (slack != 4'd0)
                    slack <= (slack < 4'd8) ? (slack + 4'd4) : LIMIT;
            end else begin
                // no progress this step: count up and saturate at LIMIT
                if (wd != LIMIT) begin
                    wd <= wd + 4'd1;
                    if ((wd + 4'd1) == LIMIT)
                        expired <= 1'b1;
                end
                // spend one unit of budget per idle step, floor at zero
                if (slack != 4'd0)
                    slack <= slack - 4'd1;
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);

    // Q: a reported timeout means the exported scan budget is exhausted,
    // so downstream stride logic has already dropped back to one char/step.
    always @(posedge clk) assert (!expired || slack == 4'd0);
endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
    output wire       o_drained
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    // commit-stage register: the next beat count is held here for one cycle
    // before it is written into the beats-remaining counter
    reg [3:0] stg_beats;
    reg       stg_vld;

    // forwarded count: the in-flight value whenever a commit is pending
    wire [3:0] beats_cur = stg_vld ? stg_beats : beats_left;


    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;
    initial stg_beats  = 4'd0;
    initial stg_vld    = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
            stg_beats  <= 4'd0;
            stg_vld    <= 1'b0;
        end else if (i_ce) begin
            // commit stage: the registered count reaches the counter
            if (stg_vld) begin
                beats_left <= stg_beats;
                stg_vld    <= 1'b0;
            end
            // issue stage: a descriptor load or a beat retire posts the new
            // status flags now and hands the count to the commit stage
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                stg_beats  <= i_len;
                stg_vld    <= 1'b1;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
                // retire one beat off the forwarded count
                stg_beats  <= beats_cur - 4'd1;
                stg_vld    <= 1'b1;
                busy       <= (beats_cur != 4'd1);
                drained    <= (beats_cur <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen
   reg       run;        // time base (gray counter) is spinning
   reg [1:0] park;       // spin-down tail before the time base parks

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
       run       = 1'b0;
       park      = 2'd0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    wire [3:0] goal_bin = bin + K;

   // a deadline can only be tracked once the time base is already spinning;
   // a request that arrives with the counter parked just spins it up
   wire accept = i_ce && armed && req && !busy && run;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
           // ... but only while the time base is unparked
           if (run) begin
               bin  <= bin_nxt;
               gray <= gray_nxt;
           end

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

           // time-base clock gate: any request spins the counter up, and it
           // keeps spinning for a short tail after the last deadline retires
           if (req) begin
               run  <= 1'b1;
               park <= 2'd3;
           end else if (busy) begin
               park <= 2'd3;
           end else if (run) begin
               if (park != 2'd0) park <= park - 2'd1;
               else              run  <= 1'b0;
           end

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
   assign o_busy    = busy || run;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // anticipated carry out of the low half of cnt, registered a cycle early
    // so the wrap term never ripples across all four counter bits
    reg lo_tc;
    // two-flop synchronizer carrying the gray pointer into the other domain
// first stage is split in two: the low pair re-samples on every enabled
// cycle, the upper pair only while armed, because the upper gray bits can
// only move on the cycle after the low half of the counter wraps, so the
// wide upper flops need not toggle their sample the rest of the time
reg [1:0] s1_lo;
reg [1:0] s1_hi;
reg       hi_arm;   // upper-pair re-sample window
wire [3:0] s1 = {s1_hi, s1_lo};
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
s1_lo  = 2'd0;
s1_hi  = 2'd0;
hi_arm = 1'b0;
        s2  = 4'd0;
        lo_tc = 1'b0;
    end

    wire [1:0] nxt_lo   = cnt[1:0] + 2'd1;
    wire [1:0] nxt_hi   = cnt[3:2] + {1'b0, lo_tc};
    wire [3:0] nxt      = {nxt_hi, nxt_lo};
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
s1_lo <= g[1:0];
if (hi_arm)
    s1_hi <= g[3:2];
hi_arm <= lo_tc;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
reg [3:0] pipe_a;
// second identical unit; both share the single issue port
reg [3:0] pipe_b;
// round-robin pointer: which unit takes the next accepted op
reg       sel;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;

initial pipe_a   = 4'b0000;
initial pipe_b   = 4'b0000;
initial sel      = 1'b0;
    initial inflight = 3'd0;
    initial armed    = 1'b0;

wire retire_a = pipe_a[3];
wire retire_b = pipe_b[3];
wire retire   = retire_a | retire_b;
// the arbiter hands each accepted op to exactly one unit
wire take_a   = issue && !sel;
wire take_b   = issue &&  sel;

    always @(posedge clk) begin
        if (rst) begin
pipe_a   <= 4'b0000;
pipe_b   <= 4'b0000;
sel      <= 1'b0;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe_a   <= {pipe_a[2:0], take_a};
pipe_b   <= {pipe_b[2:0], take_b};
if (issue)
sel  <= ~sel;
inflight <= inflight + {2'b00, issue} - {2'b00, retire_a} - {2'b00, retire_b};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;
  // minimum re-trigger interval: enabled samples elapsed since the last
  // accepted match (saturating), plus a flag marking that one has been
  // accepted at all, so the very first match is never suppressed
  reg [3:0] gap;
  reg       seen_hit;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial gap         = 4'd0;
  initial seen_hit    = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

  // a completed match is only accepted by the counter once the re-trigger
  // interval has elapsed since the previous accepted match
  wire       accept   = (prog == 3'd4) && (!seen_hit || gap >= 4'd8);

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
           gap         <= 4'd0;
           seen_hit    <= 1'b0;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
          cmt_vld <= accept;

          // re-trigger timer: cleared by an accepted match, otherwise
          // counts enabled samples up to its saturation point
          if (accept) begin
              gap      <= 4'd0;
              seen_hit <= 1'b1;
          end else if (gap != 4'd15) begin
              gap <= gap + 4'd1;
          end
           if (cmt_vld)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Re-trigger bookkeeping, global: the interval logic can only have armed
   // itself behind an occurrence of the pattern prefix 101.
   always @(posedge clk)
       assert (!seen_hit || saw_p3);
endmodule

module pingpong_rotbuf (
    input  wire        clk,
    input  wire        step,      // enable / idle when low
    input  wire [15:0] din,
    input  wire [3:0]  amt,
    output reg  [15:0] dout,
    output wire        wr_half,
    output wire        rd_half
);
    // ------------------------------------------------------------------
    // one-cycle barrel rotator (staged shift-by-1/2/4/8 collapses to this)
    // ------------------------------------------------------------------
    wire [31:0] dbl = {din, din};
    wire [15:0] rot = dbl[15:0] >> amt | dbl[31:16] << (16 - amt);

    // ------------------------------------------------------------------
    // ping-pong double buffer: 2 halves of 4 words.
    // address = {half_select, index}
    // ------------------------------------------------------------------
    reg [2:0] waddr;
    reg [2:0] raddr;
    reg [15:0] mem [0:7];
    reg        pv;

   // registered write path: the rotate result and its destination slot are
   // captured on one enabled cycle and retired into the array on the next.
   reg [15:0] wdat_q;
   reg [2:0]  wadr_q;
   reg        wval_q;

   // per-port bank arbiter grant, raised one index ahead of the wrap so the
   // half-select mux is driven by a register instead of a comparator.
   reg        wsw_q;
   reg        rsw_q;

    integer i;
    initial begin
        waddr = 3'b000;   // writer starts in half 0
        raddr = 3'b100;   // reader starts in half 1
        dout  = 16'h0000;
        pv    = 1'b0;
       wdat_q = 16'h0000;
       wadr_q = 3'b000;
       wval_q = 1'b0;
       wsw_q  = 1'b0;
       rsw_q  = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 16'h0000;
    end

    assign wr_half = waddr[2];
    assign rd_half = raddr[2];

    // each side flips its own half when its own index field wraps
   // grant is requested one slot early and consumed on the wrap itself
   wire wgrant = (waddr[1:0] == 2'b10);
   wire rgrant = (raddr[1:0] == 2'b10);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (step) begin
           // stage 1: capture the rotated word and where it belongs
           wdat_q <= rot;
           wadr_q <= waddr;
           wval_q <= 1'b1;

           // stage 2: retire the word captured on the previous enabled cycle
           if (wval_q) mem[wadr_q] <= wdat_q;

           wsw_q <= wgrant;
           rsw_q <= rgrant;

            dout       <= mem[raddr];

           waddr <= {wsw_q ? ~waddr[2] : waddr[2], waddr[1:0] + 2'b01};
           raddr <= {rsw_q ? ~raddr[2] : raddr[2], raddr[1:0] + 2'b01};
        end
    end

    // ------------------------------------------------------------------
    // P: whenever the writer migrates up into the high half, the reader
    //     must at that moment be sitting in the low half.
    // ------------------------------------------------------------------
    always @(posedge clk)
        if (pv && $rose(waddr[2]))
            assert (raddr[2] == 1'b0);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
               if (cmt_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= cmt_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= cmt_val;
               end
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;
  // posted-increment ledger: chain steps logged by the sequencer (n_iss) and
  // steps already folded into the carry-save halves (n_cmt)
  reg [3:0] n_iss, n_cmt;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
      n_iss      = 4'd0;
      n_cmt      = 4'd0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
  // done is only reported once every logged step has been folded in
  assign o_done  = ((total == 4'd3) || b_done) && (n_iss == n_cmt);

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
   wire adv2 = i_ce && (ph_ref == 3'd3) &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
  wire iss = adv || adv2;
  // one outstanding logged step is folded per enabled cycle
  wire inc = i_ce && (n_iss != n_cmt);

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
          n_iss      <= 4'd0;
          n_cmt      <= 4'd0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

          // ledger both sides: log the sequencer step, drain into the halves
          if (iss) n_iss <= n_iss + 4'd1;
          if (inc) n_cmt <= n_cmt + 4'd1;

           if (inc) begin
              // split increment: the halves re-sum to the drained step count
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
               tog <= ~tog;
           end

           if (adv) begin
               ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end

           if (adv2) begin
               ph_ref2 <= ph_ref2 + 3'd1;
               if (ph_ref2 == 3'd2) b_done <= 1'b1;
           end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;

   // raw four-bit history of the input stream, win[3] oldest, win[0] newest
   reg [3:0] win;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial win         = 4'b0000;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           win         <= 4'b0000;
        end else if (ce) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // keep the raw bit history in step with the match FSM
           win    <= {win[2:0], din};

            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
               // cross-check the FSM against the raw history before counting
               if (win == PAT)
                   match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Redundancy check: a flagged match must agree with the raw bit history
   // and must have been preceded by the 101 prefix.
   always @(posedge clk)
       if (!rst) assert (prog != 3'd4 || (saw_p3 && win == PAT));
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
    output wire o_mon
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;
   // issues are staged for one enabled cycle before joining the window count
   reg [1:0] stg;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
   initial stg     = 2'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;

   // total window occupancy: committed entries plus staged entries
   wire [4:0] occ = {1'b0, out_r} + {3'b0, stg};
   wire acc_iss = i_ce && i_issue  && (occ < {1'b0, WINDOW});
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);
   // one staged entry is absorbed into the window counter per enabled cycle
   wire cmt = i_ce && (stg != 2'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
           stg   <= 2'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
           if (cmt && !acc_ret)
               out_r <= out_r + 4'd1;
           else if (!cmt && acc_ret)
               out_r <= out_r - 4'd1;
           if (acc_iss && !cmt)
               stg <= stg + 2'd1;
           else if (!acc_iss && cmt)
               stg <= stg - 2'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
            empty_q <= (iss == ret);
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

    wire do_on  = req_on  && !zone[i_zone] && (budget != 4'd0);
    wire do_off = req_off &&  zone[i_zone];

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
        end else if (do_on) begin
            zone[i_zone] <= 1'b1;
            zpar         <= ~zpar;      // one data bit flips, parity flips
            nact         <= nact + 4'd1;
            budget       <= budget - 4'd1;
        end else if (do_off) begin
            zone[i_zone] <= 1'b0;
            zpar         <= ~zpar;
            nact         <= nact - 4'd1;
            budget       <= budget + 4'd1;
        end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);

   // P2: with all heaters off the controller must have handed every power
   //     slot back to the pool, and an all-zero slice must read as intact.
   always @(posedge i_clk)
       if (!heating)
           assert (budget == BUDGET && !fault);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

   // Bit mask of every stage that must be recorded before routing completes.
   localparam [7:0] TRAIL_PRE = 8'h3F;

    reg [3:0] nxt;
   reg [7:0] seen;   // sticky audit trail of the stages this board went through

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
       seen     = 8'h01;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
           seen     <= 8'h01;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
           if (nxt == S_IDLE)
               seen <= 8'h01;                  // new board: restart the trail
           else
               seen <= seen | (8'b1 << nxt);   // record the stage we enter
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
           else if (nxt == S_ROUTE && ((seen | (8'b1 << S_ROUTE)) == TRAIL_PRE))
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);

   // P2: the export window only opens on a fully documented run, so while the
   // window is armed every pre-route stage is present in the audit trail.
   always @(posedge clk)
       if (tracking)
           assert ((seen & TRAIL_PRE) == TRAIL_PRE);
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
output reg  [2:0] occ,       // queries in flight
output reg  [3:0] retire_cnt // rolling count of retired queries
);

    reg [3:0] pipe;              // fixed-latency valid shift register
    reg       hold;              // input capture slot: query admitted while stalled
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full
reg       retire_seen;        // sticky: at least one retirement observed

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
        hold        = 1'b0;
retire_cnt  = 4'd0;
retire_seen = 1'b0;
    end

    assign retire = pipe[3];
    assign full   = (occ == 3'd4);

    // Admission control: the tracker backpressures at capacity, and a query
    // taken while the pipe is not advancing waits in the capture slot.
    wire room   = (occ != 3'd4);
    wire accept = issue && !hold && room;   // query admitted this cycle
    wire inject = hold || accept;           // entry pushed into stage 0

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
            pipe <= {pipe[2:0], inject};

            // occupancy bookkeeping: +1 on issue, -1 on retire
            occ  <= occ + {2'b00, accept} - {2'b00, pipe[3]};
            hold <= 1'b0;

            // shadow register for the earlier event
            if (accept) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end else if (accept) begin
            // stalled: park the admitted query and count it as in flight
            hold        <= 1'b1;
            occ         <= occ + 3'd1;
            ever_issued <= 1'b1;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

// Distractor telemetry: counts retirements, observed by nothing else.
always @(posedge clk) begin
    if (ce && pipe[3]) begin
        retire_seen <= 1'b1;
        retire_cnt  <= retire_cnt + (retire_seen ? 4'd2 : 4'd1);
    end
end

endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
   reg [3:0]  dcnt;    // data bits already shifted into sr this frame: 0..8
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;
   reg [3:0]  n_acq;   // ledger: frames acquired off the line (start bit seen)
   reg [3:0]  n_rel;   // ledger: frames released to the consumer (take at STOP)
   reg        active;  // a frame is in flight according to the ledger

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
   initial dcnt  = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
   initial active = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
   wire adv       = ce && active && (startb || datab); // only count phases in flight
    wire done      = ce && stopb  && take;

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
           dcnt  <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
           n_acq  <= 4'd0;
           n_rel  <= 4'd0;
           active <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
           if (start_det || done) dcnt <= 4'd0;
           else if (datab)        dcnt <= dcnt + 4'd1;
           if (done)          ferr  <= !rx || (dcnt != 4'd8); // stop bit high and a full byte
           // frame ledger: one acquire per start bit, one release per handoff
           if (start_det)     n_acq  <= n_acq + 4'd1;
           if (done)          n_rel  <= n_rel + 4'd1;
           if (start_det)     active <= 1'b1;
           else if (done)     active <= 1'b0;
        end
    end

   // with no byte parked, the data bus reads back the ledger for diagnostics
   assign o_data = stopb ? sr : {n_acq, n_rel};
    assign o_ferr = ferr;
   assign o_busy = !idle || active;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);

   // P2: dcnt lags the phase index by the START phase plus the one-cycle
   // capture lag, so inside a frame it is always nbits-2 bits deep.
   always @(posedge clk)
       if (pv && o_busy && nbits >= 4'd2)
           assert (dcnt == nbits - 4'd2);
endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
reg [3:0] beats_left;   // beats not yet handed to a sub-request
reg [2:0] chunk;        // beats outstanding in the current sub-request
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain

    initial beats_left = 4'd0;
initial chunk      = 3'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;

    // the downstream port's beat-count field is 3 bits, so a burst is
    // handed over in sub-requests of at most 7 beats
    wire [2:0] first_chunk = (i_beats    > 4'd7) ? 3'd7 : i_beats[2:0];
    wire [2:0] next_chunk  = (beats_left > 4'd7) ? 3'd7 : beats_left[2:0];

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
chunk      <= 3'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
chunk      <= first_chunk;
beats_left <= i_beats - {1'b0, first_chunk};
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
// retire one beat of the current sub-request
if (chunk == 3'd1) begin
    // sub-request drained: hand the next slice to the port
    chunk      <= next_chunk;
    beats_left <= beats_left - {1'b0, next_chunk};
end else if (chunk != 3'd0) begin
    chunk <= chunk - 3'd1;
end
if ((chunk <= 3'd1) && (beats_left == 4'd0))
                busy <= 1'b0;
            if (busy)
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
    assign o_beat = busy && i_ce;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
    output wire [3:0] o_avail
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;
   // per-lane outstanding credits: two clients share the one shelf
   reg [3:0] out_a;
   reg [3:0] out_b;
   // round-robin pointer: whose request is charged next
   reg       turn;
   // registered arbiter grant: the shelf port moves one credit per cycle
   reg       gnt_a;
   reg       gnt_b;
   reg       gnt_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;

   wire [3:0] lane_out = turn ? out_b : out_a;
   wire       arb_idle = !gnt_a && !gnt_b;

   // a request is only latched while the shared shelf port is free
   wire accept = i_ce && arb_idle &&
                 (i_take ? (used != CAP) : (lane_out != 4'd0));

   // commit of the move the arbiter granted last cycle
   wire take_fire = (gnt_a || gnt_b) &&  gnt_take;
   wire give_fire = (gnt_a || gnt_b) && !gnt_take;

   wire [3:0] out_a_nxt = gnt_a ? (gnt_take ? out_a + 4'd1 : out_a - 4'd1) : out_a;
   wire [3:0] out_b_nxt = gnt_b ? (gnt_take ? out_b + 4'd1 : out_b - 4'd1) : out_b;

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
           out_a <= 4'd0;
           out_b <= 4'd0;
           turn  <= 1'b0;
           gnt_a <= 1'b0;
           gnt_b <= 1'b0;
           gnt_take <= 1'b0;
       end else if (i_ce) begin
           // stage 1: arbitrate this cycle's request
           gnt_a    <= accept && !turn;
           gnt_b    <= accept &&  turn;
           gnt_take <= i_take;
           if (accept)
               turn <= ~turn;

           // stage 2: retire the move granted last cycle
           out_a <= out_a_nxt;
           out_b <= out_b_nxt;
           used  <= out_a_nxt + out_b_nxt;   // running total over both lanes
           if (take_fire)
               avail <= avail - 4'd1;        // stepped down, single shelf port
           else if (give_fire)
               avail <= avail + 4'd1;
       end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
    output wire [3:0] o_snap
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;

  // Read-port ledger: every bin-0 population read issued into the snapshot
  // pipeline is logged here, and so is every read that comes back out of it.
  // Both counters run free and wrap at four bits.
  reg [3:0] n_req, n_done;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
  initial n_req  = 4'd0;
  initial n_done = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

   // Bin 3 is the out-of-range bucket: such a sample closes the current
   // measurement window, so every bin-0 read still walking the snapshot
   // pipeline is aborted on that cycle.
   wire sn_flush = i_ce && (i_bin == 2'd3);

   // read issue / read return events on the single snapshot read port
   wire sn_req = incr && (i_bin == 2'd1) && !sn_flush;
   wire sn_ret = i_ce && v4 && !sn_flush;

   // reads currently owning the read port, as seen by the ledger
   wire [3:0] sn_busy = n_req - n_done;

   // The total register has one write port, shared by the sample path and
   // the read-return path, so a sample that issues a snapshot read is not
   // counted until its read returns.  An abort credits, in a single cycle,
   // every sample whose read is still in flight.
   wire [5:0] tot_inc = ((incr && !sn_req) ? 6'd1 : 6'd0)
                      + (sn_ret            ? 6'd1 : 6'd0)
                      + (sn_flush ? {2'b00, sn_busy} : 6'd0);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
        end
       total <= total + tot_inc;
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= sn_flush ? 1'b0 : sn_req;
           sn2 <= sn1;
           v2  <= sn_flush ? 1'b0 : v1;
           sn3 <= sn2;
           v3  <= sn_flush ? 1'b0 : v2;
           sn4 <= sn3;
           v4  <= sn_flush ? 1'b0 : v3;
           if (sn_ret)
               snap <= sn4;
       end
   end

  // Read-port ledger update: one log entry per issued read, one per return.
  always @(posedge clk) begin
      if (sn_req)
          n_req <= n_req + 4'd1;
      if (sn_flush)
          n_done <= n_req;              // the abort returns them all at once
      else if (sn_ret)
          n_done <= n_done + 4'd1;
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
// A match is only declared once the capture window has been primed with four
// genuinely received bits: the match target (goal) starts above the reachable
// progress range and is stepped down to the pattern length, one step per
// probed bit, as the post-reset filler is shifted out of win.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
    reg [3:0] win;         // last four bits received, MSB = oldest
    reg [3:0] goal;        // progress value that completes a match: 4 once the
                           // window is primed, >4 while win still holds filler

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
        win    = 4'b0000;
        goal   = 4'd7;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            prog   <= nprog;
            hot    <= nhot;
            win    <= {win[2:0], i_bit};
            if (goal != 4'd4)
                goal <= goal - 4'd1;      // one filler slot retired per bit
            detect <= (nprog == goal);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end
endmodule

// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
    output wire busy
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;
    localparam [1:0] QDEPTH = 2'd2;   // staging queue in front of the window

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [1:0] queued;   // accepted, still waiting for a free window slot
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        queued  = 2'd0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    assign busy = (outst != 3'd0) || (queued != 2'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);

    wire [2:0] total = outst + {1'b0, queued};

    // accept while the window plus the staging queue still has capacity
    wire do_issue  = ce && issue && (total < (WINDOW + {1'b0, QDEPTH}));
    wire do_retire = ce && (outst != 3'd0) && (retire || force_ret);

    // a window slot is free, or is being freed by this cycle's retirement
    wire slot_free = (outst < WINDOW) || do_retire;
    // a staged transaction is older than an incoming one, so it goes first
    wire admit  = ce && (queued != 2'd0) && slot_free;
    wire direct = do_issue && slot_free && !admit;
    wire enq    = do_issue && !direct;

    wire [2:0] outst_n  = outst + ((admit || direct) ? 3'd1 : 3'd0)
                                - (do_retire ? 3'd1 : 3'd0);
    wire [1:0] queued_n = queued + (enq ? 2'd1 : 2'd0)
                                 - (admit ? 2'd1 : 2'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;
        queued <= queued_n;

        if (do_issue || do_retire) begin
            // any scoreboard event restarts (or clears) the deadline
            if (outst_n == 3'd0 && queued_n == 2'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
    output wire [3:0] o_remain
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

   // Update stage: the tick arithmetic is registered for one cycle before
   // it commits, so an update issued on a ce cycle lands on the cycle
   // after it was issued.
   reg [3:0] cnt_stg;
   reg [3:0] rem_stg;
   reg       stg_vld;

   // Forwarding: a pending stage value is newer than the committed
   // register, so back-to-back ticks are computed from the stage.
   wire [3:0] cnt_eff = stg_vld ? cnt_stg : cnt;
   wire [3:0] rem_eff = stg_vld ? rem_stg : rem;

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;
   initial cnt_stg = 4'd0;
   initial rem_stg = TIMEOUT;
   initial stg_vld = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
           cnt_stg <= 4'd0;
           rem_stg <= TIMEOUT;
           stg_vld <= 1'b0;
       end else begin
           // Drain the stage: the in-flight update commits one cycle after
           // it was issued, whether or not a new tick arrives.
           if (stg_vld) begin
               cnt <= cnt_stg;
               rem <= rem_stg;
           end
           stg_vld <= 1'b0;

           if (i_ce) begin
           stg_vld <= 1'b1;
           if (i_kick) begin
               cnt_stg <= 4'd0;
               rem_stg <= TIMEOUT;
           end else begin
               cnt_stg <= (cnt_eff < TIMEOUT) ? cnt_eff + 4'd1 : cnt_eff;
               rem_stg <= (rem_eff != 4'd0) ? rem_eff - 4'd1 : rem_eff;
           end

            if (i_ack)
                latched <= 1'b0;
           else if (!i_kick && (rem_eff == 4'd1))
                latched <= 1'b1;
        end
       end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
           else if (dec == 5'b10000)  // WRITE phase has reached o_phase
                win <= 1'b0;               // R: the job retires
        end
    end

    assign o_phase = dec;
    assign o_busy  = win;

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));

   // P2: a busy job showing phase 0 on o_phase is the launch cycle, so the
   // decode stage must already be carrying the FETCH phase behind it
   always @(posedge i_clk)
       assert (!win || (dec != 5'b00001) || (dec_s == 5'b00010));
endmodule

module seq_detect_1011 (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       din,
    output wire       match,
    output wire [3:0] hits
);
    // fixed pattern, MSB first: 1 0 1 1
    localparam [3:0] PAT = 4'b1011;

    // match-progress register: number of leading pattern bits matched so far,
    // never exceeds the pattern length (4)
    reg [2:0] prog;
    // shadow register: records that progress 3 (pattern prefix 101) was
    // observed at some earlier cycle
    reg       saw_p3;
    // saturating count of completed pattern matches consumed
    reg [3:0] match_count;
   // commit-stage flag: a detected match is posted here and lands in the
   // counter on the next enabled cycle, keeping the counter adder off the
   // detector's critical path
   reg       cmt_vld;

  // sticky saturation lock: if the counter is already topped out when a
  // match credit retires, the credit is dropped and the reading is frozen,
  // so software can tell "exactly 15" from "15 or more"
  reg       sat_lock;
 // census of match credits that retired into an already-locked counter;
 // firmware uses it to bound how far the frozen reading undercounts
 reg [3:0] drop_cnt;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial sat_lock    = 1'b0;
 initial drop_cnt    = 4'd0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
    wire       restart  = (din == PAT[3]) ? 1'b1 : 1'b0;
   // overflow park: once the census tops out the scan is frozen so the
   // count, the census and the detector state stay mutually consistent
   wire       park     = (drop_cnt == 4'd15);

    assign match = (prog == 3'd4);
    assign hits  = match_count;

    always @(posedge clk) begin
        if (rst) begin
            prog        <= 3'd0;
            saw_p3      <= 1'b0;
            match_count <= 4'd0;
           cmt_vld     <= 1'b0;
          sat_lock    <= 1'b0;
         drop_cnt    <= 4'd0;
       end else if (ce && !park) begin
            // shadow bit latches the earlier occurrence of progress 3
            saw_p3 <= saw_p3 | (prog == 3'd3);
           // post a credit for a completed match; retire the credit posted
           // by the previous enabled cycle
           cmt_vld <= (prog == 3'd4);
          if (cmt_vld)
              sat_lock <= sat_lock | (match_count == 4'd15);
          if (cmt_vld && !sat_lock)
               match_count <= (match_count == 4'd15) ? 4'd15 : match_count + 4'd1;
         // tally the credit we just threw away; the park above guarantees
         // this adder cannot wrap
         if (cmt_vld && sat_lock)
             drop_cnt <= drop_cnt + 4'd1;


            if (prog == 3'd4) begin
                // consume the completed match, then begin a fresh scan
                prog        <= restart ? 3'd1 : 3'd0;
            end else if (din == exp_bit) begin
                prog <= prog + 3'd1;
            end else begin
                prog <= restart ? 3'd1 : 3'd0;
            end
        end
    end

    // Precedence, global: any counted match must have been preceded by the
    // pattern prefix reaching progress 3.
    assert property (match_count == 4'd0 || saw_p3);

   // Saturation lock is a consequence of counted traffic: it can only engage
   // after the counter has been driven to full, so the exported count is
   // nonzero and the pattern prefix must already have been seen.
   always @(posedge clk)
       assert (!sat_lock || (saw_p3 && hits != 4'd0));
  // Credits are only discarded against a full, locked counter, so any
  // nonzero census means the exported reading is pinned at maximum and the
  // pattern prefix was seen long ago.
  always @(posedge clk)
      assert (drop_cnt == 4'd0 || (saw_p3 && hits == 4'd15));
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

   // ---- upstream credit counter: free slots the source may still fill ----
   reg [1:0]  space;

  // ---- registered full flag: the upstream gate stays shut one extra cycle ----
  reg        full_r;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
       space   = 2'd2;
       full_r  = 1'b0;
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

   // ---- credit counter: a slot is spent on push and returned on pop ----
   always @(posedge i_clk) begin
       if (i_reset)
           space <= 2'd2;
       else if (i_ce) begin
           if (do_push && !do_pop)
               space <= space - 2'd1;
           else if (do_pop && !do_push)
               space <= space + 2'd1;
       end
   end

  // ---- full flag registered off the occupancy counter for the gate timing path ----
  always @(posedge i_clk) begin
      if (i_reset)
          full_r <= 1'b0;
      else if (i_ce)
          full_r <= (occ == 2'd2);
  end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
  assign o_upstream_ready = (space != 2'd0) && !full_r;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

   // ---- Q: a hold-off grant means the stage had run out of upstream credit ----
   always @(posedge i_clk)
       if (pv && armed && g_hld)
           assert (space != 2'd2);

  // ---- R: a latched full gate means a record is still parked in the stage
  //      and its upstream credit has not been returned ----
  always @(posedge i_clk)
      if (pv && armed && full_r)
          assert (m_valid && space != 2'd2);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;
// credit-return path: a retired op's credit takes four more cycles to walk
// back from the pipe tail to the issue-side credit counter
reg       rq0;
reg       rq1;
reg       rq2;
reg       rq3;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;
initial rq0      = 1'b0;
initial rq1      = 1'b0;
initial rq2      = 1'b0;
initial rq3      = 1'b0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// nothing still travelling back down the credit-return path
wire rq_empty = !(rq0 || rq1 || rq2 || rq3);
// true quiesce: pipe drained, returns landed, nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && rq_empty && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
        end else begin
cred <= cred - {2'b00, accept} + {2'b00, rq3};
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

// credit-return path: retire pulses shift back toward the issue side
always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
    // up counter and down counter stepped by the same enable; their sum is 20
    reg [4:0] up;
    reg [4:0] dn;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;
    // ledger counters: one tick per credit handed out, one per credit back
    reg [4:0] n_iss;
    reg [4:0] n_ret;

    initial up          = 5'd0;
    initial dn          = 5'd20;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
    initial n_iss       = 5'd0;
    initial n_ret       = 5'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
                up          <= 5'd0;   // recharge with a fresh batch of 20
                dn          <= 5'd20;
                mark        <= 1'b0;   // new batch: halfway not passed yet
            end else if (n_iss == n_ret) begin
                // nothing outstanding: hand a credit to the consumer
                up    <= up + 5'd1;
                mark  <= mark | (up == 5'd9);
                n_iss <= n_iss + 5'd1;
            end else begin
                // the outstanding credit returns and is charged to the pool
                dn    <= dn - 5'd1;
                n_ret <= n_ret + 5'd1;
            end
        end
    end

    // gray view of the issue pointer (clock-domain-crossing flavour)
    assign o_gray    = n_iss ^ (n_iss >> 1);
    assign o_drained = (dn == 5'd0) && (n_iss == n_ret);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
   // increment ahead of the visible counter, so the output register has
   // no XOR chain in front of it.
reg [2:0] gray_pre;     // in-flight gray code for bin+1, low bits
// Bit 3 of a gray code is just bit 3 of the binary count, so the top
// bit skips the XOR network entirely and lives in its own register.
// It is only reloaded on the two counts where it can change, which
// keeps it from toggling with the rest of the pipeline.
reg       gray_pre_top;

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
gray_pre     = 3'd1;   // encoder prefilled with gray(bin+1)[2:0]
gray_pre_top = 1'b0;   // ... and its top bit
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
   wire [3:0] bin_ahead  = bin_nxt + 4'd1;
   wire [3:0] gray_ahead = bin_ahead ^ (bin_ahead >> 1);
// the held top bit only needs a new value as the count rolls into 8 or 0
wire       top_load  = (bin_ahead[2:0] == 3'd0);

    wire [3:0] goal_bin = bin + K;

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
gray_pre <= gray_ahead[2:0];
if (top_load) gray_pre_top <= bin_ahead[3];
gray     <= {gray_pre_top, gray_pre};

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg [1:0] bcnt;                 // back-half occupancy (stage 3 only)
reg       hand;                 // request in the stage1 -> stage2 handover

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial bcnt     = 2'd0;
initial hand     = 1'b0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
bcnt     <= 2'd0;
hand     <= 1'b0;
        end else if (step) begin
            inflight <= {inflight[2:0], req};
// each pipeline half maintains its own occupancy count locally.  The
// stage1 -> stage2 crossing is registered to keep the adder chains
// short: the front count drops the request on the advance that moves
// it out of stage 1, the handover latch carries it, and the back
// count picks it up on the following advance.
cnt      <= cnt  + {2'b00, req}           - {2'b00, inflight[1]};
bcnt     <= bcnt + {1'b0,  hand}          - {1'b0,  retire};
hand     <= inflight[1];
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0) && !hand;
assign f_full = ((cnt + {1'b0, bcnt} + {2'b00, hand}) == 3'd4);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred

   // Refill commit pipeline: the bucket adder/clamp is registered, so the
   // token target computed at a timer tick is applied four cycles later.
   // Layout of each stage: {valid, precomputed token target}.
   reg [4:0] rf_s1, rf_s2, rf_s3, rf_s4;

    wire       tick     = (timer == PERIOD);
    wire       do_grant = ce && req && (tokens != 4'd0);
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];
   wire       commit   = rf_s4[4];
   wire [3:0] target   = rf_s4[3:0];

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
        grant_q    = 1'b0;
       rf_s1      = 5'd0;
       rf_s2      = 5'd0;
       rf_s3      = 5'd0;
       rf_s4      = 5'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
            grant_q    <= 1'b0;
           rf_s1      <= 5'd0;
           rf_s2      <= 5'd0;
           rf_s3      <= 5'd0;
           rf_s4      <= 5'd0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

           // stage the refill: capture the clamped target at the tick and
           // walk it down the pipeline, one stage per enabled cycle
           rf_s1 <= {tick, refilled};
           rf_s2 <= rf_s1;
           rf_s3 <= rf_s2;
           rf_s4 <= rf_s3;

            if (tick)
                saw_refill <= 1'b1;

           case ({commit, do_grant})
               2'b10:   tokens <= target;
                2'b01:   tokens <= tokens - 4'd1;
               2'b11:   tokens <= (target == 4'd0) ? 4'd0 : (target - 4'd1);
                default: tokens <= tokens;
            endcase
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;
   // second request slot: a further transfer queued behind the one in flight,
   // sharing the single beat engine below
   reg [3:0] q_len;
   reg       q_valid;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;
   initial q_len    = 4'd0;
   initial q_valid  = 1'b0;

    wire accept = start && !armed && (len != 4'd0);

   // the length shadow is only four bits wide, so an append is refused unless
   // the combined transfer still fits in it
   wire [4:0] q_sum = {1'b0, req_len} + {1'b0, len};
   wire enq = start && !q_valid && (len != 4'd0) && !q_sum[4];

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                beats    <= len;
                req_len  <= len;      // shadow capture of the earlier event
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
               q_valid  <= 1'b0;   // a fresh burst flushes a stale append
            end else if (busy) begin
                beats    <= beats - 4'd1;
                done_cnt <= done_cnt + 4'd1;
                busy     <= (beats != 4'd1);
               if (enq) begin
                   q_valid <= 1'b1;
                   q_len   <= len;
               end
           end else if (armed && q_valid) begin
               // the queued transfer reuses the engine that just drained and
               // is appended to the still-open window, so the delivered count
               // keeps running and the shadow length grows by the new request
               beats    <= q_len;
               req_len  <= req_len + q_len;
               busy     <= 1'b1;
               q_valid  <= 1'b0;
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);
endmodule

module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
    output wire       can_fetch
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    // a retire frees a queue slot right away, but the credit itself only
    // reaches the free pool a cycle later, through this return stage
    reg        ret_credit;


    initial used    = 4'd0;
    initial credits = DEPTH;
    initial ret_credit = 1'b0;

    assign can_fetch = (credits != 4'd0);

    wire fetch_go  = fetch && !retire && (credits != 4'd0);
    wire retire_go = retire && !fetch && (used != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
            ret_credit <= 1'b0;
        end else if (en) begin
            // queue occupancy reacts in the cycle the request is seen
            if (fetch_go)
                used <= used + 4'd1;
            else if (retire_go)
                used <= used - 4'd1;

            // the free pool gives up a slot on fetch, and only gets one
            // back when a returning credit pops out of the return stage
            if (fetch_go && !ret_credit)
                credits <= credits - 4'd1;
            else if (!fetch_go && ret_credit)
                credits <= credits + 4'd1;

            // a retire hands its credit to the return stage
            ret_credit <= retire_go;
            // simultaneous fetch+retire: slot handed straight over
        end
    end

    // P (two assertions, global scope, bounded existence at most 12):
    // neither counter can ever exceed the queue depth, which is strictly
    // smaller than what their 4-bit width admits.
    always @(posedge clk) begin
        assert (used <= DEPTH);
        assert (credits <= DEPTH);
    end
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
   // issue stage: an accepted launch is parked here for one cycle before it
   // enters stage 0 of the array
   reg              ld_pend;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;
    // backpressure: while the array is draining no further launch is accepted
    reg              draining;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
   initial ld_pend = 1'b0;
    initial armed   = 1'b0;
    initial started = 1'b0;
    initial draining = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire launch_ok = i_launch && armed && !draining;
    wire accept = i_ce && launch_ok;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
           ld_pend <= 1'b0;
            armed   <= 1'b0;
            started <= 1'b0;
    draining <= 1'b0;
        end else if (i_ce) begin
           ld_pend <= launch_ok;
           pipe    <= { pipe[STAGES-2:0], ld_pend };
           cnt     <= cnt + (ld_pend          ? 3'd1 : 3'd0)
                          - (pipe[STAGES-1]   ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
    started <= started || launch_ok;
    // enter drain mode when every stage is occupied, leave it as the
    // last outstanding request retires
           draining <= draining ? !((cnt == 3'd1) && pipe[STAGES-1])
                                : ((cnt == 3'd4) ||
                                   ((cnt == 3'd3) && ld_pend));
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

    // Backpressure sanity: drain mode is only ever held while a request was
    // really launched and work is still moving through the stage array.
    always @(posedge clk)
        if (draining)
            assert (started && (pipe != {STAGES{1'b0}}));

endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
output wire [3:0] o_gnt,
output reg [3:0]  req_hist
);
    // Latency budget granted to an accepted request.
    localparam [2:0] BUDGET = 3'd5;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
    wire retire = gnt_valid && (done || ((elapsed == 3'd4) && (timer == 3'd1)));

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;
initial req_hist  = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
req_hist  <= 4'd0;
        end else if (i_ce) begin
req_hist <= {req_hist[2:0], (|req) & ~done};
            if (!gnt_valid) begin
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                    timer     <= BUDGET;   // credits left
                    elapsed   <= 3'd0;     // cycles burnt
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
output reg  [7:0] out_data,
output reg  [3:0] xfer_count
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;
reg  [7:0] shadow_data;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
xfer_count  = 4'd0;
shadow_data = 8'h00;
    end

    assign in_ready = !skid_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
            armed      <= 1'b0;
xfer_count  <= 4'd0;
shadow_data <= 8'h00;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else if (in_valid) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
                // downstream stalled: park the incoming word in the skid slot
                if (in_valid && !skid_valid) begin
                    skid_data  <= in_data;
                    skid_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

            if (accept) armed <= 1'b1;
if (accept) shadow_data <= in_data;
if (drain)  xfer_count  <= xfer_count + 4'd1 + {3'b000, shadow_data[7]};
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
output wire [2:0] o_inflight,
output reg  [3:0] o_issue_hist,
output reg  [3:0] o_act_cnt
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// distractor: history of raw issue requests (not tied to occupancy)
reg [3:0] req_hist;
// distractor: raw retire-pulse accumulator, unrelated to occupancy
reg [3:0] ce_cnt;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial req_hist     = 4'b0000;
initial o_issue_hist = 4'b0000;
initial ce_cnt       = 4'b0000;
initial o_act_cnt    = 4'b0000;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
req_hist     <= 4'b0000;
o_issue_hist <= 4'b0000;
ce_cnt       <= 4'b0000;
o_act_cnt    <= 4'b0000;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
req_hist     <= {req_hist[2:0], issue};
o_issue_hist <= req_hist ^ {3'b000, issue};
ce_cnt       <= ce_cnt + {3'b000, retire};
o_act_cnt    <= ce_cnt ^ {3'b000, issue};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
output wire o_mon,
output reg [3:0] o_act
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

   // the issue count feeds the status comparator through four retiming
   // registers; the raw counter is too far from the compare logic to make
   // timing in one cycle, so the compare now sees a 4-cycle-old copy
   reg [4:0] iss_d1;
   reg [4:0] iss_d2;
   reg [4:0] iss_d3;
   reg [4:0] iss_d4;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
   initial iss_d1  = 5'd0;
   initial iss_d2  = 5'd0;
   initial iss_d3  = 5'd0;
   initial iss_d4  = 5'd0;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
           iss_d1  <= 5'd0;
           iss_d2  <= 5'd0;
           iss_d3  <= 5'd0;
           iss_d4  <= 5'd0;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
           empty_q <= (iss_d4 == ret);
           iss_d1  <= iss;
           iss_d2  <= iss_d1;
           iss_d3  <= iss_d2;
           iss_d4  <= iss_d3;
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request

   // credit pipeline: a refill tick becomes a credit that walks four stages
   // before it reaches the bucket's refill port
   reg       rfc_s1, rfc_s2, rfc_s3, rfc_s4;

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;
   initial rfc_s1   = 1'b1;   // reset in phase with the timer: credit just issued
   initial rfc_s2   = 1'b0;
   initial rfc_s3   = 1'b0;
   initial rfc_s4   = 1'b0;

    wire tick     = (tick_cnt == 2'd0);
    wire do_grant = pending && (tokens != 3'd0);
   wire refill   = rfc_s4;   // credit landing at the bucket this cycle

    assign grant   = i_ce && do_grant;
    assign expired = pending && (deadline == 4'd0);

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

   // one credit per stage, in flight between the timer and the bucket
   always @(posedge clk) if (i_ce) begin
       rfc_s1 <= tick;
       rfc_s2 <= rfc_s1;
       rfc_s3 <= rfc_s2;
       rfc_s4 <= rfc_s3;
   end

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
       if (do_grant && refill)
            tokens <= tokens;                 // one out, one in
        else if (do_grant)
            tokens <= tokens - 3'd1;
       else if (refill && (tokens < BURST))
            tokens <= tokens + 3'd1;
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
output reg  o_level,   // last popped debounced level
output reg [3:0] o_pop_tally   // diagnostic: mixed pop tally (non-functional)
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

   // ---- event ledger: free-running push/pop transfer counters ----
   // flag generation is taken from the ledger difference so that empty/full
   // are a direct function of logged transfers rather than of the occupancy
   // accumulator; the counters wrap naturally at their width.
   reg [2:0] n_push, n_pop;
   wire [2:0] occ = n_push - n_pop;   // outstanding entries, mod 8

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

   // ---- diagnostic pop tally (observability only) ----
   reg [3:0] pop_tally;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
       n_push = 3'd0; n_pop = 3'd0;
        never_full = 1'b1;
        pv = 1'b0;
       pop_tally   = 4'd0;
       o_pop_tally = 4'd0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

   assign empty = (occ == 3'd0);
   assign full  = (occ == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

           // log both sides of every completed transfer
           if (do_push) n_push <= n_push + 3'd1;
           if (do_pop)  n_pop  <= n_pop  + 3'd1;

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

   // diagnostic-only: counts completed pops and publishes a mixed view of it
   always @(posedge clk) begin
       if (i_ce) begin
           if (do_pop) pop_tally <= pop_tally + 4'd1;
           o_pop_tally <= pop_tally ^ {3'b000, raw};
       end
   end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // Load/sample ledger: every load pulse and every sample pulse is logged
    // for the lifetime of the current alignment, so the buffer downstream can
    // account for the two divided enables it sees.
    reg  [3:0] n_load;   // count of load pulses issued
    reg  [3:0] n_samp;   // count of sample pulses issued

    // samples that do not have a matching load behind them yet
    wire [3:0] samp_ahead = n_samp - n_load;
    // a realignment can leave the ping-pong buffer starved; while the sample
    // side is two or more entries ahead, inject make-up load pulses
    wire       makeup     = (samp_ahead >= 4'd2);

   // Load-side stall watchdog: the sink downstream must never be left
   // without a load pulse for long, so the gap since the last one is timed
   // and a make-up pulse is forced once that gap gets too wide.
   reg  [2:0] gap;      // enabled cycles since the last load pulse
   wire       wdog       = (gap >= 3'd6);
   wire       load_pulse = (phase == 3'd4) || makeup || wdog;

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;
   initial gap       = 3'd0;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
           gap       <= 3'd0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
           en_load   <= load_pulse;
            en_sample <= (cnt   == 3'd4);
            // ledger entries are made as the pulses are issued
           n_load    <= n_load + (load_pulse ? 4'd1 : 4'd0);
            n_samp    <= n_samp + ((cnt == 3'd4) ? 4'd1 : 4'd0);
           gap       <= load_pulse ? 3'd0 : gap + 3'd1;
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

   // Alignment: while the divider has never been resynced, the sample pulse
   // always lands three enabled cycles into the current load window.
   always @(posedge clk)
       if (pristine)
           assert (!en_sample || (gap == 3'd3));

endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
   reg [3:0] lim;   // per-literal escape budget; escapes past it are not retired
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;

    initial st  = 5'b00001;
    initial cnt = 4'd0;
   initial lim = 4'd8;
    initial arm = 1'b0;
    initial pv  = 1'b0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

    reg [4:0] nst;
    reg [3:0] ncnt;
   reg [3:0] nlim;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
       nlim = lim;
        if (st[S_IDLE]) begin
            if (is_q) begin
                nst  = 5'b01000;   // open quote: enter string, fresh escape count
                ncnt = 4'd0;
           end else if (is_dig) begin
               nst  = 5'b00100;
               nlim = i_char[3:0];   // leading digit also programs the escape budget
           end
            else if (is_alp)
                nst = 5'b00010;
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
        end else if (st[S_STR]) begin
            if (is_q) begin
                nst  = 5'b00001;   // close quote: escape count retired
               ncnt = (cnt > lim) ? (cnt - lim) : 4'd0;   // debit one budget worth
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
           ncnt = (cnt >= lim) ? lim : (cnt + 4'd1);
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
           lim <= 4'd8;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
           lim <= nlim;
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
// Pseudo-random hall-call source.  The shift chain and its feedback XOR
// are split across two flops: the tap is evaluated one cycle ahead into
// lf_fb and shifted in on the next enabled step, which keeps the XOR
// gate out of the shift path.  Taps are chosen so that the combined
// 5-bit generator state {lf, lf_fb} is maximal length (period 31).
reg lf_fb;

initial lf_fb   = 1'b0;
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;

wire       lf_fb_next = lf[3] ^ lf[1];
wire [3:0] lf_next    = {lf[2:0], lf_fb};

// A pseudo-random hall call is issued unless the top three shift
// stages of the generator are all zero.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    wire [3:0] set_mask   = new_call ? (4'b0001 << call_floor) : 4'b0000;
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
lf_fb   <= 1'b0;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
        end else if (step) begin
            lf      <= lf_next;
lf_fb   <= lf_fb_next;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= new_call ? 3'd0 : (dry_cnt + 3'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);
endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
    output reg        armed    // sticky: set the first time a request is taken
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

   // Banked grant position: the half-select bit is registered on its own, so
   // the aging path is an offset toggle plus a bank carry rather than a full
   // 2-bit incrementer feeding the index register.
   reg  bank;                         // 0: grant sits in req[1:0], 1: req[3:2]
   wire nxt_bank = bank ^ idx[0];     // rotation carries out of the current bank


    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
       bank   = 1'b0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // accept a new request: index and one-hot come from the encoder
                vld   <= 1'b1;
                idx   <= enc;
                oh    <= iso;
               bank  <= enc[1];
                armed <= 1'b1;
            end else if (vld) begin
                // no new request: age the standing grant round-robin style
               // advance one slot: the offset toggles, the bank takes the carry
               idx  <= {nxt_bank, ~idx[0]};
               bank <= nxt_bank;
                oh  <= {oh[2:0], oh[3]};
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
    output reg        done
);
    localparam [3:0] MAXSTEP = 4'd10;
   localparam [3:0] PASS1   = 4'd6;   // steps budgeted to the first pass

   // second-pass budget, parked out of the live countdown until pass one ends
   reg [3:0] credit;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
       credit   = 4'd0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
    wire last     = (progress + 4'd1 >= MAXSTEP);
   wire refill   = (deadline <= 4'd1) && (credit != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
           credit   <= 4'd0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
           deadline <= PASS1;             // pass one runs on its own budget
           credit   <= MAXSTEP - PASS1;   // remainder held back for pass two
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
        end else if (step) begin
            // saturating up-counter: clamps at MAXSTEP, never reaches 4'd15
            progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
           if (refill) begin
               // pass one spent: hand the reserve to the live countdown
               deadline <= credit;
               credit   <= 4'd0;
           end else begin
               deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;
// Booking is two-phase: the arbiter parks its winner in gnt_p, and the seat
// is charged to the pool on that board's next enabled cycle. The parking
// station holds one grant, so the arbiter stalls while it is occupied.
reg  [5:0] gnt_p;
wire       p_any = |gnt_p;
wire [5:0] book  = gnt_p & ce;   // parked grant commits on the owner's step

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
wire [5:0] req = window & ~hold & ~gnt_q & ~gnt_p & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
wire [3:0] inflight    = {3'b0, p_any} + {3'b0, q_any};
wire       have_credit = (pool > inflight);
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

wire [5:0] gnt     = (have_credit && !p_any) ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
gnt_p = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
gnt_p <= 6'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
gnt_q <= book;
gnt_p <= (gnt_p & ~book) | gnt;
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
output wire       o_busy,
output wire [3:0] o_nspend,  // ledger: credits handed to the link (wraps)
output wire [3:0] o_nret,    // ledger: credits taken back (wraps)
output wire       o_phase,   // which link slot the collector is in
output wire       o_rdy,     // collector has a return slot open
output wire [3:0] o_ngrant,  // ledger: return slots opened (wraps)
output wire [3:0] o_nuse     // ledger: return slots consumed (wraps)
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted
reg [3:0] n_spend;  // event ledger: credits spent on bursts
reg [3:0] n_ret;    // event ledger: credits returned by the collector
reg       phase;    // half-rate return link: credits only come back on return slots
reg       rdy;      // a return slot is open and not yet used
reg [3:0] n_grant;  // event ledger: return slots opened by the collector
reg [3:0] n_use;    // event ledger: return slots consumed by a credit

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;
initial rdy = 1'b0;
initial n_grant = 4'd0;
initial n_use = 4'd0;

    wire send_ok = i_send && (avail >= 4'd3);
wire grant   = !phase && !rdy;                  // collector opens the next return slot
wire retire  = (outst != 4'd0) && phase && rdy;  // a credit comes back in an open slot

    assign o_busy = (outst != 4'd0);
assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;
assign o_rdy    = rdy;
assign o_ngrant = n_grant;
assign o_nuse   = n_use;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
rdy <= 1'b0;
n_grant <= 4'd0;
n_use <= 4'd0;
        end else if (i_ce) begin
phase <= ~phase;             // link alternates send / return slots
if (send_ok) n_spend <= n_spend + 4'd3;
if (retire)  n_ret   <= n_ret   + 4'd1;
if (grant) begin
    rdy     <= 1'b1;         // slot opens during the send half-period
    n_grant <= n_grant + 4'd1;
end else if (retire) begin
    rdy   <= 1'b0;           // slot consumed by the returning credit
    n_use <= n_use + 4'd1;
end
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
timer <= 4'd15;         // deadline: half-rate return of up to 8 credits
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
output reg  [7:0] o_data,
output reg  [3:0] o_beat_count
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [7:0] skid;       // buffered word (meaningful only while stall)
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

    initial begin
        stall    = 1'b0;
        skid     = 8'h00;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
o_beat_count = 4'd0;
    end

    assign o_ready = !stall;

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid     <= 8'h00;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
o_beat_count <= 4'd0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid     <= i_data;
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid;
                    acc_par  <= skid_par;
                end
            end
if (i_ce) begin
    o_beat_count <= o_beat_count + 4'd1;
end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

endmodule

module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

   // Lane B is the second scheduler quantum lane. To save area the two
   // lanes time-share one binary shadow and one increment/encode
   // datapath: the owner named by `turn` uses `bin`, the parked lane's
   // shadow waits in `bin_hold`, and the pair swaps on every tick.
   reg [3:0] gray_b   = 4'b0000;
   reg [3:0] bin_hold = 4'd0;
   reg       turn     = 1'b0;   // 0: lane A owns the shared shadow

   wire [3:0] gray_sel = turn ? gray_b : gray;

   wire       wrap    = (gray_sel == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
           gray_b   <= 4'b0000;
           bin_hold <= 4'd0;
           turn     <= 1'b0;
        end else if (i_ce) begin
           // the lane owning the datapath advances its gray word, then
           // the shared shadow is handed over to the other lane
           if (turn) gray_b <= bin_nxt ^ (bin_nxt >> 1);
           else      gray   <= bin_nxt ^ (bin_nxt >> 1);
           bin      <= bin_hold;
           bin_hold <= bin_nxt;
           turn     <= ~turn;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
// 3-deep shift register feeding a registered writeback stage:
// bit k = op issued k advances ago
reg [2:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;
// registered result stage: the final latency slot lives here
reg       wb;
// second beat of the narrow result bus; the pipe cannot advance during it
reg       beat;
// credit-based issue throttle: free slots in the 4-stage result path
reg [2:0] credit;

initial pipe  = 3'b000;
    initial occ   = 3'd0;
    initial armed = 1'b0;
initial wb    = 1'b0;
initial beat  = 1'b0;
initial credit = 3'd4;
wire adv = i_ce && !beat;
// an issue is only taken when the unit still has a free slot
wire acc = issue && (credit != 3'd0);

assign o_retire = adv && wb;
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
credit <= 3'd4;
end else begin
if (adv) begin
pipe <= {pipe[1:0], acc};
wb   <= pipe[2];
occ    <= occ    + (acc ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
credit <= credit - (acc ? 3'd1 : 3'd0) + (wb ? 3'd1 : 3'd0);
if (acc)
                armed <= 1'b1;
end
if (i_ce)
beat <= !beat && wb;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);

   // P2: a result waiting in writeback means the credit pool is not full.
   always @(posedge clk)
       assert (!wb || credit <= 3'd3);
endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
    output wire       o_period_start
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start
    reg [3:0] duty_stg;  // prefetched duty feeding the compare path

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;
    initial duty_stg  = 4'd0;

    wire wrap = (cnt == PERIOD_M1);
    wire prefetch = (cnt == PERIOD_M1 - 4'd1);
    // the duty pipeline is already latched during the last two cycles of a
    // period, so a request arriving there is deferred to the next period
    wire duty_hold = prefetch || wrap;

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            // prefetch one cycle ahead of the boundary so the cnt<duty
            // compare gets a full cycle of setup on the new duty value
            if (prefetch)
                duty_stg <= duty_pend;
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
    duty_act <= duty_stg;
                hi_left  <= duty_pend;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
    if (load && !duty_hold)
                duty_pend <= duty_in;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module elastic_tag_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,      // Q: opens the observation window
    input  wire       stop,       // R: closes the observation window
    input  wire       push,
    input  wire       pop,
    input  wire [3:0] din,
    output wire [3:0] head_data,
    output wire       head_valid,
output wire       marked_seen,
output reg [3:0] push_count
);
    // two-entry elastic buffer: one valid flag per slot, head/tail flags,
    // plus an occupancy counter that mirrors the flags
    reg [1:0] cnt;
    reg       hp, tp;      // head flag / tail flag
    reg       v0, v1;      // per-slot occupancy flags
    reg [3:0] mem0, mem1;

    // window + shadow register for the precedence check
    reg       win;
    reg       seen_hi;
reg       pop_toggle;

    initial begin
        cnt     = 2'd0;
        hp      = 1'b0;
        tp      = 1'b0;
        v0      = 1'b0;
        v1      = 1'b0;
        mem0    = 4'd0;
        mem1    = 4'd0;
        win     = 1'b0;
        seen_hi = 1'b0;
push_count = 4'd0;
pop_toggle = 1'b0;
    end

    // a window may only be opened on an empty buffer; it may be reopened
    wire start_acc = start && !win && (cnt == 2'd0);
    wire stop_acc  = stop && win && !start_acc;

    wire do_push = push && !start_acc && (cnt != 2'd2);
    wire do_pop  = pop  && !start_acc && (cnt != 2'd0);

    assign head_valid  = hp ? v1   : v0;
    assign head_data   = hp ? mem1 : mem0;
    assign marked_seen = seen_hi;

    always @(posedge clk) begin
        if (rst) begin
            cnt     <= 2'd0;
            hp      <= 1'b0;
            tp      <= 1'b0;
            v0      <= 1'b0;
            v1      <= 1'b0;
            win     <= 1'b0;
            seen_hi <= 1'b0;
push_count <= 4'd0;
pop_toggle <= 1'b0;
        end else begin
            if (do_push) begin
                if (tp) begin
                    mem1 <= din;
                    v1   <= 1'b1;
                end else begin
                    mem0 <= din;
                    v0   <= 1'b1;
                end
                tp <= ~tp;
            end

            if (do_pop) begin
                if (hp) v1 <= 1'b0;
                else    v0 <= 1'b0;
                hp <= ~hp;
            end

            cnt <= cnt + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);

            if (start_acc) begin
                win     <= 1'b1;
                seen_hi <= 1'b0;
            end else if (stop_acc) begin
                win     <= 1'b0;
            end else if (do_push && win && din[3]) begin
                seen_hi <= 1'b1;
            end
if (do_pop) begin
    pop_toggle <= ~pop_toggle;
end
if (do_push) begin
    push_count <= push_count + 4'd1;
end else if (pop_toggle) begin
    push_count <= push_count ^ 4'd3;
end
        end
    end

    // Precedence, inside the window: a marked item can only be observed at the
    // head if a marked item was pushed earlier in this same window.
    assert property (!win || !head_valid || !head_data[3] || seen_hi);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam [2:0] M = 3'd3;  // samples counted by the run counter
   localparam [1:0] G = 2'd2;  // K - M: steps counted by the hold-off stage

    reg       samp     = 1'b0;  // last accepted raw sample
   reg [2:0] cnt      = 3'd0;  // stability run counter, saturates at M
   reg       stable_f = 1'b0;  // decoded "full K-sample count elapsed" flag
   reg [1:0] hold     = 2'd0;  // tail of the count: the K - M steps past cnt's top
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
               hold     <= 2'd0;
                stable_f <= 1'b0;
cmt_pend <= 1'b0;          // an in-flight commit is aborted
end else begin
   if (cnt != M) begin
       cnt <= cnt + 3'd1;         // the first M identical samples
   end else if (hold != G) begin
       hold <= hold + 2'd1;       // the tail of the count runs here
       if (hold == G - 2'd1) begin
           // stage the commit; the flag and output move one step later
           cmt_pend <= 1'b1;
           cmt_val  <= samp;
       end
   end
    if (cmt_pend) begin
        o_clean  <= cmt_val;   // commit the debounced value
        stable_f <= 1'b1;
        cmt_pend <= 1'b0;
    end
            end
// cnt == M and hold == G with nothing staged: saturated, everything holds

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
output wire o_busy,
output reg [3:0] o_evt_cnt
);
    localparam [3:0] TOTAL = 4'd3;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- peer chain B: second engine drawing on the same credit pool ----
    reg [3:0] armed_b;    // chain B credits spent on ARM, awaiting START
    reg [3:0] busy_b;     // chain B credits outstanding at its consumer

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    // ---- command-port ownership: both chains share one command port; it is
    //      handed to the other chain once the current owner has drained ----
    reg sel;              // 0 => chain A is served, 1 => chain B
// ---- debug-only activity trace: counts presented command strobes ----
reg [3:0] evt_hist;

    initial begin
        armed_b    = 4'd0;
        busy_b     = 4'd0;
        sel        = 1'b0;
        free_cr    = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
evt_hist   = 4'd0;
o_evt_cnt  = 4'd0;
    end

    wire do_flush = i_ce &&  i_flush;
    wire own_idle = sel ? ((armed_b  == 4'd0) && (busy_b  == 4'd0))
                        : ((armed_cr == 4'd0) && (busy_cr == 4'd0));
    wire do_swap  = i_ce && !i_flush && own_idle && !i_arm && !i_start && !i_done;

    // the port owner is the only chain that sees the command strobes
    wire do_arm   = i_ce && !i_flush && !sel && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && !sel && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && !sel && i_done  && (busy_cr  != 4'd0);

    wire do_arm_b   = i_ce && !i_flush && sel && i_arm   && (free_cr != 4'd0);
    wire do_start_b = i_ce && !i_flush && sel && i_start && (armed_b != 4'd0);
    wire do_fin_b   = i_ce && !i_flush && sel && i_done  && (busy_b  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
            free_cr    <= TOTAL;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            armed_b    <= 4'd0;
            busy_b     <= 4'd0;
            sel        <= 1'b0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
evt_hist   <= 4'd0;
o_evt_cnt  <= 4'd0;
        end else if (i_ce) begin
            free_cr  <= free_cr  - do_arm - do_arm_b + do_fin + do_fin_b;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            armed_b  <= armed_b  + do_arm_b   - do_start_b;
            busy_b   <= busy_b   + do_start_b - do_fin_b;
            if (do_swap) sel <= ~sel;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
evt_hist  <= {evt_hist[2:0], (i_arm | i_start | i_done)};
o_evt_cnt <= o_evt_cnt + {3'd0, (evt_hist[3] | i_arm | i_start | i_done)};
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0) || (busy_b != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;
   // peer chain B: shares the start unit with chain A
   // arm(line2) -> start(line3) -> finish(line1)
   reg [1:0] stage_b;
   // shared start unit is primed and not yet consumed
   reg       start_tok;
  // posted stage-update pipe: a chain A stage advance is handed to the
  // writeback pipe and only lands on the stage register four cycles later.
  // 2'd0 in a slot means "nothing posted here".
  reg [1:0] upd_p0;
  reg [1:0] upd_p1;
  reg [1:0] upd_p2;
  reg [1:0] upd_p3;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
      upd_p0     = 2'd0;
      upd_p1     = 2'd0;
      upd_p2     = 2'd0;
      upd_p3     = 2'd0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);
  // only one stage update may be outstanding in the pipe
  wire upd_busy = (upd_p0 | upd_p1 | upd_p2 | upd_p3) != 2'd0;

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
      if (i_ce) begin
          // last slot retires onto the stage register, then the pipe shifts
          if (upd_p3 != 2'd0)
              stage <= upd_p3;
          upd_p3 <= upd_p2;
          upd_p2 <= upd_p1;
          upd_p1 <= upd_p0;
          upd_p0 <= 2'd0;
      end
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                   if (gnt_c[0] && !upd_busy) begin
                       upd_p0   <= 2'd1;   // post ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                   if (gnt_c[1] && !upd_busy) begin
                       upd_p0     <= 2'd2; // post START step
                        seen_start <= 1'b1;
                  end else if (start_tok && gnt_c[2] && !upd_busy) begin
                      upd_p0     <= 2'd3; // start unit already primed: skip START
                   end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                2'd2: begin
                   if (gnt_c[2] && !upd_busy) begin
                       upd_p0 <= 2'd3;     // post FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                   start_tok  <= 1'b0;     // release shared start unit
                  upd_p0     <= 2'd0;     // nothing left to post
                  upd_p1     <= 2'd0;
                  upd_p2     <= 2'd0;
                  upd_p3     <= 2'd0;
                end
            endcase
           // peer chain B drives the same start unit from the high lines
           case (stage_b)
               2'd0: if (gnt_c[2]) stage_b <= 2'd1;   // ARM step (B)
               2'd1: if (gnt_c[3]) begin
                         stage_b    <= 2'd2;          // START step (B)
                         seen_start <= 1'b1;          // shared unit has run
                         start_tok  <= 1'b1;          // and stays primed
                     end
               2'd2: if (gnt_c[1]) begin
                         stage_b   <= 2'd3;           // FINISH step (B)
                         start_tok <= 1'b0;           // B consumes the unit
                     end
               default: stage_b <= 2'd0;              // retire B
           endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
output wire [2:0] o_count,
output reg [3:0] o_push_tally
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;
initial o_push_tally = 4'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
   wire do_skid = i_push && w_full && !s_v && !do_pop;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
o_push_tally <= 4'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
            count <= count + 3'd1;
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
               s_v   <= 1'b0;
               count <= count - 3'd1;
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
               count <= count - 3'd1;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
           count <= count + 3'd1;
       end
        // i_push = i_pop = 0 : the buffer idles, all state held
if (!i_rst && do_push)
    o_push_tally <= o_push_tally + 4'd1;
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

   // transaction ledger: one entry per chain run.  Free-running event
   // counters, they simply wrap at four bits; software reads the pair and
   // takes the difference to see whether a run is still outstanding.
   reg [3:0] n_acq;
   initial   n_acq = 4'd0;
   reg [3:0] n_rel;
   initial   n_rel = 4'd0;
   // single-slot occupancy interlock
   reg       busy;
   initial   busy = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
    wire [2:0] delta = sync1 ^ sync2;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

   // outstanding runs according to the ledger.  The chain has exactly one
   // slot, so two or more outstanding runs means the ledger and the chain
   // have diverged: abort the run just like a corrupt handshake.
   wire [3:0] outst   = n_acq - n_rel;
   wire       lgr_err = (outst > 4'd1);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           n_acq     <= 4'd0;
           n_rel     <= 4'd0;
           busy      <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;

           if (bad_ev || lgr_err) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                   if (arm_ev && !busy) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       busy    <= 1'b1;
                       n_acq   <= n_acq + 4'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
               S_FINISH:
                   // next arm toggle retires the run and recycles the chain
                   if (arm_ev) begin
                       stage     <= S_IDLE;
                       saw_arm   <= 1'b0;
                       saw_start <= 1'b0;
                       busy      <= 1'b0;
                       n_rel     <= n_rel + 4'd1;
                   end
               default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown
    reg [2:0] used  = 3'd0;     // enabled cycles this burst has been engaged
    reg       drain = 1'b0;     // extra busy cycle after a full-budget burst

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy || drain;  // hold busy one cycle longer after a slow burst

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    drain <= 1'b0;
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                    else
                        cnt   <= cnt - 3'd1;
                    used  <= used + 3'd1;   // charge the latency counter
                end
                P_ACK: begin
                    phase <= P_DROP;      // req drops, ack still high
                    used  <= used + 3'd1;
                end
                P_DROP: begin
                    phase <= P_IDLE;      // ack drops
                    busy  <= 1'b0;
                    cnt   <= 3'd4;        // rearm the deadline
                    used  <= 3'd0;
                    drain <= (used >= 3'd5); // burst ate the whole budget
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);

    // P3: a burst never stays engaged longer than the budget plus the ack tail
    always @(posedge clk)
        if (busy)
            assert (used <= 3'd5);
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;

   // peer chain tracker B: walks line2 -> line3 -> line0 and shares the
   // seen_arm / seen_start bookkeeping with tracker A. own_b marks which
   // tracker currently owns that bookkeeping.
   reg [1:0] stage_b;
   reg       own_b;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       own_b      = 1'b0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
           // tracker A is frozen while the peer tracker owns the bookkeeping
           if (!own_b)
            case (stage)
                2'd0: begin
                    if (gnt_c[0]) begin
                        stage    <= 2'd1;   // ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                    if (gnt_c[1]) begin
                        stage      <= 2'd2; // START step
                        seen_start <= 1'b1;
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                2'd2: begin
                    if (gnt_c[2]) begin
                        stage <= 2'd3;      // FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
           // peer tracker B: may only take the shared bookkeeping while
           // tracker A is idle; it releases and clears it again on line0
           if (!own_b) begin
               if (stage_b == 2'd0 && stage == 2'd0 && gnt_c[2]) begin
                   own_b    <= 1'b1;
                   stage_b  <= 2'd1;
                   seen_arm <= 1'b1;
               end
           end else begin
               case (stage_b)
                   2'd1: if (gnt_c[3]) begin
                             stage_b    <= 2'd2;
                             seen_start <= 1'b1;
                         end
                   2'd2: if (gnt_c[0]) begin
                             stage_b    <= 2'd0;
                             own_b      <= 1'b0;
                             seen_arm   <= 1'b0;
                             seen_start <= 1'b0;
                         end
                   default: begin
                             stage_b <= 2'd0;
                             own_b   <= 1'b0;
                         end
               endcase
           end
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
   // peak occupancy telemetry: high-water mark of the occupancy counter since
   // reset, sampled every cycle and read back on the data output while the
   // buffer is empty (the head slot carries no valid word then)
   reg [1:0] hwm;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
   initial hwm   = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
           hwm   <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);
           if (count > hwm)
               hwm <= count;
        end
    end

   assign dout    = v0 ? d0 : {6'b0, hwm};
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);

   // ---- property: a cycle in which the upstream credit register reported no
   // ---- free slots must leave the peak occupancy telemetry pegged at two
   always @(posedge clk)
       if (pv && !$past(rst) && $past(free) == 2'd0)
           assert (hwm == 2'd2);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;
  // read-side pointer of the same ring: one data word takes two destination
  // beats, so it advances on alternate enables.  it shares the programmable
  // ring bound with the write pointer.
  reg [3:0] cnt2;
  reg [3:0] g2;
  reg       ph;
  // the crossing lane is a single physical 4-bit bundle, so the two pointers
  // take turns on it.  the turn is handed over only at the common origin,
  // where both encoders read zero and the lane sees no step on the bundle.
  reg       own;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
      cnt2 = 4'd0;
      g2   = 4'd0;
      ph   = 1'b0;
      own  = 1'b0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);
  wire       wrap2      = (cnt2 >= lim);
  wire [3:0] nxt2       = wrap2 ? 4'd0 : cnt2 + 4'd1;
  wire [3:0] nxt_gray2  = nxt2 ^ (nxt2 >> 1);
  wire       tick2      = ph;
  wire       swap       = (cnt == 4'd0) && (cnt2 == 4'd0);
  wire [3:0] lane       = own ? g2 : g;

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
          gq  <= lane;
           s1  <= gq;
            s2  <= s1;
          ph  <= ~ph;
          if (tick2) begin
              cnt2 <= nxt2;
              g2   <= nxt_gray2;
          end
          if (swap)
              own <= ~own;
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule
